def _hq_groesse(acc):
    """Kontogröße als Bucket (25k/50k/100k/150k/200k/300k) — account_size ist nur bei
    wenigen Konten gesetzt, starting_balance öfter; nichts davon → None (nur B/C/D)."""
    for feld in ("account_size", "starting_balance"):
        try:
            v = float(acc.get(feld) or 0)
        except (TypeError, ValueError):
            v = 0
        if v >= 5000:
            return min(HQ_GROESSEN, key=lambda g: abs(g - v))
    return None


def _hq_pct(vals, p):
    """Perzentil mit linearer Interpolation (wie percentile_cont in Postgres)."""
    if not vals:
        return None
    v = sorted(vals)
    k = (len(v) - 1) * p
    lo, hi = int(k), min(int(k) + 1, len(v) - 1)
    return v[lo] + (v[hi] - v[lo]) * (k - lo)


def _hq_ohne_ausreisser(vals, begleit=None):
    """Tukey-Zaun (1,5 × IQR) je Gruppe (24.09.2026, Finn: „kannst du hier die Ausreißer weglassen").
    Ab 5 Werten; begleit = parallele Liste, die mitgefiltert wird (Reibung real). Liefert (vals, begleit)."""
    if len(vals) < 5:
        return vals, begleit
    q1, q3 = _hq_pct(vals, 0.25), _hq_pct(vals, 0.75)
    iqr = q3 - q1
    lo, hi = q1 - 1.5 * iqr, q3 + 1.5 * iqr
    idx = [i for i, v in enumerate(vals) if lo <= v <= hi]
    if len(idx) < 3:
        return vals, begleit
    return [vals[i] for i in idx], ([begleit[i] for i in idx] if begleit is not None else None)


def _hq_typ(acc):
    """Kontotyp für die Statistik. 'winning_days' (vierter Kontotyp seit 25.09.2026, sql/2026-09-25_
    accounts_winning_days.sql — ein Funded-Konto nach bestandenem Big Trade) heißt in der Statistik
    'wd', wie die Winning-Day-Trades der Hedge-Ära (Faustregel in _hq_typ_trade)."""
    t = str(acc.get("account_type") or "").strip().lower() or "—"
    # 'funded_cfd' (29.09.2026, Funded CFD getrennt von Funded Futures, sql/2026-09-29_accounts_funded_cfd.sql) zählt in der
    # Statistik weiter als 'funded' — Gruppen „Firma|funded" und HQ_ZIELE bleiben, alte Trades der 31 umgestellten
    # CFD-Konten springen nicht in eine neue Gruppe.
    return "wd" if t == "winning_days" else "funded" if t == "funded_cfd" else t


# Winning Day als eigener Typ (25.09.2026, Finn am Statistik-Tab: „bei Tradeify Funded sollte es auch grob
# 850 € sein bei dem Big Trade, aber bei den Winning Days ist es ja unterschiedlich — da muss man unterscheiden
# zwischen Funded, Winning Day und Challenge"). BEFUND in den Hedge-Ära-Daten: Funded-Trades teilen sich sauber
# am Master-Risiko — < 1.000 $ (Tradeify Ø 404 $, Slave-Risiko Ø 93 €, Quote 0,39) sind Winning Days, ≥ 3.000 $
# (Tradeify Ø 4.449 $, Slave-Risiko Ø 846 €, Quote 0,20 → 4.500 $ ≙ ~900 €) sind Big Trades; dazwischen 18 von
# 559. Die gemischte Gruppe „Tradeify · Funded" zeigte 0,363 €/$ — die Winning Days (171 Trades) haben den
# Median der Big Trades (56) überstimmt. Ein V2-Trade ohne Master-Risiko (kein SL nötig) wird über |master_pl|
# eingeordnet.
HQ_WD_RISK = 1000.0


def _hq_typ_trade(acc, plan):
    """Kontotyp je TRADE: 'wd' (Winning Day) für einen Funded-Trade mit Master-Risiko < HQ_WD_RISK
    (ohne Risiko: |master_pl|), sonst der Kontotyp. Nur für die Quoten-/Reibungs-Gruppen und die
    Statistik-Ausgabe — an den Konten selbst ändert sich nichts.
    Seit 25.09.2026 zählt der Kontotyp ZUM ZEITPUNKT des Trades (trade_plans.konto_typ, sql/2026-09-25_trade_plans_konto_typ.sql):
    Mikes Funded-Trade 2ff62bb5 lief als Winning Day, weil sein Konto Stunden später auf 'winning_days' umgestellt wurde.
    Ohne konto_typ (Spalte fehlt / Altbestand) wie bisher der heutige Kontotyp."""
    kt = str((plan or {}).get("konto_typ") or "").strip().lower()
    typ = ("wd" if kt == "winning_days" else "funded" if kt == "funded_cfd" else kt) if kt else _hq_typ(acc)
    # Kontotyp 'winning_days' (25.09.2026) schlägt alles: jeder Trade auf so einem Konto ist ein Winning Day —
    # der Erledigt-Haken und die Risiko-Faustregel gelten nur noch für Konten, die (noch) 'funded' heißen
    # (Hedge-Ära-Bestand, dessen Konten damals nicht umgestellt waren).
    if typ == "wd":
        return "wd"
    # Ausdrückliche Markierung (sql/2026-09-25_trade_plans_winning_day.sql, Erledigt-Haken / Farmer) schlägt
    # die Faustregel: true → Winning Day, false → Big Trade / Kontotyp; nur null (Bestand) wird geschätzt.
    wd = plan.get("winning_day")
    if wd is True:
        return "wd"
    if wd is False or typ != "funded":
        return typ
    try:
        risk = float(plan.get("master_risk") or 0)
        if risk <= 0:
            risk = abs(float(plan.get("master_pl") or 0))
    except (TypeError, ValueError):
        risk = 0
    return "wd" if 0 < risk < HQ_WD_RISK else typ


def _hq_anteil(typ):
    """Realer Anteil der gemessenen Reibung: Funded (Fixgröße) 1,0, sonst (Gesamtkosten) 0,5.
    BEFUND 25.09.2026: wird von der Reibungs-Auswertung nicht mehr aufgerufen — der Anteil kommt seit
    .490 gemessen je Gruppe (_anteil_aus) mit Rückfall auf den globalen Messwert, nie aus dem Typ.
    Bleibt als Vorgabe stehen; 'wd'/'winning_days' zählen wie Funded (Fixgröße, kein Kaufpreis-Anteil)."""
    return HQ_REIB_ANTEIL_FUNDED if str(typ or "").strip().lower() in ("funded", "wd", "winning_days") else HQ_REIB_ANTEIL_SONST


def _cfd_wurzel(sym):
    """Wurzel eines CFD-Symbols aus firm_specs.symbol (24.09.2026, Finn: Symbol „—" bei Echo V2
    soll „CFD · Echo V2" heißen — Wurzel aus dem Firmen-Standard, falls greifbar):
    'US100.cash' → 'US100', 'NAS100' → 'NAS100', 'XAUUSD' → 'XAUUSD', leer → ''."""
    t = str(sym or "").strip().upper()
    if not t:
        return ""
    return re.split(r"[.\s_-]", t, 1)[0] or t


def _hq_keys(acc, plan=None):
    """Die vier Gruppenschlüssel eines Master-Kontos, in Auflösungs-Reihenfolge A→B→C→D.
    Mit plan wird der Typ je Trade bestimmt (Winning Day = 'wd', siehe _hq_typ_trade)."""
    firm = _firm_norm(acc.get("firm"))
    typ = _hq_typ_trade(acc, plan) if plan is not None else _hq_typ(acc)
    g = _hq_groesse(acc)
    keys = []
    if g:
        keys.append(("A", f"{firm}|{typ}|{g}", firm, typ, g))
    keys.append(("B", f"{firm}|{typ}", firm, typ, None))
    keys.append(("C", firm, firm, None, None))
    keys.append(("D", "*", None, None, None))
    return keys


def _admin_hedge_quoten(plans, by_id, live_ids, fx, real_flags=None, real_kats=None):
    """Quoten je Gruppe aus allen abgeschlossenen Hedge-Trades. Rein: Slave live, beide P&L
    vorhanden und ≠ 0, keine Platzhalter ±1, 0 < q < 5 (Ausreißer raus). Zusätzlich die
    GEPLANTE Quote r = slave_risk € / master_risk $ als Vergleich (median_r).
    Reibung (24.09.2026) im selben Lauf, eigene Filter (beide Risiken > 0, |Abw.| ≤ 100 €).
    → (gruppen, lookup, reib_gruppen, reib_lookup, reib_global) — reib_global = {median, mean,
    real_median, real_mean, n} über alle sauberen Reibungs-Trades (Vorbelegung des Eingabefelds)."""
    samm = {}
    reib = {}
    reib_alle = []
    real_flags = real_flags or {}
    real_kats = real_kats or {}
    verlauf = []     # (Datum, Kosten, Kategorie) je sauberem Trade — Verlaufs-Chart (25.09.2026)
    for p in plans:
        if str(p.get("route") or "") not in HQ_ROUTEN:
            continue
        if str(p.get("slave_account_id")) not in live_ids:
            continue
        try:
            mpl = float(p.get("master_pl")); spl = float(p.get("slave_pl"))
        except (TypeError, ValueError):
            continue
        if not mpl or not spl or abs(mpl) == 1 or abs(spl) == 1:
            continue
        sl = by_id.get(str(p.get("slave_account_id"))) or {}
        spl_eur = spl if _firm_norm(sl.get("firm")) == "Fusion Markets" else spl * fx
        r = None
        try:
            mr = float(p.get("master_risk") or 0); sr = float(p.get("slave_risk") or 0)
            if mr > 0 and sr > 0:
                r = sr / mr
        except (TypeError, ValueError):
            pass
        acc = by_id.get(str(p.get("master_account_id") or "")) or {}
        # Reibung je Trade (Kosten, + = Geld weg): Live-Ist gegen den perfekt symmetrischen Hedge
        if r is not None:
            kosten = -(spl_eur - (-mpl * r))
            if abs(kosten) <= HQ_REIB_MAX_ABW:
                # Reales Flag aus dem Ketten-Ausgang (25.09.2026); None = noch offen → zählt nur gemessen
                flag = real_flags.get(str(p.get("id")))
                reib_alle.append((kosten, flag))
                verlauf.append({"d": str(p.get("completed_at") or "")[:10], "k": round(kosten, 2),
                                "c": real_kats.get(str(p.get("id")), "offen")})
                # Ebene T = nur Kontotyp (25.09.2026, Finn: „alle Typen von Accounts und deren
                # Reibung bzw. Kosten") — reine Anzeige-Gruppe, löst keinen V2-Trade auf.
                t_typ = _hq_typ_trade(acc, p)
                for ebene, key, firm, typ, g in _hq_keys(acc, p) + [("T", f"typ:{t_typ}", None, t_typ, None)]:
                    e = reib.setdefault(key, {"key": key, "ebene": ebene, "firm": firm, "typ": typ, "groesse": g,
                                              "k": [], "fl": []})
                    e["k"].append(kosten)
                    e["fl"].append(flag)
        q = -spl_eur / mpl
        if not (0 < q < 5):
            continue
        for ebene, key, firm, typ, g in _hq_keys(acc, p):
            e = samm.setdefault(key, {"key": key, "ebene": ebene, "firm": firm, "typ": typ, "groesse": g,
                                      "q": [], "r": [], "sum_mpl": 0.0, "sum_spl_eur": 0.0, "abs_mpl": []})
            e["q"].append(q)
            e["abs_mpl"].append(abs(mpl))
            if r is not None:
                e["r"].append(r)
            e["sum_mpl"] += mpl
            e["sum_spl_eur"] += spl_eur
    gruppen, lookup = [], {}
    for e in samm.values():
        qs, _ = _hq_ohne_ausreisser(e["q"])
        g = {"key": e["key"], "ebene": e["ebene"], "firm": e["firm"], "typ": e["typ"], "groesse": e["groesse"],
             "n": len(qs), "n_roh": len(e["q"]),
             "median_q": round(_hq_pct(qs, 0.5), 4), "mean_q": round(sum(qs) / len(qs), 4),
             "p25": round(_hq_pct(qs, 0.25), 4), "p75": round(_hq_pct(qs, 0.75), 4),
             "median_r": (round(_hq_pct(e["r"], 0.5), 4) if e["r"] else None),
             "sum_master_pl": round(e["sum_mpl"], 2), "sum_slave_pl_eur": round(e["sum_spl_eur"], 2),
             # Typische Trade-Größe der Gruppe (Median |master_pl|, auf 50 $ gerundet) für die Beispielzeile im
             # Frontend — statt fest +7.500 $ / −2.000 $ (25.09.2026: Tradeify Big Trade ist ±4.500 $, Winning Day ~270 $)
             "bsp_usd": (round(_hq_pct(e["abs_mpl"], 0.5) / 50) * 50 if e["abs_mpl"] else None)}
        gruppen.append(g)
        lookup[g["key"]] = g
    # Vorgaben (HQ_VORGABEN): ersetzen die Gruppe des Schlüssels — Finns Zahl gilt, die Messung (n, Median)
    # reist als 'gemessen' mit und steht im Tooltip (25.09.2026; bis dahin galt: nur ohne Messung ≥ HQ_MIN_N).
    for key, v in HQ_VORGABEN.items():
        alt_g = lookup.get(key)
        firm, typ = key.split("|", 1)
        q = round(float(v["ziel_eur"]) / float(v["ziel_usd"]), 4)
        vg = {"key": key, "ebene": "B", "firm": firm, "typ": typ, "groesse": None,
              "n": 0, "n_roh": (alt_g["n_roh"] if alt_g else 0),
              "median_q": q, "mean_q": q, "p25": q, "p75": q, "median_r": None,
              "sum_master_pl": 0.0, "sum_slave_pl_eur": 0.0,
              "vorgabe": True, "ziel_usd": float(v["ziel_usd"]), "ziel_eur": float(v["ziel_eur"]),
              "gemessen": ({"n": alt_g["n"], "median_q": alt_g["median_q"], "bsp_usd": alt_g.get("bsp_usd")} if alt_g else None)}
        gruppen = [x for x in gruppen if x["key"] != key] + [vg]
        lookup[key] = vg
    gruppen.sort(key=lambda g: (g["ebene"], -g["n"], g["key"]))
    # Realer Anteil je Gruppe (25.09.2026): Σ(Kosten × Flag) / Σ Kosten über die ENTSCHIEDENEN
    # Trades (Flag 0/1), geklemmt 0…1; unter HQ_MIN_N entschiedenen Trades oder bei Σ ≤ 0 kein
    # eigener Wert → Rückfall auf die nächste Ebene (B→C→D), zuletzt global.
    def _anteil_aus(ks, fls):
        ent = [(k, f) for k, f in zip(ks, fls) if f is not None]
        summe = sum(k for k, _ in ent)
        if len(ent) < HQ_MIN_N or summe <= 0:
            return None, len(ent)
        return max(0.0, min(1.0, sum(k * f for k, f in ent) / summe)), len(ent)
    reib_global = None
    g_anteil = None
    if reib_alle:
        # Anteil aus der UNGETRIMMTEN sauberen Menge (|Abw.| ≤ 100 €, wie die Auswertung 24.09.2026);
        # der IQR-Trimm gilt nur für Median/Mittelwert je Trade.
        g_anteil, g_n_ent = _anteil_aus([k for k, _ in reib_alle], [f for _, f in reib_alle])
        ks, _fls = _hq_ohne_ausreisser([k for k, _ in reib_alle], [f for _, f in reib_alle])
        if g_anteil is None:
            g_anteil = HQ_REIB_ANTEIL_SONST
        reib_global = {"n": len(ks), "median": round(_hq_pct(ks, 0.5), 2), "mean": round(sum(ks) / len(ks), 2),
                       "anteil": round(g_anteil, 3), "n_entschieden": g_n_ent,
                       "verlauf": sorted(verlauf, key=lambda e: e["d"]),
                       "real_median": round(_hq_pct(ks, 0.5) * g_anteil, 2), "real_mean": round(sum(ks) / len(ks) * g_anteil, 2)}
    reib_gruppen, reib_lookup = [], {}
    roh = {}
    for e in reib.values():
        ks, _fls = _hq_ohne_ausreisser(e["k"], e["fl"])
        a, n_ent = _anteil_aus(e["k"], e["fl"])     # Anteil ungetrimmt, wie die Summen darunter
        roh[e["key"]] = {"key": e["key"], "ebene": e["ebene"], "firm": e["firm"], "typ": e["typ"], "groesse": e["groesse"],
                         "n": len(ks), "n_roh": len(e["k"]),
                         "median": round(_hq_pct(ks, 0.5), 2), "mean": round(sum(ks) / len(ks), 2),
                         # Summen über die saubere Menge OHNE IQR-Trimm (= die Zahlen der Auswertung 24.09.2026):
                         # gemessen gesamt, davon entschieden real / entschieden zurückgeholt / noch offen
                         "summe": round(sum(e["k"]), 2),
                         "summe_real_ent": round(sum(k for k, f in zip(e["k"], e["fl"]) if f == 1.0), 2),
                         "summe_zurueck": round(sum(k for k, f in zip(e["k"], e["fl"]) if f == 0.0), 2),
                         "summe_offen": round(sum(k for k, f in zip(e["k"], e["fl"]) if f is None), 2),
                         "n_offen": sum(1 for f in e["fl"] if f is None),
                         "anteil_eigen": a, "n_entschieden": n_ent}
    for key, g in roh.items():
        # Rückfall-Kette A→B→C→D: eigener Anteil, sonst der der nächstgröberen Gruppe, sonst global
        a, quelle = g["anteil_eigen"], "eigen"
        if a is None:
            firm, typ = g["firm"], g["typ"]
            for k2, q2 in ((f"{firm}|{typ}", "B"), (firm, "C"), ("*", "D")):
                r2 = roh.get(k2)
                if r2 and r2["anteil_eigen"] is not None and k2 != key:
                    a, quelle = r2["anteil_eigen"], f"Ebene {q2}"
                    break
        if a is None:
            a, quelle = (g_anteil if g_anteil is not None else HQ_REIB_ANTEIL_SONST), "global"
        g["anteil"] = round(a, 3)
        g["anteil_quelle"] = quelle
        g["real_median"] = round(g["median"] * a, 2)
        g["real_mean"] = round(g["mean"] * a, 2)
        # Summe real = entschieden real + offen × Anteil (Erwartung für die laufenden Ketten)
        g["summe_real"] = round(g["summe_real_ent"] + g["summe_offen"] * a, 2)
        # anteil_eigen bleibt im Dict (None = geerbt) — die Rückfall-Schleife anderer Gruppen liest es noch
        reib_gruppen.append(g)
        reib_lookup[key] = g
    reib_gruppen.sort(key=lambda g: (g["ebene"], -g["n"], g["key"]))
    return gruppen, lookup, reib_gruppen, reib_lookup, reib_global


def _hq_aufloesen(acc, lookup, plan=None):
    """Erste Gruppe mit n ≥ HQ_MIN_N in der Folge A→B→C→D — oder None (dann rechnet das
    Frontend wie vorher mit fx × 1 und kennzeichnet „ohne Quote"). Eine Vorgabe (HQ_VORGABEN,
    nur im Quoten-Lookup) zählt auf ihrer Ebene wie eine volle Gruppe."""
    for _ebene, key, _f, _t, _g in _hq_keys(acc, plan):
        g = lookup.get(key)
        if g and (g["n"] >= HQ_MIN_N or g.get("vorgabe")):
            return g
    return None


def _kapitel_liste():
    """Alle Kapitel (Tabelle kapitel, 24.09.2026) nach Beginn sortiert. Fehlt
    die Tabelle noch oder klemmt der Read → leere Liste, aber hörbar."""
    try:
        return _sb_all("kapitel", {"select": "id,key,name,von,bis,hedge,farbe,beschreibung",
                                   "order": "von.asc"})
    except Exception as e:
        print(f"[admin] ⚠️ kapitel: {type(e).__name__}: {e}", flush=True)
        return []


def _kapitel_int(v):
    """kapitel_id aus der DB als int (smallint kommt als int, null → None)."""
    try:
        return int(v) if v is not None else None
    except (TypeError, ValueError):
        return None


def _kapitel_param():
    """Query-Param ?kapitel= der Admin-Routen: fehlt oder „alle" → None (ungefiltert,
    wie vor 24.09.2026); sonst die smallint-ID. Unlesbar → ValueError."""
    v = (request.args.get("kapitel") or "").strip().lower()
    if not v or v == "alle":
        return None
    return int(v)


_kapitel_heute_cache = {"at": 0.0, "wert": None}
# Review-Finding 24.09.2026 (K20): Server (UTC), Browser (Gerätezeit) und DB (current_date UTC)
# hatten drei verschiedene „heute" — rund um Mitternacht landete ein Plan in einem anderen
# Kapitel als der PC-Chip anzeigte. Festgelegt: Asia/Dubai, Finns Betriebszeit; das Frontend
# (kapitelHeute) rechnet identisch. Der DB-Trigger bleibt bei now()::date (UTC) — er greift nur
# als Fallback für Zeilen ohne gesetztes kapitel_id, siehe Kommentar im Frontend.
KAPITEL_TZ = "Asia/Dubai"


def _kapitel_heute_iso():
    try:
        from zoneinfo import ZoneInfo
        return datetime.now(ZoneInfo(KAPITEL_TZ)).strftime("%Y-%m-%d")
    except Exception:   # pragma: no cover — zoneinfo/tzdata fehlt → UTC wie vorher
        return time.strftime("%Y-%m-%d", time.gmtime())


# Kontrafakt-Statistik 24.09.2026, Finn abends: „mach MEHR Statistik, sauber" — das Frontend soll
# Trades nach Tageszeit (Stunde in Dubai) und Haltedauer auswerten können. Die Stempel kommen aus
# Supabase mal mit „Z", mal mit „+00:00", mal ganz ohne Zone (dann UTC, wie in _push_frisch).
def _kapitel_ts(roh):
    """ISO-Stempel → aware datetime (UTC bei fehlender Zone), None wenn leer/unparsebar."""
    if not roh:
        return None
    try:
        t = datetime.fromisoformat(str(roh).strip().replace("Z", "+00:00"))
    except Exception:
        return None
    if t.tzinfo is None:
        t = t.replace(tzinfo=timezone.utc)
    return t


def _kapitel_stunde(roh):
    """Stunde 0–23 des Stempels in KAPITEL_TZ (Asia/Dubai), None ohne parsebaren Stempel.
    Dubai deshalb, weil Finns Handelstag dort läuft — UTC-Stunden würden die Session-
    Auswertung um vier Stunden verschieben."""
    t = _kapitel_ts(roh)
    if t is None:
        return None
    try:
        from zoneinfo import ZoneInfo
        return t.astimezone(ZoneInfo(KAPITEL_TZ)).hour
    except Exception:   # pragma: no cover — tzdata fehlt → UTC+4 fest (Dubai kennt keine Sommerzeit)
        return (t.astimezone(timezone.utc).hour + 4) % 24


def _kapitel_dauer_min(start_roh, ende_roh, max_tage=7):
    """Haltedauer in ganzen Minuten zwischen zwei Stempeln. None, wenn einer fehlt, das Ende vor
    dem Start liegt oder die Dauer über max_tage geht — das sind Datenfehler (nachgetragene
    Trades, hängen gebliebene Pläne), keine Trades, und sie würden jeden Ø kaputtmachen."""
    a, b = _kapitel_ts(start_roh), _kapitel_ts(ende_roh)
    if a is None or b is None:
        return None
    sek = (b - a).total_seconds()
    if sek < 0 or sek > max_tage * 86400:
        return None
    return int(round(sek / 60.0))


def _kapitel_heute():
    """Kapitel des heutigen Tages (Asia/Dubai, KAPITEL_TZ) aus der Tabelle kapitel — dieselbe
    Regel wie die DB-Funktion kapitel_fuer(d): von <= heute und (bis leer oder
    bis >= heute), bei mehreren Treffern das jüngste. 5 min gecacht (24.09.2026,
    /version wird von den PC-Panels gepollt). → {id, key, name, hedge} oder None."""
    now = time.time()
    if (now - _kapitel_heute_cache["at"]) < 300:
        return _kapitel_heute_cache["wert"]
    heute = _kapitel_heute_iso()
    wert = None
    for k in _kapitel_liste():
        von, bis = str(k.get("von") or "")[:10], str(k.get("bis") or "")[:10]
        if von and von <= heute and (not bis or bis >= heute):
            wert = {"id": _kapitel_int(k.get("id")), "key": k.get("key") or "",
                    "name": k.get("name") or "", "hedge": bool(k.get("hedge"))}
    _kapitel_heute_cache.update(at=now, wert=wert)
    return wert


def _symbol_wurzel(sym):
    """Wurzel eines Futures-Symbols für den Kapitel-Vergleich (24.09.2026):
    MNQZ6 / MNQZ2026 / MNQ1! / MNQ → 'MNQ'; NQZ6 → 'NQ'. Leer → ''."""
    s = str(sym or "").strip().upper()
    if not s:
        return ""
    s = re.sub(r"\d!$", "", s)                       # TradingView-Continuous (MNQ1!)
    m = re.match(r"^([A-Z]{1,6})[FGHJKMNQUVXZ]\d{1,4}$", s)   # Monatscode + Jahr
    if m:
        return m.group(1)
    m = re.match(r"^([A-Z]+)\d*$", s)
    return m.group(1) if m else s


def acc_balance_wahl(a, echo_bal, dup_bal):
    """REIN RECHNEND (testbar): Live-Balance eines Kontos → (balance, ccy, quelle, stand) oder (None, None, None, '').
    Rangfolge: Topstep-Sync „TSX" → MetaApi „MT5" → Echo (mt5_live) → jüngere von TradingView „TV" (tv_balance) und
    Duplikum (dup_live). 0/leer = unbekannt. Keine manuelle Balance (B8, 26.09.2026)."""
    def num(v):
        try:
            f = float(v)
            return f if f == f and f > 0 else None
        except (TypeError, ValueError):
            return None
    a = a or {}
    # Topstep Express (01.10.2026, Master-Entscheid, gemeinsame Regel ist_topstep_express): TopstepX zeigt die Balance 0-basiert —
    # 0 und negativ sind dort echte Stände, keine leeren Syncs. Der alte TSX-Sync (seit 24.09.2026 still) gilt nur, wenn er
    # nicht älter ist als die Puls-Lesung — sonst wird ein veralteter Stand ≈ Kontogröße zum „Gewinn" im Payout-Kalender.
    express = ist_topstep_express(a)
    b = num(a.get("topstep_balance"))
    tv_x = _wd_num(a.get("tv_balance")) if express else None
    if b is not None and not (tv_x is not None and str(a.get("tv_balance_at") or "") > str(a.get("topstep_last_check") or "")):
        return b, "USD", "TSX", a.get("topstep_last_check") or ""
    b = num(a.get("meta_api_balance"))
    if b is not None:
        return b, "USD", "MT5", a.get("meta_api_last_check") or ""
    login = str(a.get("external_id") or "").strip()
    hit = (echo_bal or {}).get(login)
    if hit:
        b = num(hit[0])
        if b is not None:
            return b, hit[1], "Echo", hit[2]
    tv = tv_x if express else num(a.get("tv_balance"))
    tv_at = str(a.get("tv_balance_at") or "")
    hit = (dup_bal or {}).get(login)
    dup = num(hit[0]) if hit else None
    dup_at = str(hit[2] or "") if (hit and len(hit) > 2) else ""
    if tv is not None and (dup is None or not dup_at or tv_at >= dup_at):
        return tv, "USD", "TV", tv_at
    if dup is not None:
        return dup, hit[1], "Duplikum", dup_at
    return None, None, None, ""


# ══ GEPARKTES KAPITAL NACH KONTOWERT (07.10.2026, Finn: „Neue Konten haben seit 24.09. keine Gegen-/Hedge-Kosten mehr, weil
# ohne Hedge gehandelt wird" — geparkt war bis dahin nur Kauf + Hedge − Payouts, ein frisch bestandenes Konto ohne Hedge stand
# also mit dem Kaufpreis drin). Crosscheck Finn/Master am selben Tag: Funded-Big-Trades und Winning Days laufen weiter mit
# echtem Fusion-Hedge — deren ECHTE Kosten (Kachel „Gesamtkosten" im Account-Detail, Kette Kauf + Hedge-Verluste − Hedge-Gewinne,
# z. B. Tradeify-WD 207 + 2.454,04 = 2.661,04 €) zählen voll. Regel je aktivem Konto (Kette über successorId wie c_*):
#   Wert = echte Gesamtkosten der Kette + Kontowert-Zuwachs der UNGEHEDGTEN Trades (trade_plans.ohne_hedge) aller Kettenglieder.
#   Zuwachs je ungehedgtem Trade = ap_kontowert(Balance nachher) − ap_kontowert(Balance vorher) — dieselbe Funktion wie Probelauf
#   und Kontowert-Spalte, keine zweite Rechnung. Ein gehedgter Schritt steckt schon mit seinem echten Hedge-Verlust in den Kosten
#   und bekommt KEINEN hypothetischen Zuwachs (keine Doppelzählung). Verlust-Trades ohne Hedge senken den Wert (wie ein Hedge-Gewinn).
#   Balance-Verlauf: vom aktuellen Live-Stand rückwärts über master_pl (aktives Konto), sonst vorwärts ab Kontogröße (abgelöste
#   Vorgänger, kein Live-Stand). Warum nicht „höherer von Kosten/Kontowert": bei Ketten mit echtem Fusion-Hedge nach dem 24.09.
#   (WD, Funded-Big-Trades) zählte sonst entweder der echte Hedge nicht oder der Kontowert doppelt; und einen Kontowert-Stand zum
#   24.09. gibt es nicht (keine Balance-Historie) — die Trade-Kette mit master_pl ist dagegen vollständig.
#   Raus (Finn bestätigt): Payouts der Kette ≥ Wert → im Plus, zählt weder mit noch gegen (auch nicht mit Restwert), sonst Rest.
# Geblasene/archivierte Konten: unverändert (nicht aktiv → nicht geparkt; ihre Kosten bleiben Verlust in Finanzen).
def gp_zuwachs_konto(typ, p, bal, start, trades, kauf_eur=None):
    """REIN RECHNEND (testbar): Kontowert-Zuwachs (€) der ungehedgten Trades EINES Kontos.
    typ = account_type, p = ap_kw_param(regel) oder None, bal = Live-Balance ($) oder None, start = Kontogröße als Rückfall
    (Vorwärts-Rechnung; Topstep Express 0), trades = [(master_pl $, ohne_hedge bool)] in Zeitfolge, kauf_eur = echter Kauf der Kette.
    → (zuwachs_eur, n_gerechnet, n_offen): n_offen = ungehedgte Trades ohne Wert (keine Kernwerte, Balance passt zu keiner Größe)."""
    ohne = [t for t in trades if t[1]]
    if not ohne:
        return 0.0, 0, 0
    if not p:
        return 0.0, 0, len(ohne)
    pls = [_wd_num(pl) for pl, _oh in trades]
    if bal is not None:
        b = float(bal) - sum(x for x in pls if x is not None)
    elif start is not None:
        b = float(start)
    else:
        return 0.0, 0, len(ohne)
    zuwachs, n, offen = 0.0, 0, 0
    for (pl_roh, oh), pl in zip(trades, pls):
        if pl is None:
            offen += 1 if oh else 0
            continue
        b2 = b + pl
        if oh:
            k1, k2 = ap_kontowert(typ, b, p, kauf_eur), ap_kontowert(typ, b2, p, kauf_eur)
            if k1 and k2:
                zuwachs += float(k2["wert"]) - float(k1["wert"])
                n += 1
            else:
                offen += 1
        b = b2
    return round(zuwachs, 2), n, offen


def gp_konto_geparkt(kosten, zuwachs, gezahlt):
    """REIN RECHNEND (testbar): geparkt eines aktiven Kontos. kosten = echte Gesamtkosten der Kette (Kauf + Hedge, €), zuwachs =
    Kontowert-Zuwachs ohne Hedge (€), gezahlt = Payouts der Kette (€). Wert nie unter 0. Payouts ≥ Wert (> 0) → im Plus: zählt
    gar nicht (geparkt 0, kein Gegenrechnen). → {wert, gezahlt, rest, plus, geparkt}"""
    wert = max(0.0, float(kosten or 0) + float(zuwachs or 0))
    gezahlt = float(gezahlt or 0)
    plus = gezahlt > 0 and gezahlt >= wert
    rest = wert - gezahlt
    return {"wert": round(wert, 2), "gezahlt": round(gezahlt, 2), "rest": round(rest, 2), "plus": plus,
            "geparkt": 0.0 if plus else round(max(0.0, rest), 2)}


def _gp_zuwachs_karte(accounts, archived, plans, aktive_ketten):
    """Kontowert-Zuwachs je Kettenglied für die Übersicht. aktive_ketten = {aktive_id: [ketten_ids]}. Liest Kernwerte
    (auto_plan_regeln), Balance-Spiegel (Echo/Duplikum) und echte Käufe nur, wenn es ungehedgte Trades gibt.
    → {konto_id: (zuwachs_eur, n, offen, hinweis)}"""
    by_id = {str(a["id"]): a for a in accounts}
    trades = {}
    for p in sorted(plans, key=lambda p: (str(p.get("ended_at") or p.get("completed_at") or ""), str(p.get("id") or ""))):
        trades.setdefault(str(p.get("master_account_id") or ""), []).append((p.get("master_pl"), bool(p.get("ohne_hedge"))))
    glieder = {c for k in aktive_ketten.values() for c in k if any(oh for _pl, oh in trades.get(c, ()))}
    if not glieder:
        return {}
    reg = (sb_select("auto_plan_regeln", {"select": "regeln", "id": "eq.1"}) or [{}])[0]
    firmen = (reg.get("regeln") or {}).get("firmen") or []
    echo_bal, dup_bal = _ap_balance_karten()
    kauf = _ap_kauf_echt(sorted(glieder))
    out = {}
    for c in glieder:
        a = by_id.get(c) or {}
        typ = a.get("account_type") or ""
        p = ap_kw_param(ap_regel_finden(firmen, a.get("firm")))
        # Live-Stand nur am aktiven Konto selbst; abgelöste Vorgänger rechnen vorwärts ab Kontogröße (Express ab 0)
        bal = acc_balance_wahl(a, echo_bal, dup_bal)[0] if c not in archived else None
        start = 0.0 if ist_topstep_express(a) else _wd_konto_groesse(a)
        if start is None and p and len(p.get("groessen") or []) == 1:
            start = float(p["groessen"][0])      # Name ohne „150k" (z. B. nur die Kontonummer): einzige Größe der Kernwerte
        z, n, offen = gp_zuwachs_konto(typ, p, bal, start, trades.get(c, []), kauf.get(c))
        hinweis = None
        if offen:
            hinweis = (f"keine Kernwerte für {a.get('firm') or 'diese Firma'}" if not p
                       else "Balance passt zu keiner Größe der Kernwerte" if (bal is not None or start is not None)
                       else "keine Balance und keine Kontogröße")
        out[c] = (z, n, offen, hinweis)
    return out


def admin_build_overview(kapitel_id=None):
    # KAPITEL (24.09.2026, Finn: „Ab jetzt wird es nicht mehr gegengehedgt mit
    # Realmoney … dass wir das Ganze zeitlich trennen können mit den vorherigen
    # Daten … und dass man auch in Prophos in so einem neuen Chapter alles da
    # sieht"). Kapitel 1 = Hedge-Ära (bis 23.09.2026), Kapitel 2 = Ohne Hedge.
    # Gefiltert wird ausschließlich über die SPALTE kapitel_id (Trigger setzt
    # sie nach Datum, backfilled, nie null) — sie ist die eine Wahrheit, nicht
    # created_at/completed_at/occurred_at. kapitel_id=None → alles wie bisher.
    b = _admin_basis()
    accounts, archived, preds_of, fx = b["accounts"], b["archived"], b["preds_of"], b["fx"]
    by_id, live_ids, names, disp = b["by_id"], b["live_ids"], b["names"], b["disp"]
    excluded_ids, excluded_names = b["excluded_ids"], b["excluded_names"]
    kf = {} if kapitel_id is None else {"kapitel_id": f"eq.{int(kapitel_id)}"}
    # Kapitel-Liste EINMAL lesen (24.09.2026, Vollumstieg „Ohne Hedge", Finn: „riesen
    # Umstieg — geh alles durch, Backend, jedes Einzelne"): ist das gefilterte Kapitel
    # eines ohne Hedge (kapitel.hedge = false), gibt es dort per Definition keine
    # Slave-P&L — die Hedge-Spalten werden gar nicht erst gelesen und die Hedge-
    # Formel nicht gerechnet (hedge = 0, hedge_ev leer). Spart bei Kapitel 2 die
    # teuerste Rechnung der Übersicht und liefert nie „fast 0" aus Altlasten.
    kapitel_liste = _kapitel_liste()
    kap = next((k for k in kapitel_liste if kapitel_id is not None
                and _kapitel_int(k.get("id")) == int(kapitel_id)), None)
    hedge_aus = bool(kap is not None and not kap.get("hedge"))
    # completed_at seit 23.09.2026 mit: der Personen-Verlauf (unten) braucht
    # das Datum jedes Hedge-Verlusts, die Summen-Aggregation braucht es nicht.
    # master_pl/blown/user_id seit 24.09.2026: ohne Hedge-Spalten braucht der
    # Admin etwas Sinnvolles je Zeile — Master-P&L (USD), Trades, Blows im Kapitel.
    plans_select = "master_account_id,user_id,master_pl,blown"
    if not hedge_aus:
        plans_select += ",slave_account_id,slave_pl,completed_at,hedge_eur"   # hedge_eur: Solo-Hedge ohne Slave-Konto (24.09.2026 spät)
    if kapitel_id is None:
        plans_select += ",id,ohne_hedge,ended_at"   # Geparkt nach Kontowert (07.10.2026): Trade-Folge je Konto, nur ohne Kapitel-Filter
    plans     = _sb_all("trade_plans", {"select": plans_select,
                                        "status": "eq.completed", **kf})
    # Select bewusst breiter als die Summen-Aggregation braucht (11.09.2026,
    # Finn: „man soll auch sehen, wo die ganzen Payouts ankamen"): dieselben
    # Zeilen speisen jetzt zusätzlich die Empfangs-Liste im Finanzen-Tab
    # (Person, Datum, Account, Notiz) — ein zweiter Fetch wäre doppelt.
    txs       = _sb_all("transactions", {"select": "account_id,user_id,account_name,"
                                                   "account_firm,amount,currency,occurred_at,notes",
                                         "kind": "eq.payout", **kf})
    # Accounts bleiben UNGEFILTERT (die Ketten brauchen die Vorgänger), aber
    # Kaufkosten zählen nur für Konten, die im gewählten Kapitel liegen.
    kauf_zaehlt = {str(a["id"]) for a in accounts
                   if kapitel_id is None or _kapitel_int(a.get("kapitel_id")) == int(kapitel_id)}

    # Hedge-Kosten je Master-Account: nur abgeschlossene Trades auf einen LIVE-Slave.
    # Verlust (slave_pl < 0) → Kosten +, Gewinn → Kosten −. USD→EUR wie im Frontend.
    hedge = {}
    hedge_ev = []      # Verlauf (23.09.2026): (master_id, datum, kosten_eur) je Trade
    for p in ([] if hedge_aus else plans):
        ev = _admin_hedge_ev(p, by_id, live_ids, fx)
        if ev is None:
            continue
        m, datum, eur = ev
        hedge[m] = hedge.get(m, 0.0) + eur
        hedge_ev.append(ev)

    # Master-P&L / Trades / Blows je Account und je Person im (gefilterten) Kapitel
    # (24.09.2026): USD roh, wie /admin/kapitel — Prop-Konten laufen in USD.
    # Person = Besitzer des Master-Kontos (Fallback: user_id des Plans).
    mpl_k, trades_k, blown_k = {}, {}, {}
    mpl_p, trades_p, blown_p = {}, {}, {}
    for p in plans:
        m = str(p.get("master_account_id") or "")
        acc = by_id.get(m) or {}
        puid = str(acc.get("user_id") or p.get("user_id") or "")
        trades_k[m] = trades_k.get(m, 0) + 1
        trades_p[puid] = trades_p.get(puid, 0) + 1
        if p.get("blown"):
            blown_k[m] = blown_k.get(m, 0) + 1
            blown_p[puid] = blown_p.get(puid, 0) + 1
        try:
            v = float(p.get("master_pl"))
        except (TypeError, ValueError):
            continue
        if v == v:
            mpl_k[m] = mpl_k.get(m, 0.0) + v
            mpl_p[puid] = mpl_p.get(puid, 0.0) + v

    payouts = {}
    for t in txs:
        a = str(t.get("account_id") or "")
        if not a: continue
        try: payouts[a] = payouts.get(a, 0.0) + float(t.get("amount") or 0)
        except (TypeError, ValueError): pass
    # Anzahl Payouts je Account (17.09.2026, FundedNext-Refund beim ERSTEN
    # Payout): erhaltene Buchungen + offene Anfragen (unten) — beides
    # „verbraucht" den ersten Payout, der Refund zählt dann nicht mehr.
    payout_n = {}
    for t in txs:
        a = str(t.get("account_id") or "")
        if a: payout_n[a] = payout_n.get(a, 0) + 1

    def own(aid, a=None):
        """Eigene Zahlen EINES Accounts (ohne Kette), in EUR. Kauf nur, wenn
        der Account im gewählten Kapitel liegt (24.09.2026) — Hedge/Payouts
        sind über die gefilterten Reads oben schon begrenzt."""
        a = a if a is not None else by_id.get(aid) or {}
        try: buy = float(a.get("purchase_cost") or 0) if aid in kauf_zaehlt else 0.0
        except (TypeError, ValueError): buy = 0.0
        return buy, hedge.get(aid, 0.0), payouts.get(aid, 0.0)

    def chain(aid):
        """Wie calcReingesteckdEur() im Frontend: eigene Kosten PLUS die komplette
        Vorgänger-Kette. Ein geblowter Phase-1-Account ist nicht weg — sein Geld
        steckt über den Nachfolger weiter in derselben Prop-Firma. Genau das ist
        die Zahl, die die App pro Account als „Gesamtkosten" anzeigt."""
        b, h, p, n = 0.0, 0.0, 0.0, 0
        stack, seen = [aid], {aid}
        while stack:
            cur = stack.pop()
            acc = by_id.get(cur)
            if acc is None or (acc.get("account_type") or "") == "live":
                continue
            cb, ch, cp = own(cur, acc)
            b += cb; h += ch; p += cp
            if cur != aid:
                n += 1
            for prev in preds_of.get(cur, []):
                if prev not in seen and len(seen) < 200:   # Schutz gegen Zyklen
                    seen.add(prev); stack.append(prev)
        return b, h, p, n

    def chain_ids(aid):
        """Alle Account-IDs der Kette (eigene + Vorgänger), gleiche Regel wie
        chain(). Der Personen-Verlauf in der Übersicht (23.09.2026) wählt damit
        im Ketten-Modus dieselben Ereignisse, die c_* schon summiert."""
        ids, stack, seen = [], [aid], {aid}
        while stack:
            cur = stack.pop()
            acc = by_id.get(cur)
            if acc is None or (acc.get("account_type") or "") == "live":
                continue
            ids.append(cur)
            for prev in preds_of.get(cur, []):
                if prev not in seen and len(seen) < 200:
                    seen.add(prev); stack.append(prev)
        return ids

    # Eine flache Zeile pro Account — die UI filtert/aggregiert daraus selbst
    # (Person, Firma, aktiv/archiviert). Jede Zeile trägt BEIDE Sichten:
    #   buy/hedge/payouts/parked      = nur dieser Account
    #   c_buy/c_hedge/c_payouts/c_parked = inkl. Vorgänger-Kette (= „Gesamtkosten")
    # Warum beide: über AKTIVE Accounts ist die Kettensicht richtig (das Geld der
    # abgelösten Accounts steckt weiter in der Firma). Zeigt man aktive UND
    # archivierte zusammen, würde die Kettensicht die Vorgänger doppelt zählen —
    # dort sind die Eigen-Zahlen richtig. Die UI wählt je nach Filter.
    rows = []
    for a in accounts:
        aid = str(a["id"])
        if (a.get("account_type") or "") == "live":
            continue                                   # Hedge-Broker, keine Prop-Firma
        if str(a.get("user_id")) in excluded_ids:
            continue                                   # nutzt Prophos eigenständig
        buy, hg, po = own(aid, a)
        cb, ch, cp, npred = chain(aid)
        uid = str(a.get("user_id"))
        rows.append({
            "id": aid,
            "ext": a.get("external_id") or "",
            "name": a.get("name") or "",
            "firm": _firm_norm(a.get("firm")),
            "firm_raw": (a.get("firm") or "").strip(),
            "type": a.get("account_type") or "",
            "user_id": uid,
            "person": disp.get(uid) or names.get(uid, uid[:8]),
            "person_mail": names.get(uid, ""),
            "archived": aid in archived,
            # Kapitel des Accounts (24.09.2026) — das Frontend färbt/filtert damit.
            "kapitel_id": _kapitel_int(a.get("kapitel_id")),
            # Winning-Day-Farmer (23.09.2026): nur angehakte Fundeds werden gefarmt (sql/2026-09-23_accounts_wd_farm.sql)
            "wd_farm": bool(a.get("wd_farm")),
            # created_at = Kaufzeitpunkt-Näherung (28.08.2026, „Letzte Käufe" im
            # Acc-Käufe-Tab): der Account wird beim Kauf in Prophos angelegt,
            # ein eigenes Kaufdatum-Feld gibt es nicht.
            "created": a.get("created_at") or "",
            "buy": round(buy, 2),
            "hedge": round(hg, 2),
            "payouts": round(po, 2),
            "parked": round(buy + hg - po, 2),
            "preds": npred,
            "c_buy": round(cb, 2),
            "c_hedge": round(ch, 2),
            "c_payouts": round(cp, 2),
            "c_parked": round(cb + ch - cp, 2),
            "chain_ids": chain_ids(aid),
            # Kapitel „Ohne Hedge" (24.09.2026): Master-P&L (USD), Trades und Blows
            # dieses Kontos im gefilterten Kapitel — ohne Hedge-Spalten die Kennzahl
            # der Zeile. Nur eigene Pläne, keine Kette.
            "master_pl_k": round(mpl_k.get(aid, 0.0), 2),
            "trades_k": trades_k.get(aid, 0),
            "blown_k": blown_k.get(aid, 0),
        })

    # GEPARKT NACH KONTOWERT (07.10.2026, Regel bei gp_zuwachs_konto): nur ohne Kapitel-Filter (Finn sieht immer „Alle"; im Kapitel
    # fehlen die Vorgänger-Trades) und nur für aktive Konten. gp_* je Zeile, gp_aktiv oben — ohne gp_aktiv rechnet das Frontend wie
    # bisher. Fällt das Lesen der Kernwerte/Balances aus, bleibt der Zuwachs 0 (Wert = echte Kosten) und gp_fehler sagt es.
    gp_aktiv, gp_fehler = kapitel_id is None, None
    if gp_aktiv:
        aktive = {r["id"]: r["chain_ids"] for r in rows if not r["archived"]}
        try:
            zuw = _gp_zuwachs_karte(accounts, archived, plans, aktive)
        except Exception as e:
            zuw, gp_fehler = {}, f"Kontowert nicht lesbar ({type(e).__name__}) — Wert = echte Kosten"
            print(f"[admin] ⚠️ geparkt/kontowert: {type(e).__name__}: {e}", flush=True)
        for r in rows:
            if r["archived"]:
                continue
            z = n = offen = 0
            hinweise = []
            for c in r["chain_ids"]:
                zc, nc, oc, hc = zuw.get(c, (0.0, 0, 0, None))
                z += zc; n += nc; offen += oc
                if hc and hc not in hinweise:
                    hinweise.append(hc)
            kosten = r["c_buy"] + r["c_hedge"]
            gp = gp_konto_geparkt(kosten, z, r["c_payouts"])
            r.update({"gp_kosten": round(kosten, 2), "gp_zuwachs": round(z, 2), "gp_wert": gp["wert"], "gp_gezahlt": gp["gezahlt"],
                      "gp_rest": gp["rest"], "gp_plus": gp["plus"], "gp_geparkt": gp["geparkt"], "gp_n": n, "gp_offen": offen,
                      "gp_hinweis": "; ".join(hinweise) or None})

    # VERLAUF je Person (23.09.2026, Finn: „Charts, wo man den Verlauf von jeder
    # Person farblich markiert sieht — gleiche Logik für Übersicht, Saldo und
    # Payouts erhalten"): jede Geldbewegung als datiertes Ereignis in EUR —
    #   kauf   = purchase_cost, Datum = created_at (Kaufnäherung wie „created")
    #   hedge  = Hedge-Kosten eines Trades, Datum = completed_at
    #   payout = gebuchter Payout, Datum = occurred_at, auch OHNE Account
    # Das Frontend wählt je Auswertung Ereignisse und Vorzeichen und summiert
    # je Person kumuliert. Reine Anzeige — keine Summe oben rechnet damit.
    verlauf = []
    for a in accounts:
        aid = str(a["id"]); uid = str(a.get("user_id"))
        if (a.get("account_type") or "") == "live" or uid in excluded_ids:
            continue
        if aid not in kauf_zaehlt:
            continue                                   # Kauf gehört in ein anderes Kapitel (24.09.2026)
        try: buy = float(a.get("purchase_cost") or 0)
        except (TypeError, ValueError): buy = 0.0
        datum = str(a.get("created_at") or "")[:10]
        if buy and datum:
            verlauf.append({"uid": uid, "aid": aid, "datum": datum, "art": "kauf", "eur": round(buy, 2)})
    for m, datum, eur in hedge_ev:
        acc = by_id.get(m) or {}
        uid = str(acc.get("user_id") or "")
        if not datum or not uid or uid in excluded_ids or (acc.get("account_type") or "") == "live":
            continue
        verlauf.append({"uid": uid, "aid": m, "datum": datum, "art": "hedge", "eur": round(eur, 2)})
    for t in txs:
        uid = str(t.get("user_id") or "")
        datum = str(t.get("occurred_at") or "")[:10]
        if not datum or uid in excluded_ids:
            continue
        try: amt = float(t.get("amount") or 0)
        except (TypeError, ValueError): continue
        verlauf.append({"uid": uid, "aid": str(t.get("account_id") or ""), "datum": datum, "art": "payout", "eur": round(amt, 2)})
    verlauf.sort(key=lambda e: e["datum"])

    # Payouts unterwegs (02.09.2026, Finns Wunsch: „das ich im Admin dashboard
    # dazu eine cleane übersicht habe"): alle OFFENEN Anfragen aus
    # pending_payouts über alle Personen. Zählt bewusst in keine der Summen
    # oben rein — angefragtes Geld ist noch kein Geld, es wird nur GEZEIGT.
    pending_rows = []
    try:
        for t in _sb_all("pending_payouts", {
                "select": "id,user_id,account_id,account_name,account_firm,amount,currency,"
                          "liegt_bei,requested_at,notes",
                "status": "eq.pending"}):
            uid = str(t.get("user_id"))
            if uid in excluded_ids:
                continue
            pa = str(t.get("account_id") or "")
            if pa: payout_n[pa] = payout_n.get(pa, 0) + 1
            try:
                amt = float(t.get("amount") or 0)
            except (TypeError, ValueError):
                continue
            pending_rows.append({
                "user_id": uid,
                "person": disp.get(uid) or names.get(uid, uid[:8]),
                "person_mail": names.get(uid, ""),
                "amount": round(amt, 2),
                "currency": t.get("currency") or "EUR",
                "liegt_bei": t.get("liegt_bei") or "",
                "requested_at": t.get("requested_at") or "",
                "account_name": t.get("account_name") or "",
                "account_firm": t.get("account_firm") or "",
                "notes": t.get("notes") or "",
            })
        pending_rows.sort(key=lambda r: r["requested_at"])
    except Exception as e:
        # Tabelle (noch) nicht da oder Query kaputt → Übersicht trotzdem
        # liefern, aber hörbar — nie catch-und-schweigen (Lehre aus .108).
        print(f"[admin] ⚠️ pending_payouts: {type(e).__name__}: {e}", flush=True)

    # Payouts ERHALTEN — wo sie ankamen (11.09.2026, Finns Wunsch nach dem
    # KPI „Payouts erhalten", das nur eine nackte Summe zeigt): jede gebuchte
    # payout-Buchung über alle Personen. Bewusst AUCH Buchungen ohne
    # account_id — die fehlen oben in den Account-Summen (dort braucht es
    # einen Account als Anker), sind aber trotzdem angekommenes Geld und
    # gehören in die Empfangs-Liste. Beim Pending-Flow steht die Herkunft
    # („angefragt … · lag bei …") in den Notes, die kommen mit.
    recv_rows = []
    for t in txs:
        uid = str(t.get("user_id") or "")
        if uid in excluded_ids:
            continue
        try:
            amt = float(t.get("amount") or 0)
        except (TypeError, ValueError):
            continue
        recv_rows.append({
            "user_id": uid,
            "person": disp.get(uid) or names.get(uid, uid[:8] or "—"),
            "amount": round(amt, 2),
            "currency": t.get("currency") or "EUR",
            "occurred_at": t.get("occurred_at") or "",
            "account_name": t.get("account_name") or "",
            "account_firm": t.get("account_firm") or "",
            "notes": t.get("notes") or "",
        })
    recv_rows.sort(key=lambda r: r["occurred_at"], reverse=True)   # neueste zuerst

    # NÄCHSTE PAYOUTS — Kalender (15.09.2026, Finns Wunsch: „im Admin unter
    # Payouts sehen, an welchen Tagen die nächsten Payouts angefragt werden
    # können"). Quelle ist accounts.payout_ready_at, das Finn beim Anlegen /
    # Bearbeiten eines CFD-Accounts einträgt. Archivierte Accounts und Live-
    # Broker raus, ausgeblendete Personen wie überall. Auch VERGANGENE Termine
    # bleiben drin — ein überfälliger Termin ist genau die Information, die
    # der Kalender liefern soll (angefragt = Datum wird im Frontend geleert).
    # Zwei Sorten Einträge (15.09.2026 abends, Finn: „das Gleiche für die
    # Future-Logik"): CFD mit Datum (ready_at) UND Futures-Accounts mit
    # manuell gezählten Winning Days (goal_manual, Stand = goal_done_offset,
    # ready_at leer, dafür count/target) — bei count >= target ist der Payout
    # anfragbar. Die automatische Zählung (Tages-P&L) bleibt dem Frontend
    # vorbehalten, sie bräuchte hier alle trade_plans.
    # Futures-Funded zählten seit 15.09.2026 implizit als Winning-Day-Konten (firm_specs-Lesung hier) — seit 08.10.2026 nur noch
    # Typ winning_days oder Waiting for Payout (s. payout_ready unten), die Lesung entfiel.
    # Balance je Account (15.09.2026 abends, Finn: „schreib die aktuelle
    # Balance daneben, damit man weiss, wie viel der Account hat"). Gleiche
    # Rangfolge wie die Account-Karte: Topstep-Sync → MetaApi → Duplikum-
    # Spiegel (dup_live.accounts, login = external_id; traegt balance erst
    # seit diesem Build, davor bleibt der Eintrag leer). Seit 26.09.2026 (B8) ohne manuelle Balance, dafür TradingView.
    dup_bal = {}
    try:
        for row in _sb_all("dup_live", {"select": "accounts,updated_at"}):
            for da in (row.get("accounts") or []):
                if not isinstance(da, dict) or da.get("balance") in (None, ""):
                    continue
                lg = str(da.get("login") or "").strip()
                if lg and (lg not in dup_bal or str(row.get("updated_at") or "") > str(dup_bal[lg][2] or "")):
                    dup_bal[lg] = (da.get("balance"), da.get("ccy") or "USD", row.get("updated_at") or "")
    except Exception as e:
        print(f"[admin] ⚠️ dup_live-Balances: {type(e).__name__}: {e}", flush=True)

    # Echo-Snapshot (17.09.2026, Finn: „Bei Balance wird überall 0 angezeigt —
    # du musst dich auf die Echo-Live-Balance beziehen"): die PC-Tabs pushen
    # alle 5 s master_balance nach mt5_live (master_login = external_id).
    # Jüngste Zeile je Login gewinnt. Ein eingefrorener Snapshot ist als
    # KONTOSTAND weiter richtig (Doktrin 31.08.: alt ist okay, nur nie als
    # frisch ausgeben) — deshalb wandert updated_at als balance_at mit.
    echo_bal = {}
    try:
        for row in _sb_all("mt5_live", {"select": "master_login,updated_at,"
                                                  "bal:status->>master_balance,ccy:status->>master_currency"}):
            lg = str(row.get("master_login") or "").strip()
            if not lg or row.get("bal") in (None, ""):
                continue
            at = str(row.get("updated_at") or "")
            if lg not in echo_bal or at > echo_bal[lg][2]:
                echo_bal[lg] = (row.get("bal"), row.get("ccy") or "USD", at)
    except Exception as e:
        print(f"[admin] ⚠️ mt5_live-Balances: {type(e).__name__}: {e}", flush=True)

    def _acc_balance(a):
        """(balance, ccy, quelle, stand). 0 gilt bei JEDER Quelle als unbekannt —
        ein Funded-Account steht nie auf 0, das ist der leere Sync/Default
        (17.09.2026: Topstep-Sync lieferte 0.00, die Tabelle zeigte „0 $").
        26.09.2026 (Auftrag Koordination B8, Finn nutzt die manuelle Balance nicht mehr): TradingView (accounts.tv_balance,
        Puls liest sie beim Platzieren/Nachlesen) ist Quelle „TV" — die jüngere von TV und Duplikum gewinnt (wie
        wd_konten_alle.live_balance); die manuelle accounts.balance ist KEIN Rückfall mehr → ohne Live-Wert None
        („ohne Wert" im Payout-Kalender statt eines alten Handwerts)."""
        return acc_balance_wahl(a, echo_bal, dup_bal)

    def _pnum(v):
        try:
            f = float(v)
            return f if f == f else None
        except (TypeError, ValueError):
            return None

    # Balance + Payout-Rechnungsfelder auch an die Übersichts-Zeilen (17.09.2026,
    # „Wert in Funded-Accounts"): exakt dieselbe Quelle wie der Kalender unten.
    for r in rows:
        a = by_id.get(r["id"]) or {}
        bal, ccy, src, at = _acc_balance(a)
        r.update({
            "balance": round(bal, 2) if bal is not None else None,
            "balance_ccy": ccy, "balance_src": src, "balance_at": at,
            "payout_pct": _pnum(a.get("payout_pct")),
            "payout_override": _pnum(a.get("payout_override")),
            "payouts_n": payout_n.get(r["id"], 0),
        })

    # ACCOUNTS JE FIRMA (27.09.2026, Finn: „pro Prop-Firma ALLE Accounts von ALLEN
    # IDs auf einen Blick … und falls ein Account gerade schon im Trade ist, soll
    # das leuchten"). Reine Anzeige, zählt in keine Summe: Größe, Start-Balance,
    # Payout-Datum und Archiv-Grund stehen schon im Accounts-Read von _admin_basis,
    # dazu EIN Read der offenen Pläne (status open = Trade läuft) — Master UND
    # Slave-Konto gelten als „im Trade".
    arch_info = b.get("arch_info") or {}
    offen = {}
    try:
        for p in _sb_all("trade_plans", {"select": "id,master_account_id,slave_account_id,richtung,route,"
                                                   "master_symbol,started_at,created_at",
                                         "status": "eq.open"}):
            info = {"plan_id": p.get("id"), "richtung": p.get("richtung") or "",
                    "route": p.get("route") or "", "symbol": (p.get("master_symbol") or "").strip(),
                    "seit": p.get("started_at") or p.get("created_at") or ""}
            for rolle, key in (("master", "master_account_id"), ("slave", "slave_account_id")):
                k = str(p.get(key) or "")
                if k and k not in offen:
                    offen[k] = dict(info, rolle=rolle)
    except Exception as e:
        print(f"[admin] ⚠️ offene Pläne: {type(e).__name__}: {e}", flush=True)

    # HEUTE SCHON ZU ENDE (27.09.2026 nachmittags, Finn: „rot, wenn sie heute schon
    # Stop Loss gehittet oder TP gehittet haben"): je Konto der jüngste beendete Plan
    # (review/completed) der letzten 36 h — welcher Kalendertag „heute" ist, entscheidet
    # das Frontend in Ortszeit (wie trades_heute). Ein eigenes TP/SL-Feld gibt es nicht:
    # das Vorzeichen des P&L der eigenen Seite zählt (Master: master_pl, Hedge: slave_pl),
    # blown = SL. P&L noch leer (review vor der Nachlesung) → ergebnis „ende".
    ende = {}
    try:
        seit_e = datetime.fromtimestamp(datetime.now(timezone.utc).timestamp() - 36 * 3600,
                                        tz=timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        for p in _sb_all("trade_plans", {"select": "master_account_id,slave_account_id,master_pl,slave_pl,"
                                                   "blown,ended_at,completed_at,richtung,master_symbol",
                                         "status": "in.(review,completed)",
                                         "or": f"(ended_at.gte.{seit_e},completed_at.gte.{seit_e})"}):
            at = str(p.get("ended_at") or p.get("completed_at") or "")
            for rolle, key, plk in (("master", "master_account_id", "master_pl"), ("slave", "slave_account_id", "slave_pl")):
                k = str(p.get(key) or "")
                if not k or (k in ende and ende[k]["at"] >= at):
                    continue
                pl = _pnum(p.get(plk))
                erg = "sl" if (p.get("blown") and rolle == "master") else ("tp" if (pl or 0) > 0 else "sl" if (pl or 0) < 0 else "ende")
                ende[k] = {"at": at, "pl": pl, "ergebnis": erg, "rolle": rolle, "blown": bool(p.get("blown")),
                           "richtung": p.get("richtung") or "", "symbol": (p.get("master_symbol") or "").strip()}
    except Exception as e:
        print(f"[admin] ⚠️ beendete Pläne: {type(e).__name__}: {e}", flush=True)

    # SCHON GEPLANT (30.09.2026, „Accounts je Firma" je ID — Finn: sein Bruder managt die Trades von
    # Hand und muss sehen, wo noch welcher Trade steht): EIN Read der Pläne mit status planned, je
    # Master-Konto der nächste (früheste start_um; ohne Startzeit zuletzt). Wie im_trade: keine
    # Kapitel-Regel (aktueller Zustand eines Kontos), sichtbar nur an Zeilen, die die Übersicht ohnehin
    # liefert (excluded_ids / Admin-Zugang greifen beim Zeilenaufbau). Ob der Tag schon vorbei ist,
    # entscheidet das Frontend in Ortszeit — planned_for wandert deshalb mit.
    geplant = {}
    try:
        for p in _sb_all("trade_plans", {"select": "master_account_id,start_um,route,planned_for",
                                         "status": "eq.planned"}):
            k = str(p.get("master_account_id") or "")
            if not k:
                continue
            neu = {"start_um": p.get("start_um") or "", "route": p.get("route") or "",
                   "planned_for": str(p.get("planned_for") or "")[:10]}
            alt = geplant.get(k)
            if alt is None or (neu["start_um"] and (not alt["start_um"] or neu["start_um"] < alt["start_um"])):
                geplant[k] = neu
    except Exception as e:
        print(f"[admin] ⚠️ geplante Pläne: {type(e).__name__}: {e}", flush=True)

    def _firma_felder(a, aid):
        return {"size": _pnum(a.get("account_size")),
                "start": _pnum(a.get("starting_balance")),
                "payout_at": str(a.get("payout_ready_at") or "")[:10],
                "arch_grund": (arch_info.get(aid) or {}).get("reason") or "",
                "im_trade": offen.get(aid),
                "letztes_ende": ende.get(aid),
                "geplant": geplant.get(aid),   # 30.09.2026, s. o.
                # Funded CFD „Waiting for Payout" (29.09.2026): wartet nur auf die Auszahlung, braucht keinen Trade
                "waiting_payout_since": a.get("waiting_payout_since") or None}

    for r in rows:
        r.update(_firma_felder(by_id.get(r["id"]) or {}, r["id"]))

    # Live-Konten (Hedge-Broker) stehen bewusst NICHT in rows — jede Summe der
    # Übersicht würde sie sonst mitzählen. Die Firmen-Ansicht zeigt sie trotzdem
    # als Phase „live", deshalb als eigene Liste in derselben Zeilen-Form.
    live_konten = []
    for a in accounts:
        aid, uid = str(a["id"]), str(a.get("user_id"))
        if (a.get("account_type") or "") != "live" or uid in excluded_ids:
            continue
        bal, ccy, src, at = _acc_balance(a)
        z = {"id": aid, "ext": a.get("external_id") or "", "name": a.get("name") or "",
             "firm": _firm_norm(a.get("firm")), "firm_raw": (a.get("firm") or "").strip(),
             "type": "live", "user_id": uid,
             "person": disp.get(uid) or names.get(uid, uid[:8]), "person_mail": names.get(uid, ""),
             "archived": aid in archived, "kapitel_id": _kapitel_int(a.get("kapitel_id")),
             "balance": round(bal, 2) if bal is not None else None,
             "balance_ccy": ccy, "balance_src": src, "balance_at": at}
        z.update(_firma_felder(a, aid))
        live_konten.append(z)

    payout_ready = []
    for a in accounts:
        aid = str(a["id"])
        uid = str(a.get("user_id"))
        typ = a.get("account_type") or ""
        if typ == "live" or aid in archived or uid in excluded_ids:
            continue
        # NUR WINNING DAYS + WAITING FOR PAYOUT (Finn 08.10.2026, Admin → Payouts: „nur Accounts, die auch als Typ ‚Winning Day'
        # sind, nicht alle ‚Funded' … nur Typ ‚Winning Day' oder ‚Waiting for Payout'" + „es fehlen gerade die kompletten CFD-Accounts
        # … jeder CFD-Account, der nicht mehr gehandelt wird, soll hier rein"). Bisher kamen alle Funded Futures implizit mit (75 Konten
        # in „Winning Days"), CFD mit Waiting for Payout ohne Termin gar nicht. Waiting for Payout = waiting_payout_since gesetzt
        # (wie accTypGruppe/Chip in Accounts). Einziger Leser ist der Payout-Kalender (admCalRender).
        warten = str(a.get("waiting_payout_since") or "").strip()
        if typ != "winning_days" and not warten:
            continue
        d = (a.get("payout_ready_at") or "").strip()
        manual = typ == "winning_days" or (bool(a.get("goal_manual")) and (a.get("goal_kind") or "") == "winning_days")
        try:
            target = int(a.get("goal_target") or 0)
        except (TypeError, ValueError):
            target = 0
        if manual and target <= 0:
            target = 5
        try:
            count = max(0, int(a.get("goal_done_offset") or 0))
        except (TypeError, ValueError):
            count = 0
        payout_ready.append({
            "account_id": aid,
            "user_id": uid,
            "person": disp.get(uid) or names.get(uid, uid[:8]),
            "account_name": a.get("name") or "",
            "account_firm": (a.get("firm") or "").strip(),
            "ext": a.get("external_id") or "",
            "type": a.get("account_type") or "",
            "ready_at": d[:10] if d else "",
            "wd_count": count if manual else None,
            "wd_target": target if manual else None,
            "wd_ready": bool(manual and target > 0 and count >= target),
            "waiting_since": warten[:10],
        })
        bal, ccy, src, at = _acc_balance(a)
        payout_ready[-1].update({
            "balance": round(bal, 2) if bal is not None else None,
            "balance_ccy": ccy,
            "balance_src": src,
            "balance_at": at,
            # Kaufpreis + Payout-Zähler (17.09.2026): FundedNext-Refund 150 %
            # vom Kaufpreis beim ERSTEN Payout — rechnet das Frontend.
            "buy": _pnum(a.get("purchase_cost")) or 0,
            "payouts_n": payout_n.get(aid, 0),
            # Payout-Rechnung (17.09.2026, Finn: „wie viel Geld das bei dem
            # Payout ist"): Prozent (leer = 80) und fester Betrag, beide über
            # /admin/payout-calc gesetzt. Gerechnet wird im Frontend — die
            # Größe steht im Account-Namen („100k …"), nicht in der DB.
            "payout_pct": _pnum(a.get("payout_pct")),
            "payout_override": _pnum(a.get("payout_override")),
        })
    payout_ready.sort(key=lambda r: (r["ready_at"] or "9999", r["person"], r["account_name"]))

    # TRADES HEUTE (22.09.2026, Finn: „daily so kurzen Überblick, was wir heute
    # für Trades gemacht haben, pro ID — so kleine Motivation"). Quelle sind
    # die abgeschlossenen trade_plans (completed_at zählt, wie in den
    # Rechnungen). Bewusst die letzten 48 h statt „heute" — welcher Kalendertag
    # das ist, entscheidet das Frontend in der Ortszeit des PCs; der Server
    # kennt die nicht. Master-P&L ist $ (Prop-Konten), Hedge-P&L trägt die
    # Währung der Slave-Firma (Fusion ⇒ €) — dieselbe Regel wie oben.
    # Ausgeblendete Personen wie überall. Reine Anzeige, zählt in keine Summe.
    trades_heute = []
    try:
        seit = (datetime.now(timezone.utc).timestamp() - 48 * 3600)
        seit_iso = datetime.fromtimestamp(seit, tz=timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        for p in _sb_all("trade_plans", {
                "select": "id,user_id,master_account_id,master_name,master_firm,slave_name,slave_firm,"
                          "master_pl,slave_pl,blown,completed_at,richtung,master_symbol,route",
                "status": "eq.completed",
                "completed_at": f"gte.{seit_iso}",
                "order": "completed_at.desc"}):
            uid = str(p.get("user_id") or "")
            if uid in excluded_ids:
                continue
            trades_heute.append({
                "id": p.get("id"),
                "user_id": uid,
                "person": disp.get(uid) or names.get(uid, uid[:8] or "—"),
                "account_id": str(p.get("master_account_id") or ""),
                "master_name": p.get("master_name") or "",
                "master_firm": (p.get("master_firm") or "").strip(),
                "slave_name": p.get("slave_name") or "",
                "slave_firm": (p.get("slave_firm") or "").strip(),
                "master_pl": _pnum(p.get("master_pl")),
                "slave_pl": _pnum(p.get("slave_pl")),
                "hedge_ccy": "EUR" if _firm_norm(p.get("slave_firm")) == "Fusion Markets" else "USD",
                "blown": bool(p.get("blown")),
                "completed_at": p.get("completed_at") or "",
                "richtung": p.get("richtung") or "",
                "symbol": (p.get("master_symbol") or "").strip(),
                "route": p.get("route") or "",
            })
    except Exception as e:
        # Übersicht trotzdem liefern, aber hörbar — nie catch-und-schweigen.
        print(f"[admin] ⚠️ trades_heute: {type(e).__name__}: {e}", flush=True)

    # TAGES-ÜBERBLICK „Accounts je Firma" (28.09.2026, Finn: „wie viele Trades
    # gemacht wurden, wie viele Long, wie viele Short, wie ausgeglichen"). Anders
    # als trades_heute zählt hier der START (started_at) und jeder echte Trade —
    # laufend (open), zu prüfen (review) und fertig (completed); planned ohne Start
    # nicht. 36 h Fenster, „heute" entscheidet das Frontend in Ortszeit.
    trades_start = []
    try:
        seit_s = datetime.fromtimestamp(datetime.now(timezone.utc).timestamp() - 36 * 3600,
                                        tz=timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        # Von Hand nachgetragene Trades haben kein started_at → created_at als Rückfall
        for p in _sb_all("trade_plans", {"select": "id,user_id,master_account_id,richtung,route,status,started_at,created_at",
                                         "status": "in.(open,review,completed)",
                                         "or": f"(started_at.gte.{seit_s},and(started_at.is.null,created_at.gte.{seit_s}))"}):
            uid = str(p.get("user_id") or "")
            if uid in excluded_ids:
                continue
            trades_start.append({"id": p.get("id"), "user_id": uid,
                                 "account_id": str(p.get("master_account_id") or ""),
                                 "richtung": p.get("richtung") or "", "route": p.get("route") or "",
                                 "status": p.get("status") or "", "at": p.get("started_at") or p.get("created_at") or ""})
    except Exception as e:
        print(f"[admin] ⚠️ trades_start: {type(e).__name__}: {e}", flush=True)

    people_list = sorted(
        [{"user_id": u, "name": disp.get(u) or names.get(u, u[:8]),
          "mail": names.get(u, ""),
          # Master-P&L/Trades/Blows je Person im Kapitel (24.09.2026, USD).
          "master_pl": round(mpl_p.get(u, 0.0), 2),
          "trades": trades_p.get(u, 0), "blown": blown_p.get(u, 0)}
         for u in {r["user_id"] for r in rows}],
        key=lambda p: p["name"].lower())
    firm_list = sorted({r["firm"] for r in rows})
    # ADMIN-GRUPPEN (08.10.2026): Finn (ohne Einschränkung) bekommt die Gruppen für die Filter-Chips im Admin-Kopf — Name aus
    # id_gruppen.name, nie im Code. Ein eingeschränkter Login bekommt nur seine eigene Sicht (sicht_ids), keine fremden Gruppen.
    gruppen_info = {}
    try:
        if _admin_nur_uid():
            gruppen_info = {"sicht_ids": sorted(_admin_sicht() or ()), "verwalter": _admin_verwalter(), "gruppen": []}
        else:
            gruppen_info = {"gruppen": admin_gruppen_liste(admin_gruppen_daten()),
                            "gruppe_aktiv": str(request.args.get("gruppe") or "").strip().lower() or None}
    except Exception as e:
        print(f"[admin] ⚠️ gruppen: {type(e).__name__}: {e}", flush=True)
        gruppen_info = {"gruppen": [], "gruppen_fehler": f"{type(e).__name__}"}
    # excluded_uids zusaetzlich zu den E-Mails (26.08.2026): die Flotte im
    # Frontend blendet diese Personen komplett aus und braucht dafuer die uid —
    # dup_live/mt5_live-Zeilen tragen nur user_id, keine E-Mail.
    return {**gruppen_info, "accounts": rows, "people": people_list, "firms": firm_list,
            "live_konten": live_konten,   # nur für „Accounts je Firma" (27.09.2026)
            "pending_payouts": pending_rows,
            "payouts_received": recv_rows,
            "verlauf": verlauf,
            "payout_ready": payout_ready,
            "trades_heute": trades_heute,
            "trades_start": trades_start,   # Tages-Überblick „Accounts je Firma" (28.09.2026)
            "fx_usd_eur": fx, "generated": _wt_now_iso(),
            # Geparkt nach Kontowert (07.10.2026): gp_* an jeder aktiven Zeile gültig; gp_fehler = Kontowert-Teil ausgefallen
            "gp_aktiv": gp_aktiv, "gp_fehler": gp_fehler,
            "excluded": sorted(excluded_names),
            "excluded_uids": sorted(excluded_ids),
            # Kapitel (24.09.2026): aktiver Filter + alle Kapitel für den Umschalter;
            # hedge_aus = Hedge-Spalten wurden für dieses Kapitel gar nicht gelesen.
            "kapitel": {"aktiv": (int(kapitel_id) if kapitel_id is not None else None),
                        "liste": kapitel_liste, "hedge_aus": hedge_aus}}


@app.route("/admin/overview", methods=["GET", "OPTIONS"])
def admin_overview():
    if request.method == "OPTIONS":
        return "", 200
    # Auth seit 24.09.2026 über _wd_login (Service-Key + sb-token + /auth/v1/user
    # — exakt die Prüfung, die hier vorher inline stand; nur eingeloggt, kein Admin).
    _uid, err = _wd_login()
    if err:
        return err
    try:
        kapitel_id = _kapitel_param()
    except ValueError:
        return jsonify({"error": "kapitel muss eine Zahl oder 'alle' sein"}), 400
    try:
        return jsonify(admin_build_overview(kapitel_id))
    except Exception as e:
        print(f"[admin] ⚠️ overview: {type(e).__name__}: {e}", flush=True)
        return jsonify({"error": str(e)}), 500


def admin_build_kapitel():
    """Kapitel-Vergleich für den Admin-Tab (24.09.2026, Finn: „dass wir das
    Ganze zeitlich trennen können mit den vorherigen Daten"): je Kapitel die
    Summen, die auch die Übersicht kennt, plus Monatssäulen für ein Chart.
    Zuordnung ausschließlich über die Spalte kapitel_id (accounts, trade_plans,
    transactions). Dieselben Helfer wie die Übersicht: _admin_basis (Accounts,
    Archiv, FX, Ausgeblendete), _admin_hedge_ev (Hedge-Formel). Reine Anzeige."""
    b = _admin_basis()
    accounts, archived, fx = b["accounts"], b["archived"], b["fx"]
    by_id, live_ids, excluded_ids = b["by_id"], b["live_ids"], b["excluded_ids"]
    names, disp = b["names"], b["disp"]
    liste = _kapitel_liste()
    # master_pl/blown/user_id zusätzlich zur Übersicht: Trade-Zähler + Prop-P&L je Kapitel.
    # master_symbol seit 24.09.2026 (Vollumstieg „Ohne Hedge"): Symbol-Zähler NQ/MNQ je Kapitel.
    # id/route/master_name/richtung seit 24.09.2026 nachts (Finn: „Graph OHNE Gegenhedge und
    # Graph MIT Gegenhedge — wie hätte es ausgesehen, hätte ich jetzt gegengehedgt?"): das
    # hedge-freie Kapitel liefert die Einzel-Trades, das Frontend rechnet den Kontrafakt daraus.
    _plans_sel = ("id,user_id,master_account_id,slave_account_id,"
                  "slave_pl,master_pl,blown,completed_at,kapitel_id,ohne_hedge,master_symbol,"
                  "route,master_name,richtung,slave_risk,master_risk,hedge_eur,winning_day,"
                  # Winning-Days-Statistik (26.09.2026): Herkunft, TP, Kontrakte, Zeiten, Schließgrund des Fusion-Hedges
                  "notes,master_tp,master_contracts,started_at,ended_at,hedge_grund:mt5_baseline->hedge->>grund")
    # konto_typ (25.09.2026, Kontotyp zum Zeitpunkt des Trades): fehlt die Spalte noch (SQL nicht eingespielt), ohne sie laden —
    # die Statistik darf daran nie kippen
    try:
        plans = _sb_all("trade_plans", {"select": _plans_sel + ",konto_typ", "status": "eq.completed"})
    except Exception:
        plans = _sb_all("trade_plans", {"select": _plans_sel, "status": "eq.completed"})
    # Hedge-Quoten je Firma·Typ·Größe aus der Hedge-Ära (24.09.2026, Finn: „der Hedge ist nicht
    # immer 1:1 … guck in den bestehenden Daten, wie viel wo gegengehedgt wurde") — Grundlage
    # für hedge_q/hedge_hyp_eur je V2-Trade unten. Ausgeblendete Personen fallen auch hier raus.
    hq_plans = [p for p in plans
                if str((by_id.get(str(p.get("master_account_id") or "")) or {}).get("user_id") or p.get("user_id") or "") not in excluded_ids]
    # payout = erhaltenes Geld (auch OHNE account_id, wie „Payouts erhalten");
    # live_pnl = das echte Hedge-Geld in EUR aus den Finanzen-Buchungen.
    # Seit 25.09.2026 VOR den Quoten geladen: die realen Reibungs-Flags brauchen die Payout-Konten.
    # wd_hedge (25.09.2026) = Fusion-Gegenhedge der Winning Days als Buchung — eigene Summe im Kapitel. Das
    # Hedge-GELD der Farm-Pläne zählt weiter über den Plan (slave_pl + hedge_eur in _admin_hedge_ev), die Buchung
    # ist der Finanzen-Abgleich dazu; in 'hedge' würde sie doppelt zählen.
    txs = _sb_all("transactions", {"select": "user_id,account_id,kind,amount,occurred_at,kapitel_id",
                                   "kind": "in.(payout,live_pnl,wd_hedge)"})
    payout_accs = {str(t.get("account_id")) for t in txs if t.get("kind") == "payout" and t.get("account_id")}
    real_flags, real_kats = _reib_real_flags(hq_plans, by_id, live_ids, b.get("arch_info") or {}, payout_accs)
    hq_gruppen, hq_lookup, reib_gruppen, reib_lookup, reib_global = _admin_hedge_quoten(hq_plans, by_id, live_ids, fx, real_flags, real_kats)
    # Vorbelegung = realer MITTELWERT (Finn 24.09.2026: „die Hälfte von 5,44" meint den Mittelwert, nicht den Median)
    reib_std = (reib_global or {}).get("real_mean")
    if reib_std is None:
        reib_std = HQ_REIBUNG_STD
    # Firmen-Standard-Symbol (firm_specs.symbol, über alle Personen) → CFD-Wurzel für Echo-V2-Trades
    # ohne master_symbol (24.09.2026, Finn: „—" soll „CFD · Echo V2" heißen). Fehlt der Read → leer, hörbar.
    firm_sym = {}
    try:
        for f in _sb_all("firm_specs", {"select": "name,symbol"}):
            w = _cfd_wurzel(f.get("symbol"))
            if w:
                firm_sym.setdefault(_firm_norm(f.get("name")), w)
    except Exception as e:
        print(f"[admin] ⚠️ firm_specs (kapitel): {type(e).__name__}: {e}", flush=True)
    def _f(v):
        try: return float(v)
        except (TypeError, ValueError): return None

    def _uid_of_plan(p):
        acc = by_id.get(str(p.get("master_account_id") or "")) or {}
        return str(acc.get("user_id") or p.get("user_id") or "")

    out = []
    for k in liste:
        kid = _kapitel_int(k.get("id"))
        if kid is None:
            continue
        kauf = hedge = payouts = master_pl = live_pnl = wd_hedge = 0.0
        wd_hedge_n = 0
        konten = konten_aktiv = payout_n = trades = blown = trades_ohne_hedge = 0
        tage = []
        monate = {}
        # Je Person (24.09.2026, Finn: Vergleich im Admin ohne Hedge-Spalten) und
        # je Symbolwurzel (NQ/MNQ) — ausgeblendete Personen sind oben schon raus.
        personen = {}
        symbole = {}
        # Kontrafakt-Listen (24.09.2026): NUR für hedge-freie Kapitel, klein gehalten — je Trade
        # Master-P&L in USD + Symbolwurzel/Weg/Richtung, dazu Payouts und Käufe des Kapitels als
        # datierte EUR-Beträge. Hedge-Kapitel bekommen die Listen nicht (dort ist der Hedge real).
        kontrafakt = not bool(k.get("hedge"))
        trades_liste, payouts_liste, kauf_liste = [], [], []
        wd_liste = []   # Winning Days des Kapitels (26.09.2026, Finn: „für Winning Days auch cleane Statistik")
        def _person(uid):
            return personen.setdefault(uid, {
                "user_id": uid, "person": disp.get(uid) or names.get(uid, uid[:8] or "—"),
                "konten": 0, "kauf": 0.0, "payouts": 0.0, "master_pl": 0.0, "trades": 0, "blown": 0})
        def _monat(datum, art, eur):
            if not datum:
                return
            tage.append(datum)
            m = monate.setdefault(datum[:7], {"monat": datum[:7], "kauf": 0.0, "hedge": 0.0, "payouts": 0.0})
            m[art] += eur
        # Konten + Kauf: nur Prop-Konten (kein Live-Broker), keine ausgeblendeten Personen.
        for a in accounts:
            if _kapitel_int(a.get("kapitel_id")) != kid:
                continue
            if (a.get("account_type") or "") == "live" or str(a.get("user_id")) in excluded_ids:
                continue
            aid = str(a["id"])
            konten += 1
            if aid not in archived:
                konten_aktiv += 1
            buy = _f(a.get("purchase_cost")) or 0.0
            kauf += buy
            if buy:
                _monat(str(a.get("created_at") or "")[:10], "kauf", buy)
            pe = _person(str(a.get("user_id")))
            pe["konten"] += 1
            pe["kauf"] += buy
            if kontrafakt and buy:
                kauf_liste.append({"user_id": pe["user_id"], "person": pe["person"],
                                   "datum": str(a.get("created_at") or "")[:10], "eur": round(buy, 2)})
        # Trades: Zähler über alle abgeschlossenen Pläne des Kapitels, Hedge nur
        # auf Live-Slaves (Formel wie Übersicht), Master-P&L roh in USD.
        for p in plans:
            if _kapitel_int(p.get("kapitel_id")) != kid:
                continue
            if _uid_of_plan(p) in excluded_ids:
                continue
            trades += 1
            pe = _person(_uid_of_plan(p))
            pe["trades"] += 1
            if p.get("blown"):
                blown += 1
                pe["blown"] += 1
            # ohne_hedge = generierte Spalte: V2-Weg (mt5v2/tvv2/tsv2) UND kein Fusion-Gegenhedge
            # (hedge_eur leer/0) — sql/2026-09-24_trade_plans_ohne_hedge_wd.sql. Finn (24.09.2026):
            # „alle Trades über Echo V2 / Orbit V2 sind ab jetzt ohne Gegenhedge" — AUSSER Winning-
            # Days-Farm-Pläne (hedge_eur > 0), die auf Fusion gegengehedgt sind; deren slave_pl zählt
            # unten über _admin_hedge_ev als echte Hedge-Seite, nicht als Kontrafakt.
            if p.get("ohne_hedge"):
                trades_ohne_hedge += 1
            # Winning Day (26.09.2026): Orbit V2 mit Fusion-Gegenhedge (hedge_eur > 0) oder als Winning Day markiert — echter
            # Hedge, Fusion-€ = slave_pl (Deal-Historie). Eigene Liste, zählt NICHT in die Kontrafakt-Trades.
            if kontrafakt and str(p.get("route") or "") == "tvv2" and ((_f(p.get("hedge_eur")) or 0) > 0 or p.get("winning_day")
                                                                        or str(p.get("konto_typ") or "") == "winning_days"):
                macc = by_id.get(str(p.get("master_account_id") or "")) or {}
                wd_liste.append({
                    "id": p.get("id"), "user_id": pe["user_id"], "person": pe["person"],
                    "account_name": p.get("master_name") or macc.get("name") or "",
                    "master_firm": _firm_norm(macc.get("firm")) if macc else "—",
                    "datum": str(p.get("completed_at") or "")[:10],
                    "zeit": p.get("completed_at") or p.get("ended_at") or None,
                    "master_pl": _f(p.get("master_pl")), "fusion_eur": _f(p.get("slave_pl")),
                    "hedge_eur": _f(p.get("hedge_eur")), "master_tp": _f(p.get("master_tp")),
                    "kt": _f(p.get("master_contracts")), "richtung": str(p.get("richtung") or "").lower(),
                    "grund": p.get("hedge_grund") or None, "blown": bool(p.get("blown")),
                    "quelle": "farmer" if "winning-day-farmer" in str(p.get("notes") or "").lower() else "hand",
                    "dauer_min": _kapitel_dauer_min(p.get("started_at"), p.get("ended_at") or p.get("completed_at"))})
            mpl = _f(p.get("master_pl"))
            if mpl is not None:
                master_pl += mpl
                pe["master_pl"] += mpl
            wurzel = _symbol_wurzel(p.get("master_symbol"))
            if wurzel:
                symbole[wurzel] = symbole.get(wurzel, 0) + 1
            if kontrafakt and p.get("ohne_hedge"):
                # Nur echte Ohne-Hedge-Trades (24.09.2026 spät): ein Winning-Days-Farm-Plan IST gehedgt —
                # sein realer Fusion-P&L läuft unten in 'hedge', ein hypothetischer daneben wäre doppelt.
                # Quote des Master-Kontos (Firma·Typ·Größe) aus der Hedge-Ära → Vorschlag hedge_hyp_eur
                # = −master_pl × q − Reibung. Ohne passende Gruppe (n < HQ_MIN_N überall) bleibt hedge_q
                # None; das Frontend rechnet dann fx × 1 und zeigt „ohne Quote".
                macc = by_id.get(str(p.get("master_account_id") or "")) or {}
                hg = _hq_aufloesen(macc, hq_lookup, p)   # Typ je Trade: Winning Day ≠ Big Trade (25.09.2026)
                hq = hg["median_q"] if hg else None
                # Reibung real je Trade: gemessener Gruppen-Median × realer Anteil der Gruppe (seit
                # 25.09.2026 aus den entschiedenen Ketten gemessen, nicht mehr fest 1,0/0,5);
                # ohne Gruppe der globale reale Mittelwert, sonst HQ_REIBUNG_STD.
                rg = _hq_aufloesen(macc, reib_lookup, p)
                r_anteil = rg["anteil"] if rg else ((reib_global or {}).get("anteil") or HQ_REIB_ANTEIL_SONST)
                reib_real = round(rg["median"] * r_anteil, 2) if rg else round(float(reib_std), 2)
                trades_liste.append({
                    "id": p.get("id"), "user_id": pe["user_id"], "person": pe["person"],
                    "account_name": p.get("master_name") or "",
                    "datum": str(p.get("completed_at") or "")[:10],
                    # genauer Zeitpunkt (25.09.2026, Finn: „man sieht nicht immer die neuesten zuerst") — die Liste
                    # sortiert danach und zeigt die Uhrzeit; datum bleibt der Tag für die Charts
                    "zeit": p.get("completed_at") or p.get("ended_at") or None,
                    # 24.09.2026 „mach MEHR Statistik": Stunde (Dubai) + Haltedauer + Konto-ID, damit das
                    # Frontend Tageszeit-, Dauer- und Je-Konto-Charts zeichnen kann. Ende = ended_at, sonst
                    # completed_at (V2-Trades werden per „Erledigt" abgeschlossen, ended_at kann fehlen).
                    "stunde": _kapitel_stunde(p.get("ended_at") or p.get("completed_at")),
                    "dauer_min": _kapitel_dauer_min(p.get("started_at"), p.get("ended_at") or p.get("completed_at")),
                    "account_id": str(p.get("master_account_id") or ""),
                    "master_pl": round(mpl, 2) if mpl is not None else None,
                    # Echo V2 ohne Symbol: Wurzel aus dem Firmen-Standard (symbol_quelle 'firma'), sonst leer → Frontend „CFD"
                    "master_symbol_root": wurzel or (firm_sym.get(_firm_norm(macc.get("firm")), "") if (macc and str(p.get("route") or "") == "mt5v2") else ""),
                    "symbol_quelle": ("plan" if wurzel else ("firma" if (macc and str(p.get("route") or "") == "mt5v2" and firm_sym.get(_firm_norm(macc.get("firm")))) else "")),
                    "route": p.get("route") or "",
                    "richtung": str(p.get("richtung") or "").lower(), "blown": bool(p.get("blown")),
                    "master_firm": _firm_norm(macc.get("firm")) if macc else "—",
                    "master_typ": _hq_typ_trade(macc, p) if macc else "—",   # 'wd' = Winning Day auf Funded
                    "master_groesse": _hq_groesse(macc) if macc else None,
                    "hedge_q": hq,
                    "hedge_q_quelle": ((f'{hg["key"]} · Vorgabe {hg["ziel_usd"]:.0f} $ ≙ {hg["ziel_eur"]:.0f} €' if hg.get("vorgabe")
                                        else f'{hg["key"]} · n={hg["n"]} · Ebene {hg["ebene"]}') if hg else None),
                    "reibung_real": reib_real,
                    "reibung_anteil": r_anteil,
                    # gemessene Reibung je Trade (26.09.2026, Finn: „was ich gespart habe an realen und gemessenen"
                    # als Linienchart) — Gruppen-Median vor dem realen Anteil; ohne Gruppe der globale Median.
                    "reibung_gem": (round(rg["median"], 2) if rg else (round(float((reib_global or {}).get("median")), 2)
                                    if (reib_global or {}).get("median") is not None else round(float(reib_std) * 2, 2))),
                    "reibung_quelle": (f'{rg["key"]} · n={rg["n"]} · Ebene {rg["ebene"]} · gemessen {rg["median"]} € × Anteil {r_anteil} ({rg["anteil_quelle"]}, {rg["n_entschieden"]} entschieden)' if rg else "global"),
                    "hedge_hyp_eur": (round(-mpl * hq - reib_real, 2) if (hq is not None and mpl is not None) else None)})
            ev = _admin_hedge_ev(p, by_id, live_ids, fx)
            if ev is not None:
                _m, datum, eur = ev
                hedge += eur
                _monat(datum, "hedge", eur)
        for t in txs:
            if _kapitel_int(t.get("kapitel_id")) != kid:
                continue
            if str(t.get("user_id") or "") in excluded_ids:
                continue
            amt = _f(t.get("amount"))
            if amt is None:
                continue
            if t.get("kind") == "payout":
                payouts += amt
                payout_n += 1
                _monat(str(t.get("occurred_at") or "")[:10], "payouts", amt)
                tuid = str(t.get("user_id") or "")
                if tuid:
                    _person(tuid)["payouts"] += amt
                if kontrafakt:
                    payouts_liste.append({"user_id": tuid, "person": (personen.get(tuid) or {}).get("person") or tuid[:8] or "—",
                                          "datum": str(t.get("occurred_at") or "")[:10], "eur": round(amt, 2)})
            elif t.get("kind") == "live_pnl":
                live_pnl += amt
            elif t.get("kind") == "wd_hedge":
                wd_hedge += amt
                wd_hedge_n += 1
        out.append({
            "id": kid, "key": k.get("key") or "", "name": k.get("name") or "",
            "von": k.get("von") or "", "bis": k.get("bis"),
            "hedge_aktiv": bool(k.get("hedge")),
            "farbe": k.get("farbe") or "", "beschreibung": k.get("beschreibung") or "",
            "konten": konten, "konten_aktiv": konten_aktiv,
            "kauf": round(kauf, 2), "hedge": round(hedge, 2),
            "payouts": round(payouts, 2), "payout_n": payout_n,
            "trades": trades, "blown": blown, "trades_ohne_hedge": trades_ohne_hedge,
            "master_pl": round(master_pl, 2), "live_pnl": round(live_pnl, 2),
            # Summe der WD-Hedge-Buchungen (P&L in €, negativ = Kosten) + Anzahl — Abgleich zu 'hedge' (Kosten, +)
            "wd_hedge": round(wd_hedge, 2), "wd_hedge_n": wd_hedge_n,
            "netto": round(payouts - kauf - hedge, 2),
            "erster_tag": min(tage) if tage else None,
            "letzter_tag": max(tage) if tage else None,
            "monate": [{k2: (round(v, 2) if isinstance(v, float) else v) for k2, v in m.items()}
                       for _mk, m in sorted(monate.items())],
            # Vergleich je Person + Symbol-Zähler (24.09.2026). Personen ohne
            # Bewegung im Kapitel tauchen nicht auf (kein Konto, kein Trade, kein Payout).
            "personen": sorted(
                [{k2: (round(v, 2) if isinstance(v, float) else v) for k2, v in pe.items()}
                 for pe in personen.values()],
                key=lambda pe: str(pe["person"]).lower()),
            "symbole": dict(sorted(symbole.items())),
            # Kontrafakt-Rohdaten (24.09.2026) — nur hedge-freie Kapitel tragen sie, sonst leer.
            "trades_liste": sorted(trades_liste, key=lambda t: (t["datum"], str(t.get("zeit") or ""), str(t["id"]))),
            "payouts_liste": sorted(payouts_liste, key=lambda t: t["datum"]),
            "kauf_liste": sorted(kauf_liste, key=lambda t: t["datum"]),
            "wd_liste": sorted(wd_liste, key=lambda t: (t["datum"], str(t.get("zeit") or ""), str(t["id"]))),
        })
    return {"kapitel": out, "fx_usd_eur": fx, "generated": _wt_now_iso(),
            # Hedge-Quoten der Hedge-Ära (24.09.2026): Gruppen A→D mit n/median/mean/p25/p75/median_r
            "hedge_quoten": {"gruppen": hq_gruppen, "fx": fx, "min_n": HQ_MIN_N, "reibung_std": round(float(reib_std), 2)},
            # Gemessene Reibung je Gruppe (24.09.2026): Kosten €/Trade (+ = weg), real = × Anteil
            # anteil je Gruppe seit 25.09.2026 gemessen (Ketten-Ausgang), 'regel' = Klartext fürs Frontend
            "reibung_gruppen": {"gruppen": reib_gruppen, "global": reib_global, "min_n": HQ_MIN_N,
                                "max_abw": HQ_REIB_MAX_ABW, "umschalt": HQ_REIB_UMSCHALT,
                                "regel": "Fixgröße 1,0 · Kette mit Payout 1,0 · ohne Payout geblowt 0 · manuell archiviert 1,0 · laufend zählt nicht"}}


@app.route("/admin/kapitel", methods=["GET", "OPTIONS"])
def admin_kapitel():
    """Kapitel-Vergleich (24.09.2026) — Auth wie /admin/overview: eingeloggt reicht."""
    if request.method == "OPTIONS":
        return "", 200
    _uid, err = _wd_login()
    if err:
        return err
    try:
        return jsonify(admin_build_kapitel())
    except Exception as e:
        print(f"[admin] ⚠️ kapitel: {type(e).__name__}: {e}", flush=True)
        return jsonify({"error": str(e)}), 500


# ════════════════════════════════════════════════════════════════════════════
# PROP-BAUM (03.10.2026, Auftrag von Pascal, Finn: „bau es mal in Prophos rein … fass nix
# bestehendes an"). Admin-Reiter: alle aktiven Prop-Accounts als Baum Firma → Stufe → ID →
# Account, Pascal arbeitet sie täglich ab. Reine Anzeige plus Haken — keine Bewertung.
# Eigener Endpoint statt /admin/overview erweitern: die Übersicht bleibt unberührt, und der
# Baum braucht nur einen Bruchteil ihrer Rechnung. Die Stufen rechnet das Frontend (eine
# Logik für aktuellen Stand und Tages-Schnappschuss), der Server liefert Rohwerte.
# Tabellen: sql/2026-10-03_prop_baum.sql (nur Service-Key, RLS ohne Policy).
# ════════════════════════════════════════════════════════════════════════════

def pb_handelstag(jetzt=None):
    """REIN RECHNEND (testbar): Handelstag zum Zeitpunkt jetzt (UTC) → (tag 'JJJJ-MM-TT', start_utc, ende_utc).
    Wechsel um 17:45 America/New_York (15 min vor Globex-Open 18:00 ET, Pascal 03.10.2026): alles ab 17:45 ET
    zählt zum nächsten Tag. Start/Ende je über die NY-Zeitzone gerechnet, damit Sommer-/Winterzeit stimmen."""
    from zoneinfo import ZoneInfo
    from datetime import timedelta
    ny_tz = ZoneInfo("America/New_York")
    ny = (jetzt or datetime.now(timezone.utc)).astimezone(ny_tz)
    tag = ny.date()
    if ny.hour * 60 + ny.minute >= 17 * 60 + 45:
        tag = tag + timedelta(days=1)
    vor = tag - timedelta(days=1)
    start = datetime(vor.year, vor.month, vor.day, 17, 45, tzinfo=ny_tz).astimezone(timezone.utc)
    ende = datetime(tag.year, tag.month, tag.day, 17, 45, tzinfo=ny_tz).astimezone(timezone.utc)
    return tag.isoformat(), start, ende


def _pb_iso(t):
    return t.strftime("%Y-%m-%dT%H:%M:%SZ")


def admin_build_prop_baum():
    b = _admin_basis()
    accounts, archived, arch_info = b["accounts"], b["archived"], b.get("arch_info") or {}
    by_id, names, disp, excluded_ids = b["by_id"], b["names"], b["disp"], b["excluded_ids"]
    tag, start, ende = pb_handelstag()
    start_iso = _pb_iso(start)
    jetzt_ts = datetime.now(timezone.utc).timestamp()

    def _alter_s(at):
        try:
            return jetzt_ts - datetime.fromisoformat(str(at).replace("Z", "+00:00")).timestamp()
        except Exception:
            return None

    # Balance wie die Übersicht (acc_balance_wahl, dieselbe Rangfolge). Die Reads von dup_live/mt5_live
    # liefern hier zugleich die offenen Positionen (= „heute gehandelt").
    dup_bal, echo_bal, offen_logins = {}, {}, set()
    try:
        for row in _sb_all("dup_live", {"select": "accounts,positions,updated_at"}):
            at = str(row.get("updated_at") or "")
            acc_login = {}
            for da in (row.get("accounts") or []):
                if not isinstance(da, dict):
                    continue
                lg = str(da.get("login") or "").strip()
                acc_login[str(da.get("account_id"))] = lg
                if lg and da.get("balance") not in (None, "") and (lg not in dup_bal or at > str(dup_bal[lg][2] or "")):
                    dup_bal[lg] = (da.get("balance"), da.get("ccy") or "USD", at)
            # Positionen nur aus einem frischen Spiegel (Wächter schreibt ~30 s) — ein eingefrorener zählt nicht
            alter = _alter_s(at)
            if alter is not None and alter <= 120:
                for p in (row.get("positions") or []):
                    lg = acc_login.get(str((p or {}).get("account_id")), "")
                    if lg:
                        offen_logins.add(lg)
    except Exception as e:
        print(f"[prop-baum] ⚠️ dup_live: {type(e).__name__}: {e}", flush=True)
    try:
        for row in _sb_all("mt5_live", {"select": "master_login,updated_at,bal:status->>master_balance,"
                                                  "ccy:status->>master_currency,pos:status->master_positions"}):
            lg = str(row.get("master_login") or "").strip()
            if not lg:
                continue
            at = str(row.get("updated_at") or "")
            if row.get("bal") not in (None, "") and (lg not in echo_bal or at > echo_bal[lg][2]):
                echo_bal[lg] = (row.get("bal"), row.get("ccy") or "USD", at)
            alter = _alter_s(at)
            if isinstance(row.get("pos"), list) and row["pos"] and alter is not None and alter <= 120:
                offen_logins.add(lg)
    except Exception as e:
        print(f"[prop-baum] ⚠️ mt5_live: {type(e).__name__}: {e}", flush=True)

    # Trades im laufenden Handelstag: Master ODER Slave, open/review/completed, Zeitanker started_at
    # (von Hand nachgetragene Pläne ohne started_at: created_at) — wie trades_start der Übersicht.
    gehandelt = set()
    try:
        for p in _sb_all("trade_plans", {"select": "id,master_account_id,slave_account_id",
                                         "status": "in.(open,review,completed)",
                                         "or": f"(started_at.gte.{start_iso},and(started_at.is.null,created_at.gte.{start_iso}))"}):
            for k in ("master_account_id", "slave_account_id"):
                if p.get(k):
                    gehandelt.add(str(p[k]))
    except Exception as e:
        print(f"[prop-baum] ⚠️ trade_plans: {type(e).__name__}: {e}", flush=True)
    # Winning Day von Hand gezählt (goal_manual_last = Tag) — fehlt in _admin_basis, deshalb ein schmaler Read
    try:
        for a in _sb_all("accounts", {"select": "id", "goal_manual_last": f"eq.{tag}"}):
            gehandelt.add(str(a.get("id")))
    except Exception as e:
        print(f"[prop-baum] ⚠️ goal_manual_last: {type(e).__name__}: {e}", flush=True)

    def _zeile(a):
        aid, uid = str(a["id"]), str(a.get("user_id"))
        bal, _ccy, _src, at = acc_balance_wahl(a, echo_bal, dup_bal)
        login = str(a.get("external_id") or "").strip()
        return {
            "id": aid, "user_id": uid, "person": disp.get(uid) or names.get(uid, uid[:8]),
            "firm": _firm_norm(a.get("firm")), "type": a.get("account_type") or "",
            "name": a.get("name") or "", "ext": a.get("external_id") or "",
            # groesse = Kontogröße (150k), basis = Start-Balance (Topstep Express startet bei 0 $)
            "groesse": _wd_konto_groesse(a), "basis": konto_basis_balance(a),
            "balance": round(bal, 2) if bal is not None else None, "balance_at": at or None,
            "wd_farm": bool(a.get("wd_farm")),
            "traded_today": aid in gehandelt or bool(login and login in offen_logins),
        }

    zeilen = []
    for a in accounts:
        aid, uid = str(a["id"]), str(a.get("user_id"))
        if (a.get("account_type") or "") == "live" or uid in excluded_ids or aid in archived:
            continue
        zeilen.append(_zeile(a))

    # Tages-Schnappschuss: erster Stand je Account am Handelstag. Fehlende Zeilen nachtragen (ignore-duplicates —
    # zwei gleichzeitige Aufrufe überschreiben nie den ersten Stand). Schlägt das fehl, gibt es eben keinen Pfeil.
    snap = {}
    try:
        for s in _sb_all("prop_baum_schnappschuss", {"select": "account_id,daten", "handelstag": f"eq.{tag}",
                                                      "order": "account_id.asc"}):
            snap[str(s.get("account_id"))] = s.get("daten") or {}
        neu = [{"account_id": z["id"], "handelstag": tag, "daten": z} for z in zeilen if z["id"] not in snap]
        if neu:
            r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/prop_baum_schnappschuss",
                            params={"on_conflict": "account_id,handelstag"}, json=neu,
                            headers=_sb_headers("resolution=ignore-duplicates,return=minimal"))
            _sb_pruefen(r)
            for z in neu:
                snap.setdefault(z["account_id"], z["daten"])
    except Exception as e:
        print(f"[prop-baum] ⚠️ Schnappschuss: {type(e).__name__}: {e}", flush=True)

    # Heute raus: im Schnappschuss des Tages, inzwischen archiviert → Grund aus dem Archiv-Eintrag
    # (blown / passed / passed_pending / manual — das Frontend macht daraus „geblowt" bzw. „bestanden").
    raus = []
    for aid, d in snap.items():
        if aid not in archived:
            continue
        a = by_id.get(aid) or {}
        uid = str(a.get("user_id") or d.get("user_id") or "")
        if uid in excluded_ids:
            continue
        raus.append(dict(d, id=aid, user_id=uid, grund=(arch_info.get(aid) or {}).get("reason") or ""))

    haken = {}
    try:
        for h in _sb_all("prop_baum_haken", {"select": "account_id,art", "handelstag": f"eq.{tag}",
                                             "order": "account_id.asc"}):
            haken[str(h.get("account_id"))] = h.get("art")
    except Exception as e:
        print(f"[prop-baum] ⚠️ Haken: {type(e).__name__}: {e}", flush=True)
    sichtbar = {z["id"] for z in zeilen} | {r["id"] for r in raus}

    people = sorted([{"user_id": u, "name": disp.get(u) or names.get(u, u[:8])}
                     for u in {z["user_id"] for z in zeilen} | {r["user_id"] for r in raus}],
                    key=lambda p: str(p["name"]).lower())
    return {"handelstag": tag, "wechsel_um": _pb_iso(ende), "accounts": zeilen,
            "schnappschuss": {k: v for k, v in snap.items() if k in sichtbar},
            "raus": raus, "haken": {k: v for k, v in haken.items() if k in sichtbar},
            "people": people, "generated": _wt_now_iso()}


@app.route("/admin/prop-baum", methods=["GET", "POST", "OPTIONS"])
def admin_prop_baum():
    """GET = Baum des laufenden Handelstags. POST {account_id, art: 'done'|'skip'|null} setzt bzw. löscht den
    Haken des Accounts für den laufenden Handelstag (die Server-Uhr entscheidet den Tag). Gate wie /admin/overview,
    „nur eigene" (admin_zugang) darf nur eigene Accounts abhaken."""
    if request.method == "OPTIONS":
        return "", 200
    uid, err = _wd_login()
    if err:
        return err
    if request.method == "GET":
        try:
            return jsonify(admin_build_prop_baum())
        except Exception as e:
            print(f"[prop-baum] ⚠️ GET: {type(e).__name__}: {e}", flush=True)
            return jsonify({"error": str(e)}), 500
    body = request.get_json(silent=True) or {}
    aid = str(body.get("account_id") or "").strip()
    art = body.get("art")
    if not re.match(r"^[0-9a-fA-F-]{36}$", aid):
        return jsonify({"error": "account_id fehlt"}), 400
    if art not in ("done", "skip", None):
        return jsonify({"error": "art muss done, skip oder null sein"}), 400
    try:
        acc = sb_select("accounts", {"select": "id,user_id", "id": f"eq.{aid}"}) or []
        if not acc:
            return jsonify({"error": "Account unbekannt"}), 404
        if not _admin_darf_uid(acc[0].get("user_id")):   # seit 08.10.2026 Verwalter: Accounts seiner Gruppe
            return jsonify({"error": "nur Accounts der eigenen Gruppe" if _admin_verwalter() else "nur eigene Accounts"}), 403
        tag = pb_handelstag()[0]
        if art is None:
            r = _sb_anfrage("DELETE", f"{SUPABASE_URL}/rest/v1/prop_baum_haken",
                            params={"account_id": f"eq.{aid}", "handelstag": f"eq.{tag}"}, headers=_sb_headers())
        else:
            r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/prop_baum_haken",
                            params={"on_conflict": "account_id,handelstag"},
                            json={"account_id": aid, "handelstag": tag, "art": art, "created_by": uid,
                                  "created_at": _wt_now_iso()},
                            headers=_sb_headers("resolution=merge-duplicates,return=minimal"))
        _sb_pruefen(r)
        return jsonify({"ok": True, "handelstag": tag, "account_id": aid, "art": art})
    except Exception as e:
        print(f"[prop-baum] ⚠️ POST: {type(e).__name__}: {e}", flush=True)
        return jsonify({"error": str(e)}), 500


