def vorrat2_rechnen_lauf(quelle):
    """Ein Lauf: Daten holen, je freier Zelle rechnen, Totband gegen den letzten Lauf, Ergebnis in vorrat_lauf. → Lauf-Zeile."""
    jetzt = datetime.now(timezone.utc)
    jetzt_iso = jetzt.isoformat()
    firmen_regeln, param, ohne_ids, bereit = _vorrat2_tabellen()
    if not bereit:
        raise RuntimeError(f"SQL noch nicht eingespielt ({VORRAT2_SQL})")
    b = _admin_basis()
    accounts, archived, arch_info = b["accounts"], b["archived"], b.get("arch_info") or {}
    excluded_ids = b["excluded_ids"] | ohne_ids
    ziele, matrix, ein, _ = _vorrat_tabellen()
    try:
        ziele_ext = {_firm_norm(z.get("firma")): z for z in sb_select("vorrat_ziele", {"select": "firma,kauf_groesse"})}
    except requests.exceptions.HTTPError:
        ziele_ext = {}
    for f, z in ziele.items():
        z.update({k: (ziele_ext.get(f) or {}).get(k) for k in ("kauf_groesse",)})
    # Stufen-Kette und Kernwerte je Vorrats-Firma aus auto_plan_regeln (ap_regel_finden: Vergleich nach _ap_norm über namen[])
    stufen, kws = {}, {}
    for f in ziele:
        rg = ap_regel_finden(firmen_regeln, f)
        stufen[f] = vorrat_stufen_aus_kernwerten(rg, param)
        kws[f] = ap_kw_param(rg)
    standard = ein.get("standard_status") if ein.get("standard_status") in ("frei", "gesperrt") else "frei"
    try:
        echo_bal, dup_bal = _ap_balance_karten()
    except Exception as e:
        echo_bal, dup_bal = {}, {}
        print(f"[vorrat2] ⚠️ Balance-Spiegel: {type(e).__name__}: {e}", flush=True)
    # Gemessene Quoten: nur Kapitel ohne Hedge (Spalte kapitel_id), Archiv-Grund passed/passed_pending = bestanden, blown = geblowt
    try:
        ohne_hedge = {int(k["id"]) for k in sb_select("kapitel", {"select": "id,hedge"}) if k.get("hedge") is False}
    except Exception:
        ohne_hedge = set()
    faelle = []
    for a in accounts:
        aid = str(a["id"])
        if aid not in archived or _kapitel_int(a.get("kapitel_id")) not in ohne_hedge:
            continue
        grund = (arch_info.get(aid) or {}).get("reason") or ""
        aus = "bestanden" if grund in ("passed", "passed_pending") else "geblowt" if grund == "blown" else None
        if aus:
            faelle.append((_firm_norm(a.get("firm")), a.get("account_type") or "", aus))
    quoten = vorrat_quoten(faelle, stufen, param)
    faktoren = {}
    for (firma, stufe), q in quoten.items():
        if q["faktor"]:
            faktoren.setdefault(firma, {})[stufe] = q["faktor"]
    # Konten je Zelle (Lesart wie Stufe 1)
    cfd_firmen = {f for f, z in ziele.items() if "funded_cfd" in (z.get("typen") or [])}
    je = {}
    for a in accounts:
        aid, uid = str(a["id"]), str(a.get("user_id"))
        if (a.get("account_type") or "") == "live" or uid in excluded_ids or aid in archived:
            continue
        firma = _firm_norm(a.get("firm"))
        if firma not in ziele:
            continue
        bal, _ccy, _src, at = acc_balance_wahl(a, echo_bal, dup_bal)
        express = ist_topstep_express(a)
        typ = a.get("account_type") or ""
        je.setdefault((uid, firma), []).append({
            "account_id": aid, "name": a.get("name"), "typ": typ if typ in VORRAT_TYPEN else "challenge",
            "groesse": vorrat_groesse(_wd_konto_groesse(a), None if express else bal,
                                      firma in cfd_firmen or typ in VORRAT_CFD_TYPEN),
            "balance": bal, "balance_at": at or None, "alter_tage": vorrat_alter_handelstage(at, jetzt) if at else None,
            "express": express, "waiting": bool(a.get("waiting_payout_since")), "created_at": a.get("created_at"),
            "consistency_pct": a.get("consistency_pct"), "_a": a})
    # Höchststand je Kettenkonto (Topstep mit DLL, 09.10.2026) für MLL in Chance und Kontowert — eine Abfrage, Fehler → ohne Höchststand
    kette_konten = [k["_a"] for (u_, f_), l_ in je.items() if (kws.get(f_) or {}).get("kette_daily") for k in l_]
    peaks = _ap_peaks(kette_konten) if kette_konten else {}
    for l_ in je.values():
        for k in l_:
            k["peak"] = peaks.get(str(k["_a"].get("id")))
            k.pop("_a", None)
    uids = sorted((set(b["names"]) | {u for u, _ in je}) - excluded_ids)
    # Totband-Vorlauf: letzte fertige Zeile
    try:
        alt = (sb_select("vorrat_lauf", {"select": "id,ergebnis", "ergebnis": "not.is.null", "order": "at.desc,id.desc", "limit": "1"})
               or [{}])[0]
    except requests.exceptions.HTTPError:
        alt = {}
    vorher = {(z.get("user_id"), z.get("firma")): z.get("totband") for z in ((alt.get("ergebnis") or {}).get("zellen") or [])}
    bestellungen = _vorrat2_bestellungen()
    zellen = []
    for f in sorted(ziele, key=lambda x: (float(ziele[x].get("reihe") or 0), x)):
        for uid in uids:
            gesetzt = matrix.get((uid, f))
            status = gesetzt if gesetzt in VORRAT_STATUS else standard
            liste = je.get((uid, f), [])
            seed = zlib.crc32(f"{uid}|{f}".encode("utf-8")) % 1000003
            z = vorrat2_zelle(ziele[f], stufen.get(f) or {}, liste, status, param, faktoren.get(f), seed, kws.get(f))
            nr = z["nachkauf"]["n_roh"]
            tb = vorrat_totband(nr, vorher.get((uid, f)), jetzt_iso, param) if isinstance(nr, int) else None
            z["totband"] = tb
            if tb:
                an = vorrat_anzeige_n(tb["n_tb"], tb["n_seit"], [k.get("created_at") for k in liste],
                                      [x for x in bestellungen if str(x.get("user_id")) == uid and _firm_norm(x.get("firma")) == f],
                                      jetzt_iso)
                z["nachkauf"]["n"] = an["n"]
                z["bestellt"] = an["bestellt"]
            else:
                z["nachkauf"]["n"] = 0 if nr == 0 else None
            z["nachkauf"]["dringlichkeit"] = z["lage"]
            z["nachkauf"]["heute"] = (min(z["nachkauf"]["n"], z["tagesrate"]) if isinstance(z["nachkauf"]["n"], int) else None)
            name = b["disp"].get(uid) or b["names"].get(uid) or uid[:8]
            z.update(user_id=uid, firma=f, status=status, user=name)
            # Fakten in Klartext für den KI-Bot (Master 06.10.2026) — liegen im Lauf, /admin/vorrat/lauf liefert sie aus
            z["fakten_text"] = vorrat_fakten_text(z, name, f, ziele[f], status)
            zellen.append(z)
    _, naechster = vorrat2_slot(jetzt, param["takt_utc"])
    return {"zellen": zellen, "stand": VORRAT2_RECHEN_STAND, "gesamt_score": vorrat_gesamt(zellen)["score"], "quoten": [dict(firma=k[0], stufe=k[1], **v) for k, v in quoten.items()],
            "parameter": param, "gerechnet_um": jetzt_iso, "naechster_lauf": naechster.isoformat(), "quelle": quelle}


def vorrat2_lauf(quelle="hand", slot=None):
    """Lauf mit Protokoll-Zeile. Takt: die Zeile mit slot ist der Claim (Unique-Index) — eine zweite Instanz bekommt 409 und lässt
    es. → Lauf-Zeile {id, at, quelle, ergebnis} oder None (Slot schon vergeben).
    Immer in einem EIGENEN App-Kontext (06.10.2026, erster Takt auf Railway: „Working outside of application context" —
    _admin_basis liest über _admin_nur_uid Flasks g, das es im Takt-Thread nicht gibt). Der frische Kontext hat ein leeres g:
    der Lauf sieht alle IDs, auch wenn ein „nur eigene"-Nutzer „Jetzt aktualisieren" drückt — sonst speicherte sein Klick einen
    Lauf nur mit seinen Zellen für alle."""
    with _vr2_lock, app.app_context():
        try:
            row = sb_insert("vorrat_lauf", {"quelle": quelle, "slot": slot})
        except requests.exceptions.HTTPError as e:
            if getattr(e.response, "status_code", 0) == 409:
                # Slot schon geclaimt. Ist er gescheitert (fehler gesetzt, kein Ergebnis), übernimmt dieser Versuch die Zeile —
                # der Guard im PATCH sorgt dafür, dass das genau EINE Instanz tut (06.10.2026: Slot 11:00 blieb mit Fehler stehen)
                neu = sb_update("vorrat_lauf", {"quelle": "eq.takt", "slot": f"eq.{slot}", "ergebnis": "is.null",
                                                "fehler": "not.is.null"}, {"fehler": None, "at": _wt_now_iso()})
                if not neu:
                    return None
                row = neu[0]
            elif getattr(e.response, "status_code", 0) == 404:
                raise RuntimeError(f"SQL noch nicht eingespielt ({VORRAT2_SQL})")
            else:
                raise
        try:
            erg = vorrat2_rechnen_lauf(quelle)
            erg["lauf_id"] = row.get("id")
            sb_update("vorrat_lauf", {"id": f"eq.{row['id']}"},
                      {"ergebnis": erg, "parameter": erg["parameter"], "quoten": erg["quoten"], "fehler": None})
            row.update(ergebnis=erg)
            return row
        except Exception as e:
            try:
                # fehler gesetzt = der Slot darf von einem späteren Versuch übernommen werden (siehe 409 oben)
                sb_update("vorrat_lauf", {"id": f"eq.{row['id']}"}, {"fehler": f"{type(e).__name__}: {e}"[:500]})
            except Exception:
                pass
            raise


def vorrat2_loop():
    """Takt: je Takt-Zeitpunkt (takt_utc) genau ein Lauf; ein verpasster Takt (Neustart) wird nachgeholt, bis der nächste dran ist."""
    print("[vorrat2] 📦 Takt bereit (" + ", ".join(VORRAT2_STD["takt_utc"]) + " UTC)", flush=True)
    takt, takt_at = list(VORRAT2_STD["takt_utc"]), 0.0
    while True:
        try:
            if time.time() - takt_at > 600:            # Parameter höchstens alle 10 min lesen
                try:
                    _, prm, _, ok_ = _vorrat2_tabellen()
                    takt = list(prm.get("takt_utc") or takt) if ok_ else takt
                except Exception:
                    pass
                takt_at = time.time()
            slot, _ = vorrat2_slot(datetime.now(timezone.utc), takt)
            s = slot.isoformat()
            if _vr2_info.get("slot") != s:
                vorrat2_lauf("takt", s)
                _vr2_info.update(slot=s, last_run=time.time(), runs=_vr2_info["runs"] + 1)
            _vr2_info["last_error"] = ""
        except Exception as e:
            _vr2_info["last_error"] = f"{type(e).__name__}: {e}"
            print(f"[vorrat2] ⚠️ {e}", flush=True)
            _schleife_schlafen(240)
        _schleife_schlafen(60)


def start_vorrat2():
    global _vr2_started
    if _vr2_started or not SUPABASE_SERVICE_KEY:
        return
    if (os.environ.get("PROPHOS_FRONTEND") or "").strip():
        return          # PC-Backend: kein Takt (nur Railway rechnet, sonst rechnet jeder PC)
    _vr2_started = True
    _vr2_info["started"] = True
    threading.Thread(target=vorrat2_loop, daemon=True).start()


VORRAT2_NEU_BREMSE_S = 300


def vorrat2_neu_seit_lauf(zellen, lauf_at):
    """REIN RECHNEND (testbar): gibt es Konten, die NACH dem letzten Lauf angelegt wurden? zellen tragen _angelegt (created_at je Konto
    der Zelle, aus admin_build_vorrat). Anlass 08.10.2026 (Finn: „Moritz — vor 20 Minuten 3 weitere Tradeify-Konten gekauft, die werden
    im Vorrat nicht angezeigt"): Konten-Liste, Wert im Vorrat und Kaufzahl kommen aus dem gespeicherten Lauf (Takt alle 6 h) —
    zwischen zwei Takten fehlten neue Konten bis zu 6 h. → True = ein frischer Lauf ist fällig."""
    if not lauf_at:
        return False

    def norm(x):   # PostgREST liefert „2026-10-07T22:12:24+00:00", SQL-Spalten auch „2026-10-07 17:00:25+00" — gleiche Form, dann String-Vergleich
        t = str(x).strip().replace(" ", "T").replace("Z", "+00:00")
        return t + ":00" if len(t) >= 3 and t[-3] == "+" and t[-6] != "+" else t
    s = norm(lauf_at)
    for z in zellen or []:
        for c in z.get("_angelegt") or []:
            if c and norm(c) > s:
                return True
    return False


def vorrat2_anhaengen(erg1):
    """Stufe-1-Antwort (admin_build_vorrat) + Stufe-2-Felder aus dem letzten Lauf. Gibt es noch keinen Lauf, läuft einmal einer.
    Bestellungen und seit dem Lauf angelegte Konten wirken sofort (vorrat_anzeige_n). Seit 08.10.2026: liegen Konten jünger als der
    letzte Lauf vor, läuft sofort ein neuer (Quelle 'hand' wie der Knopf, höchstens alle VORRAT2_NEU_BREMSE_S s) — neue Konten zählen damit sofort
    als im Vorrat, mit ihrer Lesung oder ohne (vorrat2_zelle nimmt Konten ohne Balance als Bestand ohne Chance-Wert)."""
    try:
        rows = sb_select("vorrat_lauf", {"select": "id,at,quelle,ergebnis", "ergebnis": "not.is.null", "order": "at.desc,id.desc",
                                         "limit": "1"})
    except requests.exceptions.HTTPError as e:
        if getattr(e.response, "status_code", 0) == 404:
            return dict(erg1, stufe2_bereit=False, stufe2_hinweis=f"SQL noch nicht eingespielt ({VORRAT2_SQL})")
        raise
    lauf = rows[0] if rows else vorrat2_lauf("hand")
    if lauf and lauf.get("ergebnis") and vorrat2_neu_seit_lauf(erg1.get("zellen") or [], lauf.get("at")) \
            and time.time() - float(_vr2_info.get("neu_at") or 0) > VORRAT2_NEU_BREMSE_S:
        _vr2_info["neu_at"] = time.time()
        try:
            lauf = vorrat2_lauf("hand") or lauf    # neue Konten seit dem letzten Lauf → sofort nachrechnen (08.10.2026); quelle 'hand', weil
                                                   # vorrat_lauf.quelle per CHECK nur 'takt'/'hand' zulässt (Hinweis Slave 1)
        except Exception as e:
            print(f"[vorrat2] ⚠️ Lauf wegen neuer Konten: {type(e).__name__}: {e}", flush=True)
    if lauf and (lauf.get("ergebnis") or {}).get("stand") != VORRAT2_RECHEN_STAND:
        # Lauf stammt aus älterem Code (06.10.2026: nach dem Push von .1055 fehlten untergrenze/chance_neu bis zum nächsten Takt —
        # die Sätze der Tagesliste lauteten „Ziel 0") → einmal neu rechnen; scheitert das, bleibt der alte Lauf
        try:
            lauf = vorrat2_lauf("hand") or lauf
        except Exception as e:
            print(f"[vorrat2] ⚠️ Neurechnung nach Code-Wechsel: {type(e).__name__}: {e}", flush=True)
    if not lauf or not lauf.get("ergebnis"):
        return dict(erg1, stufe2_bereit=False, stufe2_hinweis="noch kein Lauf")
    e2 = lauf["ergebnis"]
    try:
        # KI-Antwort gehört zum angezeigten (neuesten) Lauf — eine Antwort zu einem älteren Lauf rechnet mit alten Zahlen
        ki = (sb_select("vorrat_lauf", {"select": "id,ki_text,ki_zeilen,ki_um", "id": f"eq.{lauf.get('id')}"}) or [{}])[0]
    except requests.exceptions.HTTPError:
        ki = {}
    ki_aktiv = False
    if ki.get("ki_um") and isinstance(ki.get("ki_zeilen"), dict) and ki["ki_zeilen"]:
        try:
            alter_h = (datetime.now(timezone.utc) - datetime.fromisoformat(str(ki["ki_um"]).replace("Z", "+00:00"))).total_seconds() / 3600
            ki_aktiv = alter_h < float((e2.get("parameter") or {}).get("ki_gueltig_h") or VORRAT2_STD["ki_gueltig_h"])
        except ValueError:
            ki_aktiv = False
    jetzt_iso = _wt_now_iso()
    bestellungen = _vorrat2_bestellungen()
    z2 = {(z.get("user_id"), z.get("firma")): z for z in (e2.get("zellen") or [])}
    stufen_skala = {d["wert"]: d for d in VORRAT2_DRINGLICHKEITEN}
    for z in erg1.get("zellen") or []:
        s = z2.get((z["user_id"], z["firma"]))
        if not s:
            z.update(nachkauf=None, konten=[], score=None, score_teile=[], sperre=None, zustand=None, bestellt=None,
                     dringlichkeit=None, ki_text=None)
            continue
        nk = dict(s.get("nachkauf") or {})
        tb = s.get("totband")
        an = vorrat_anzeige_n(tb["n_tb"], tb["n_seit"], z.get("_angelegt") or [],
                              [b for b in bestellungen if str(b.get("user_id")) == z["user_id"]
                               and _firm_norm(b.get("firma")) == z["firma"]], jetzt_iso) if tb else None
        if an:
            nk["n"] = an["n"]
        nk["kosten_eur"] = (round(nk["n"] * nk["preis_eur"], 2) if isinstance(nk.get("n"), int) and nk.get("preis_eur") else None)
        lage = s.get("lage")
        nk["dringlichkeit"] = lage if lage in stufen_skala else None
        z.update(nachkauf=nk, konten=s.get("konten") or [], score=s.get("score"), score_teile=s.get("score_teile") or [],
                 sperre=s.get("sperre"), sicherheit=s.get("sicherheit"), sicherheit_nach=s.get("sicherheit_nach"),
                 bestand_gewichtet=s.get("bestand_gewichtet"), erwartet=s.get("erwartet"), bestfall=s.get("bestfall"),
                 hinweise=s.get("hinweise") or [], bestand_eur=s.get("bestand_eur"), funnel_eur=s.get("funnel_eur"),
                 untergrenze=s.get("untergrenze"), luecke=s.get("luecke"), unterwegs_n=s.get("unterwegs_n"),
                 vorrat_n=s.get("vorrat_n"), chance_neu=s.get("chance_neu"), wert_neu=s.get("wert_neu"),
                 unterwegs_stufen=s.get("unterwegs_stufen") or {}, kauf_regel=s.get("kauf_regel"),
                 unterwegs_nominal=s.get("unterwegs_nominal"), bestand_echt=s.get("bestand_echt"),
                 rechnung=(dict(s.get("rechnung") or {}, n=nk.get("n")) if s.get("rechnung") else None),
                 tagesrate=s.get("tagesrate"), abdeckung=s.get("abdeckung"),
                 toleranz=bool(s.get("toleranz")),
                 # flach für die Box „So wird gerechnet" (T1 06.10.2026) — dieselben Zahlen wie in rechnung
                 zaehlt_neu_usd=(s.get("rechnung") or {}).get("zaehlt_neu_usd"), wert_neu_usd=s.get("wert_neu"),
                 unterwegs_zaehlt_usd=(s.get("rechnung") or {}).get("funnel_zaehlt"),
                 regel_g=(s.get("rechnung") or {}).get("mitte"),
                 bestellt=(an or {}).get("bestellt"), zustand=("bestellt" if (an or {}).get("bestellt") else None),
                 ki_text=None)
        nk["heute"] = (min(nk["n"], s["tagesrate"]) if isinstance(nk.get("n"), int) and isinstance(s.get("tagesrate"), int)
                       else nk.get("n"))
        z.pop("_angelegt", None)
    # Tagesliste „Heute kaufen" (Master 06.10.2026) aus den angezeigten Zahlen — Bestellungen und neu angelegte Konten wirken sofort
    ziele_a = {f.get("firma"): f.get("ziel") or {} for f in erg1.get("firmen") or []}
    for z in erg1.get("zellen") or []:
        z.setdefault("art", ziele_a.get(z["firma"], {}).get("art"))
        z.setdefault("typen", ziele_a.get(z["firma"], {}).get("typen"))
    namen = {p_["user_id"]: p_["name"] for p_ in erg1.get("people") or []}
    tmax = int(((e2.get("parameter") or {}).get("tages_max")) or VORRAT2_STD["tages_max"])
    heute, luecke_ges = vorrat_tagesliste(erg1.get("zellen") or [], namen, tmax)
    for e in heute:
        e.update(quelle="regel", ki_um=None)
    # Overall-Score mit Trend gegen den vorigen Lauf (der Lauf davor nach Zeitpunkt, mit gespeichertem gesamt_score)
    try:
        vor = [r for r in sb_select("vorrat_lauf", {"select": "id,gs:ergebnis->gesamt_score", "ergebnis": "not.is.null",
                                                    "order": "at.desc,id.desc", "limit": "5"}) if r.get("id") != lauf.get("id")]
        trend = next((r.get("gs") for r in vor if isinstance(r.get("gs"), (int, float))), None)
    except Exception:
        trend = None
    gesamt = vorrat_gesamt(erg1.get("zellen") or [], heute, trend)
    # Satz je freier Zelle (auch „reicht für das Ziel, nichts kaufen") — Finn soll jede Zeile in Klartext lesen können
    for z in erg1.get("zellen") or []:
        n = (z.get("nachkauf") or {}).get("n")
        z["satz"] = (vorrat_satz(z, namen.get(z["user_id"]) or z["user_id"][:8], n or 0)
                     if z.get("status") == "frei" and not z.get("sperre") and isinstance(n, int) else None)
        z["quelle"] = "regel"
    personen_basis = erg1.get("zellen") or []
    if ki_aktiv:
        # KI-Bot (Master 06.10.2026): heute[], Satz und Personen-Zeile aus der KI; die Regel-Zahlen bleiben in nachkauf stehen
        heute = vorrat_ki_anwenden(erg1.get("zellen") or [], ki["ki_zeilen"], namen, ki.get("ki_um"))
        personen_basis = [dict(z, nachkauf=dict(z.get("nachkauf") or {}, n=(z.get("ki") or {}).get("heute", 0)))
                          if z.get("quelle") == "ki" else z for z in erg1.get("zellen") or []]
        gesamt.update(kaeufe_heute=sum(e["anzahl"] for e in heute),
                      kosten_heute_eur=round(sum(float(e.get("kosten_eur") or 0) for e in heute)))
    # Score je Person und je Firma (Finn 06.10.2026) — gesamt aus den Regel-Zahlen, heute aus heute[] (KI oder Regel)
    personen = vorrat_personen(personen_basis, namen)
    je_person = vorrat_score_gruppen(erg1.get("zellen") or [], heute, "user_id")
    for p_ in personen:
        p_.update(je_person.get(p_["user_id"]) or {"score": None, "wort": "—", "abdeckung_pct": None, "heute": 0, "gesamt": 0})
    je_firma = vorrat_score_gruppen(erg1.get("zellen") or [], heute, "firma")
    for f_ in erg1.get("firmen") or []:
        f_.update(je_firma.get(f_["firma"]) or {"score": None, "wort": "—", "abdeckung_pct": None, "heute": 0, "gesamt": 0})
    naechster = vorrat2_slot(datetime.now(timezone.utc), (e2.get("parameter") or VORRAT2_STD)["takt_utc"])[1]
    hinweise_ki = [dict(h, von_name=namen.get(str(h.get("von"))) or None) for h in _vorrat2_ki_hinweise()]
    return dict(erg1, stufe2_bereit=True, stufe2_hinweis="", gerechnet_um=e2.get("gerechnet_um"),
                ki_hinweise=hinweise_ki, naechster_ki_lauf=(naechster + timedelta(minutes=15)).isoformat(),
                heute=heute, luecke_gesamt=luecke_ges, tages_max=tmax, personen=personen,
                heute_quelle=("ki" if ki_aktiv else "regel"), ki_um=(ki.get("ki_um") if ki_aktiv else None),
                gesamt=gesamt,
                kauf_regel=(e2.get("parameter") or {}).get("kauf_regel"), mitte=(e2.get("parameter") or {}).get("mitte"),
                regel_satz=vorrat_regel_satz((e2.get("parameter") or {}).get("kauf_regel"), (e2.get("parameter") or {}).get("mitte", 0.5),
                                             (e2.get("parameter") or {}).get("sicherheit", 0.8)),
                naechster_lauf=vorrat2_slot(datetime.now(timezone.utc), (e2.get("parameter") or VORRAT2_STD)["takt_utc"])[1].isoformat(),
                lauf_id=lauf.get("id"), lauf_quelle=lauf.get("quelle"), sicherheit_ziel=(e2.get("parameter") or {}).get("sicherheit"),
                dringlichkeiten=VORRAT2_DRINGLICHKEITEN, ki_text=(ki.get("ki_text") if ki_aktiv else None),
                ki_text_um=(ki.get("ki_um") if ki_aktiv else None), ki_text_lauf_id=(ki.get("id") if ki_aktiv else None))


def _vorrat_antwort(erg1):
    """GET-/rechnen-Antwort: Stufe 1 + Stufe 2. Scheitert Stufe 2 (SQL fehlt, DB-Fehler), kommt Stufe 1 trotzdem — mit Hinweis."""
    try:
        out = vorrat2_anhaengen(erg1)
    except Exception as e:
        print(f"[vorrat2] ⚠️ anhängen: {type(e).__name__}: {e}", flush=True)
        out = dict(erg1, stufe2_bereit=False, stufe2_hinweis=f"Stufe 2: {type(e).__name__}: {e}"[:300])
    for z in out.get("zellen") or []:
        z.pop("_angelegt", None)
        z.setdefault("konten", [])
    out.setdefault("dringlichkeiten", VORRAT2_DRINGLICHKEITEN)
    out.setdefault("heute", [])
    out.setdefault("personen", [])
    out.setdefault("gesamt", None)
    out.setdefault("ki_hinweise", [])
    # Ziele zum Bearbeiten (Finn 06.10.2026): alle Spalten von vorrat_ziele, nach reihe
    try:
        out["ziele"] = sb_select("vorrat_ziele", {"select": "firma,art,typen,von,bis,groessen,kauf_einheit,kauf_groesse,reihe",
                                                  "order": "reihe.asc"})
    except requests.exceptions.HTTPError:
        try:
            out["ziele"] = sb_select("vorrat_ziele", {"select": "firma,art,typen,von,bis,groessen,kauf_einheit,reihe",
                                                      "order": "reihe.asc"})
        except requests.exceptions.HTTPError:
            out["ziele"] = []
    out.setdefault("luecke_gesamt", None)
    if _admin_nur_uid():
        # Admin-Gruppen (08.10.2026): der KI-Text und Finns KI-Hinweise sprechen über alle IDs (HT-weit) — nicht an Eingeschränkte
        out["ki_text"], out["ki_hinweise"] = None, []
    return out


def vorrat_ziel_pruefen(alt, body, neu=False):
    """REIN RECHNEND (testbar): Ziel-Änderung von der Seite prüfen (Finn über den Master 06.10.2026: Ziele direkt auf der
    Vorrat-Seite bearbeiten). alt = bisherige vorrat_ziele-Zeile ({} bei neu), body = POST. Erlaubt: von, bis, groessen,
    kauf_einheit, kauf_groesse; bei neu zusätzlich art und typen. Die Art einer bestehenden Zeile bleibt (sonst passen Bestand
    und Ziel nicht mehr zusammen). → (felder zum Schreiben, None) oder (None, Klartext-Fehler)"""
    out = {}
    if neu:
        art = body.get("art")
        if art not in ("plus_ueber_start", "groessen_summe", "stueck"):
            return None, "art muss plus_ueber_start, groessen_summe oder stueck sein"
        typen = body.get("typen")
        if not isinstance(typen, list) or not typen or any(t not in VORRAT_TYPEN for t in typen):
            return None, "typen muss eine Liste aus " + ", ".join(VORRAT_TYPEN) + " sein"
        out.update(art=art, typen=list(dict.fromkeys(typen)))
    else:
        art = (alt or {}).get("art")
    for k in ("von", "bis"):
        if k in body:
            v = body.get(k)
            if v is None or v == "":
                out[k] = None
                continue
            f = _vr2_num(v)
            if f is None or f < 0:
                return None, f"{k} muss eine Zahl ≥ 0 sein"
            out[k] = f
    if "groessen" in body:
        g = body.get("groessen")
        if g in (None, []):
            out["groessen"] = None
        else:
            if not isinstance(g, list) or len(g) > 10:
                return None, "groessen muss eine Liste [{groesse, stueck}] sein (höchstens 10)"
            sauber = []
            for t in g:
                if not isinstance(t, dict):
                    return None, "groessen: jeder Eintrag braucht groesse und stueck"
                gr, st = t.get("groesse"), t.get("stueck")
                grf = None if gr in (None, "") else _vr2_num(gr)
                if gr not in (None, "") and (grf is None or grf <= 0):
                    return None, "groessen: groesse muss > 0 sein (oder leer = jede Größe)"
                if not isinstance(st, int) or isinstance(st, bool) or st < 0:
                    return None, "groessen: stueck muss eine ganze Zahl ≥ 0 sein"
                sauber.append({"groesse": grf, "stueck": st})
            out["groessen"] = sauber
    if "kauf_einheit" in body:
        out["kauf_einheit"] = (str(body.get("kauf_einheit") or "").strip()[:80]) or None
    if "kauf_groesse" in body:
        v = body.get("kauf_groesse")
        f = None if v in (None, "") else _vr2_num(v)
        if v not in (None, "") and (f is None or f <= 0):
            return None, "kauf_groesse muss > 0 sein"
        out["kauf_groesse"] = f
    ges = dict(alt or {}, **out)
    if art == "stueck":
        if not ges.get("groessen"):
            return None, "bei art stueck sind groessen [{groesse, stueck}] Pflicht"
    else:
        if ges.get("von") is None or ges.get("bis") is None:
            return None, "von und bis sind Pflicht"
        if float(ges["von"]) > float(ges["bis"]):
            return None, "von muss ≤ bis sein"
    if not out:
        return None, "nichts zu ändern"
    return out, None


def _vorrat2_aktion(aktion, body, uid):
    """POST-Aktionen der Seite: einstellung {sicherheit} · bestellt {user_id, firma, anzahl, einheit} · bestellt_weg {id}."""
    nur = _admin_nur_uid()
    try:
        if aktion in ("ki_hinweis", "ki_hinweis_weg"):
            # Hinweise an den KI-Bot (Finn 06.10.2026) — gelten für alle IDs, „nur eigene"-Nutzer dürfen nicht
            if nur:
                return jsonify({"error": "nur Admin"}), 403
            try:
                ein = (sb_select("vorrat_einstellung", {"select": "parameter", "id": "eq.1"}) or [{}])[0]
            except requests.exceptions.HTTPError:
                return jsonify({"error": f"SQL noch nicht eingespielt ({VORRAT2_SQL})"}), 503
            prm = dict(ein.get("parameter") or {})
            liste = prm.get("ki_hinweise") or []
            if aktion == "ki_hinweis":
                liste, fehler = vorrat_ki_hinweis(liste, body.get("text"), uid, _wt_now_iso(), uuid.uuid4().hex[:12])
                if fehler:
                    return jsonify({"error": fehler}), 400
            else:
                hid = str(body.get("id") or "")
                if not any(isinstance(h, dict) and h.get("id") == hid for h in liste):
                    return jsonify({"error": "Hinweis nicht gefunden"}), 404
                liste = [h for h in liste if not (isinstance(h, dict) and h.get("id") == hid)]
            prm["ki_hinweise"] = liste
            sb_update("vorrat_einstellung", {"id": "eq.1"}, {"parameter": prm, "updated_at": _wt_now_iso()})
            return jsonify({"ok": True, "ki_hinweise": liste})
        if aktion in ("ziel", "ziel_neu"):
            # Ziele gelten für alle IDs — „nur eigene"-Nutzer dürfen sie nicht ändern (wie die Sicherheit)
            if nur:
                return jsonify({"error": "nur Admin"}), 403
            firma = _firm_norm(str(body.get("firma") or "")[:80])
            if firma == "—":
                return jsonify({"error": "firma fehlt"}), 400
            try:
                rows = sb_select("vorrat_ziele", {"select": "*"})
            except requests.exceptions.HTTPError as e:
                if getattr(e.response, "status_code", 0) == 404:
                    return jsonify({"error": f"SQL noch nicht eingespielt ({VORRAT_SQL})"}), 503
                raise
            alt = next((r for r in rows if _firm_norm(r.get("firma")) == firma), None)
            if aktion == "ziel" and not alt:
                return jsonify({"error": f"{firma} hat noch kein Ziel — erst anlegen (aktion ziel_neu)"}), 404
            if aktion == "ziel_neu":
                if alt:
                    return jsonify({"error": f"{firma} hat schon ein Ziel — ändern mit aktion ziel"}), 409
                firmen_regeln, _p, _o, _ok = _vorrat2_tabellen()
                if not ap_kw_param(ap_regel_finden(firmen_regeln, firma)):
                    return jsonify({"error": f"{firma} hat keine Kernwerte in auto_plan_regeln (Drawdown, Ziele, Kaufpreis) — "
                                             f"ohne sie lässt sich keine Chance rechnen. Erst die Kernwerte anlegen."}), 400
            felder, fehler = vorrat_ziel_pruefen(alt or {}, body, neu=(aktion == "ziel_neu"))
            if fehler:
                return jsonify({"error": fehler}), 400
            felder["updated_at"] = _wt_now_iso()
            if aktion == "ziel":
                neu_row = (sb_update("vorrat_ziele", {"firma": f"eq.{alt['firma']}"}, felder) or [None])[0]
            else:
                reihe = max([int(r.get("reihe") or 0) for r in rows] + [0]) + 1
                neu_row = sb_insert("vorrat_ziele", dict(felder, firma=firma, reihe=reihe))
            try:
                vorrat2_lauf("hand")            # sofort neu rechnen wie „Jetzt aktualisieren"
            except Exception as e:
                print(f"[vorrat2] ⚠️ Lauf nach Ziel-Änderung: {type(e).__name__}: {e}", flush=True)
            return jsonify({"ok": True, "ziel": neu_row})
        if aktion == "einstellung":
            if nur:
                return jsonify({"error": "nur Admin"}), 403
            s = _vr2_num(body.get("sicherheit"))
            if s is None or not (0.1 <= s <= 0.95):
                return jsonify({"error": "sicherheit muss zwischen 0,1 und 0,95 liegen (Anteil)"}), 400
            r = _sb_anfrage("PATCH", f"{SUPABASE_URL}/rest/v1/vorrat_einstellung", params={"id": "eq.1"},
                            json={"sicherheit": round(s, 3), "updated_at": _wt_now_iso()},
                            headers=_sb_headers("return=minimal"))
            if r.status_code in (400, 404):
                return jsonify({"error": f"SQL noch nicht eingespielt ({VORRAT2_SQL})"}), 503
            _sb_pruefen(r)
            return jsonify({"ok": True, "sicherheit": round(s, 3)})
        if aktion == "bestellt":
            ziel_uid = str(body.get("user_id") or "").strip().lower()
            firma = _firm_norm(str(body.get("firma") or "")[:80])
            anzahl = body.get("anzahl")
            if not re.match(r"^[0-9a-f-]{36}$", ziel_uid) or firma == "—":
                return jsonify({"error": "user_id/firma fehlt"}), 400
            if not isinstance(anzahl, int) or not (1 <= anzahl <= 20):
                return jsonify({"error": "anzahl muss 1–20 sein"}), 400
            if not _admin_darf_uid(ziel_uid):   # seit 08.10.2026 Verwalter: jede ID seiner Gruppe
                return jsonify({"error": "nur IDs der eigenen Gruppe" if _admin_verwalter() else "nur eigene ID"}), 403
            _, prm, _, _ok = _vorrat2_tabellen()
            from datetime import timedelta as _td
            verfall = (datetime.now(timezone.utc) + _td(hours=float(prm.get("bestellt_h") or 48))).isoformat()
            try:
                row = sb_insert("vorrat_bestellt", {"user_id": ziel_uid, "firma": firma, "anzahl": anzahl,
                                                    "einheit": (str(body.get("einheit") or "")[:80] or None), "von": uid,
                                                    "verfall_at": verfall})
            except requests.exceptions.HTTPError as e:
                if getattr(e.response, "status_code", 0) == 404:
                    return jsonify({"error": f"SQL noch nicht eingespielt ({VORRAT2_SQL})"}), 503
                raise
            return jsonify({"ok": True, "bestellt": {"id": row.get("id"), "anzahl": anzahl, "offen": anzahl,
                                                     "einheit": row.get("einheit"), "at": row.get("at"), "verfall": verfall}})
        bid = body.get("id")
        if not isinstance(bid, int):
            return jsonify({"error": "id fehlt"}), 400
        params = {"id": f"eq.{bid}", "weg_at": "is.null"}
        if nur:   # seit 08.10.2026 die ganze Sicht (Verwalter: Gruppe)
            params["user_id"] = admin_sicht_filter(getattr(g, "admin_sicht", None) or frozenset({nur}))
        r = sb_update("vorrat_bestellt", params, {"weg_at": _wt_now_iso()})
        if not r:
            return jsonify({"error": "Bestellung nicht gefunden"}), 404
        return jsonify({"ok": True, "id": bid})
    except Exception as e:
        print(f"[vorrat2] ⚠️ {aktion}: {type(e).__name__}: {e}", flush=True)
        return jsonify({"error": str(e)}), 500


def _vorrat2_code_ok():
    """X-Vorrat-Code gegen vorrat_einstellung.ki_code_sha256 (Finn setzt den Code per SQL, nie im Repo). Vergleich zeitkonstant."""
    code = (request.headers.get("X-Vorrat-Code") or "").strip()
    if not code:
        return False
    try:
        h = ((sb_select("vorrat_einstellung", {"select": "ki_code_sha256", "id": "eq.1"}) or [{}])[0].get("ki_code_sha256") or "")
    except Exception:
        return False
    return bool(h) and hmac.compare_digest(hashlib.sha256(code.encode("utf-8")).hexdigest(), str(h).strip().lower())


@app.route("/admin/vorrat/lauf", methods=["GET", "OPTIONS"])
def admin_vorrat_lauf():
    """Ein Lauf komplett (Mac-Skript für den Text, Master 06.10.2026: kein Service-Key auf dem Mac). ?lauf_id=N, ohne = neuester."""
    if request.method == "OPTIONS":
        return "", 200
    if not _vorrat2_code_ok():
        _uid, err = _wd_login()
        if err:
            return err
        if _admin_nur_uid():
            return jsonify({"error": "nur Admin"}), 403
    lid = str(request.args.get("lauf_id") or "").strip()
    params = {"select": "id,at,quelle,slot,parameter,quoten,ergebnis,fehler,ki_text,ki_zeilen,ki_um", "order": "at.desc,id.desc", "limit": "1"}
    if lid:
        if not lid.isdigit():
            return jsonify({"error": "lauf_id muss eine Zahl sein"}), 400
        params["id"] = f"eq.{lid}"
    else:
        params["ergebnis"] = "not.is.null"
    try:
        rows = sb_select("vorrat_lauf", params)
    except Exception as e:
        return jsonify({"error": str(e)}), 500
    if not rows:
        return jsonify({"error": "kein Lauf"}), 404
    # Finns Hinweise an den KI-Bot (06.10.2026) — die Routine liest sie hier mit
    return jsonify(dict(rows[0], lauf_id=rows[0].get("id"), ki_hinweise=_vorrat2_ki_hinweise()))


@app.route("/admin/vorrat/ki", methods=["POST", "OPTIONS"])
def admin_vorrat_ki():
    """KI-Antwort zu einem Lauf (Master 06.10.2026: KI-Bot, der wie Finn denkt — Routine in der Cloud ruft Railway).
    {lauf_id, text, zeilen: {"user_id|firma": {heute, einheit, prio, satz}}} — geprüft mit vorrat_ki_pruefen (Zelle des Laufs, frei,
    heute 0–5, ohne Lesung nur 0, Summe ≤ 30) und in vorrat_lauf.ki_zeilen/ki_text/ki_um gespeichert. GET /admin/vorrat baut
    heute[] daraus, solange die Antwort zum neuesten Lauf gehört und jünger als ki_gueltig_h ist."""
    if request.method == "OPTIONS":
        return "", 200
    if not _vorrat2_code_ok():
        _uid, err = _wd_login()
        if err:
            return err
        if _admin_nur_uid():
            return jsonify({"error": "nur Admin"}), 403
    body = request.get_json(silent=True) or {}
    lid = body.get("lauf_id")
    if not isinstance(lid, int):
        return jsonify({"error": "lauf_id fehlt"}), 400
    try:
        rows = sb_select("vorrat_lauf", {"select": "id,zellen:ergebnis->zellen", "id": f"eq.{lid}"})
    except Exception as e:
        return jsonify({"error": str(e)}), 500
    if not rows or not rows[0].get("zellen"):
        return jsonify({"error": "Lauf nicht gefunden oder ohne Ergebnis"}), 404
    _, prm, _, _ok = _vorrat2_tabellen()
    sauber, fehler = vorrat_ki_pruefen(rows[0]["zellen"], body.get("zeilen") or {}, int(prm.get("ki_max_tag") or 30),
                                       int(prm.get("ki_max_zelle") or 5))
    if fehler:
        return jsonify({"error": fehler}), 400
    try:
        r = sb_update("vorrat_lauf", {"id": f"eq.{lid}"},
                      {"ki_text": str(body.get("text") or "")[:4000] or None, "ki_zeilen": sauber, "ki_um": _wt_now_iso()})
    except Exception as e:
        return jsonify({"error": str(e)}), 500
    if not r:
        return jsonify({"error": "Lauf nicht gefunden"}), 404
    return jsonify({"ok": True, "lauf_id": lid, "zeilen": len(sauber), "heute": sum(v["heute"] for v in sauber.values())})


