WD_HEUTE_PPL = {"NQ": 20.0, "MNQ": 2.0}


def _cme_handelstag(roh=None):
    """Handelstag nach CME/Tradovate (Chicago): die Session ab 17:00 CT trägt das Datum des
    Folgetags → Chicago-Datum von (Zeitpunkt + 7 h). Exakt wie tvV2Handelstag im Frontend, damit
    Farmer-Pläne und Rundgang-Ergebnisse (mt5_baseline.tv.datum_start) denselben Tag meinen.
    roh: ISO-Stempel, Unix-Sekunden oder None (= jetzt). None, wenn nicht parsebar."""
    from datetime import timedelta
    from zoneinfo import ZoneInfo
    try:
        if roh is None:
            t = datetime.now(timezone.utc)
        elif isinstance(roh, (int, float)):
            t = datetime.fromtimestamp(float(roh), timezone.utc)
        else:
            t = datetime.fromisoformat(str(roh).replace("Z", "+00:00"))
            if t.tzinfo is None:
                t = t.replace(tzinfo=timezone.utc)
        return (t + timedelta(hours=7)).astimezone(ZoneInfo("America/Chicago")).strftime("%Y-%m-%d")
    except (ValueError, TypeError, OverflowError):
        return None


def _wd_level(einstieg, richtung, usd, ppl, kt, ist_tp):
    """REIN RECHNEND (testbar): Preis-Level aus einer $-Distanz. BUY: TP über, SL unter dem
    Einstieg; SELL gespiegelt. None ohne Einstieg, ohne Betrag, ohne Punktwert oder Kontrakte."""
    try:
        e, u, p, k = float(einstieg or 0), float(usd or 0), float(ppl or 0), float(kt or 0)
    except (TypeError, ValueError):
        return None
    if not (e > 0 and u > 0 and p > 0 and k > 0) or richtung not in ("buy", "sell"):
        return None
    d = u / (p * k)
    hoch = (richtung == "buy") == bool(ist_tp)
    return round(e + d if hoch else e - d, 2)


def tsx_zeile_ueberlagern(route, tv, einstieg, richtung, ppl, kt):
    """REIN RECHNEND (testbar, F28 mit Front end, 27.09.2026): Topstep V2 (tsv2) hat echte Werte aus TopstepX in der tv-Baseline —
    tv.tp_level_nq / tv.sl_level_nq (Brackets aus dem Reiter „Orders"), tv.mll_start (MLL, trailing) + tv.balance_start.
    Liquidation = MLL beim Start: liq_balance = mll_start, Level aus (balance_start − mll_start) als $-Abstand.
    einstieg_quelle wird unverändert durchgereicht ('fill' | 'reader_klick'). -> dict mit den Überschreibungen ({} sonst)"""
    if str(route or "") != "tsv2" or not isinstance(tv, dict):
        return {}
    out = {}
    tp, sl = _wd_num(tv.get("tp_level_nq")), _wd_num(tv.get("sl_level_nq"))
    if tp and tp > 1000:
        out["tp_level_nq"], out["level_quelle"] = tp, "tsx"
    mll, bs = _wd_num(tv.get("mll_start")), _wd_num(tv.get("balance_start"))
    if mll is not None and bs is not None and bs > mll:
        out.update(liq_balance=mll, liq_regel="MLL TopstepX beim Start", liq_quelle="mll_tsx",
                   liq_level_nq=_wd_level(einstieg, richtung, bs - mll, ppl, kt, False), liq_pl_usd=round(mll - bs, 2))
    if sl and sl > 1000:
        out.update(sl_level_nq=sl, sl_art="bracket")
    elif out.get("liq_level_nq") is not None:
        out.update(sl_level_nq=out["liq_level_nq"], sl_art="liquidation")
    if tv.get("einstieg_quelle"):
        out["einstieg_quelle"] = str(tv.get("einstieg_quelle"))
    return out


def tv_bracket_ueberlagern(route, tv, hedge):
    """REIN RECHNEND (testbar, 29.09.2026, Finn: „den Trade 1:1 in Radar klonen"): Orbit V2 (tvv2) OHNE Hedge — der neue Puls (CDP)
    liest TP- und SL-Limit exakt aus TradingViews Meldungen, der PC-Tab friert sie als tv.tp_level_nq / tv.sl_level_nq ein (gleiche
    Felder wie Topstep V2). Bisher rechnete der Radar TP/SL aus master_tp/master_sl ab dem Fill — TradingView verankert die Brackets
    aber am Kurs beim Klick (Live-Test 14:26 UTC, Plan 8fdf12d0: 0,25 Pkt daneben). Mit Hedge bleibt hedge.* maßgeblich (beim Open
    eingefroren, Hand-Werte „✎ TP aus TV"). -> dict mit den Überschreibungen ({} sonst)"""
    if str(route or "") != "tvv2" or not isinstance(tv, dict) or hedge:
        return {}
    out = {}
    tp, sl = _wd_num(tv.get("tp_level_nq")), _wd_num(tv.get("sl_level_nq"))
    if tp and tp > 1000:
        out["tp_level_nq"], out["level_quelle"] = tp, str(tv.get("tp_level_quelle") or "tv_toast")
    if sl and sl > 1000:
        out.update(sl_level_nq=sl, sl_art="bracket")
    return out


def _wd_konto_groesse(acc):
    """Kontogröße: „150k" aus dem Namen zuerst, sonst starting_balance (seit 08.10.2026 dieselbe Reihenfolge wie das Frontend
    kontoGroesseAnzeige/.1169 — Finn: ein 100k-Funding-Pips-Konto stand als „150k", weil starting_balance 150000 trug; Radar-groesse,
    WD-Hedge-Liquidation (Größe + 100 $) und Planer-Anzeige sehen so dieselbe Zahl). SQL-Abgleich 08.10.2026: bei allen winning_days/
    funded/funded_cfd-Konten ist starting_balance leer oder 0 — dort rechnete die Liquidation ohnehin schon aus dem Namen, nichts
    ändert sich; abweichend sind nur Phasen-Konten (siehe Bericht Slave-Terminal)."""
    m = re.search(r"(\d{2,3})\s*k\b", str((acc or {}).get("name") or ""), re.I)
    if m:
        return float(m.group(1)) * 1000
    sb = _wd_num((acc or {}).get("starting_balance"))
    return sb if sb and sb > 0 else None


def wd_start_balance(p, tv, acc, vorher):
    """REIN RECHNEND (testbar, B14): Balance vor dem Trade → (wert, quelle, at). tv.balance_start zuerst ('balance_start');
    sonst accounts.tv_balance als Vorläufer ('konto_balance'), aber nur wenn frisch: gelesen NACH dem Ende des letzten Trades
    dieses Kontos (vorher = {ended_at, balance_end_da}), dessen Nachlesung nicht mehr aussteht (balance_end da), und nicht
    NACH dem Ende dieses Plans (sonst wäre es schon die End-Balance). Sonst (None, None, None).
    Hintergrund (Front end 27.09.2026): tv.balance_start kommt erst NACH dem Hedge-Open — der Hedge öffnet sofort nach dem Klick."""
    # Topstep Express (01.10.2026, gemeinsame Regel ist_topstep_express): TopstepX zeigt die Balance 0-basiert — 0 und negativ sind
    # echte Stände; vorher fiel die Start-Balance dort weg und es gab keine Liquidation (bzw. einen Konto-Wert anderer Basis)
    express = ist_topstep_express(acc, plan_balance_relativ(p))
    gueltig = (lambda v: v is not None) if express else (lambda v: v is not None and v > 0)
    bs = _wd_num((tv or {}).get("balance_start"))
    if gueltig(bs):
        return bs, "balance_start", (tv or {}).get("balance_start_at") or p.get("started_at")
    kb = _wd_num((acc or {}).get("tv_balance"))
    kb_at = str((acc or {}).get("tv_balance_at") or "")
    if not gueltig(kb) or not kb_at:
        return None, None, None
    if p.get("ended_at") and kb_at > str(p.get("ended_at")):
        return None, None, None                    # schon die Balance NACH diesem Trade
    if vorher:
        if not vorher.get("balance_end_da"):
            return None, None, None                # Nachlesung des vorigen Trades steht noch aus
        if not vorher.get("ended_at") or kb_at <= str(vorher.get("ended_at")):
            return None, None, None                # vor dem Ende des vorigen Trades gelesen
    return kb, "konto_balance", kb_at


def wd_vorher_waehlen(p, fruehere):
    """REIN RECHNEND (testbar): letzter beendeter Trade desselben Kontos VOR diesem Plan → {ended_at, balance_end_da} | None.
    fruehere = [{id, master_account_id, ended_at, bal_end}]."""
    t = str(p.get("started_at") or p.get("start_um") or p.get("created_at") or "")
    acc = str(p.get("master_account_id") or "")
    kand = [f for f in (fruehere or []) if str(f.get("master_account_id") or "") == acc and str(f.get("id")) != str(p.get("id"))
            and f.get("ended_at") and (not t or str(f["ended_at"]) < t)]
    if not kand:
        return None
    f = max(kand, key=lambda x: str(x["ended_at"]))
    return {"ended_at": f["ended_at"], "balance_end_da": _wd_num(f.get("bal_end")) is not None}


def _wd_fruehere_trades(acc_ids):
    """Beendete Pläne der Konten (14 Tage) für wd_vorher_waehlen — eine Abfrage je 80 Konten, Fehler → []."""
    out, ids = [], sorted({str(x) for x in acc_ids if x})
    seit = datetime.fromtimestamp(time.time() - 14 * 86400, timezone.utc).isoformat()
    try:
        for i in range(0, len(ids), 80):
            # started_at + bal_start seit 30.09.2026 für liq_tagesstart (Tagesstart-Balance je CME-Handelstag)
            out += _sb_all("trade_plans", {"select": "id,master_account_id,ended_at,started_at,bal_end:mt5_baseline->final->balance_end,"
                                                     "bal_start:mt5_baseline->tv->balance_start",
                                           "master_account_id": f"in.({','.join(ids[i:i + 80])})", "ended_at": f"gte.{seit}"})
    except Exception as e:
        print(f"[wd-heute] ⚠️ frühere Trades: {type(e).__name__}: {e}", flush=True)
    return out


def wd_sl_zeile(p, acc, hedge, tv, einstieg, richtung, ppl, kt, sl_usd, vorher=None):
    """REIN RECHNEND (testbar, B14, 27.09.2026 — Finn: „Bei den Winning Days ist der Stop Loss im Chart immer der
    Liquidationspreis, also Balance 150.100. Wenn dieser Preis erreicht wird, wird der Fusion-Account geschlossen … bei den
    anderen Sachen rechnen wir den Liquidationspreis über den Max Drawdown."): SL-Linie einer /admin/wd-heute-Zeile.
    Winning Day: Liquidations-Level zu 100 % aus Start-Balance − (Kontogröße + 100 $) — hedge.sl_level_nq (vom Hedge-Open
    eingefroren, F22) hat Vorrang, sonst gerechnet wie /admin/live-trades (_lt_liq). Der Master bekommt KEINEN SL.
    Sonst: master_sl wie bisher. -> {sl_level_nq, sl_art 'liquidation'|'master_sl'|None, liq_balance, sl_hinweis}"""
    hedge = hedge or {}
    start_bal, liq_quelle, _start_at = wd_start_balance(p, tv, acc, vorher)
    liq = _lt_liq(acc, p, start_bal, einstieg, richtung, ppl, kt)
    typ = str((acc or {}).get("account_type") or "").lower()
    wd = plan_ist_wd(p, typ)
    if wd:
        # Rechnung zuerst (mit balance_start, sobald da), dann das beim Open eingefrorene Hedge-Level
        h_lvl = _wd_num(hedge.get("sl_level_nq"))
        if liq_quelle == "balance_start" and liq["level"] is not None:
            lvl, q = liq["level"], "balance_start"
        elif h_lvl:
            lvl, q = h_lvl, (hedge.get("liq_quelle") or "hedge")
        else:
            lvl, q = liq["level"], (liq_quelle if liq["level"] is not None else None)
        hinweis = None
        if lvl is None:
            hinweis = ("keine Start-Balance — Hedge schließt nur am TP" if start_bal is None
                       else "Start-Balance nicht über Kontogröße + 100 $ — kein Liquidations-Level" if liq["balance"] is not None
                       else "Kontogröße unbekannt — kein Liquidations-Level")
        return {"sl_level_nq": lvl, "sl_art": "liquidation" if lvl is not None else None,
                "liq_balance": liq["balance"], "liq_quelle": q, "sl_hinweis": hinweis}
    lvl = (_wd_num(hedge.get("sl_level_nq")) or _wd_level(einstieg, richtung, sl_usd, ppl, kt, False)) if sl_usd else None
    return {"sl_level_nq": lvl, "sl_art": "master_sl" if lvl is not None else None, "liq_balance": None, "liq_quelle": None,
            "sl_hinweis": None}


def wd_tsx_master_pl(tv, final):
    """REIN RECHNEND (testbar, TSV2-PNL 01.10.2026): Master-P&L eines beendeten Topstep-V2-Plans für /admin/wd-heute → dict | None.
    Balance nachher − vorher, wenn beide Seiten dieselbe Basis haben (TopstepX-Express zeigt die Balance 0-basiert, balance_relativ);
    sonst RP&L am Ende − RP&L beim Klick (today_pnl_start, ältere Pläne rpl_start) am selben Handelstag. NIE der Tages-RP&L allein:
    der enthält jeden Trade des Tages, auch Hand-Trades außerhalb von Prophos."""
    tv, final = tv or {}, final or {}
    bs, be = _wd_num(tv.get("balance_start")), _wd_num(final.get("balance_end"))
    ra, rb = tv.get("balance_relativ"), final.get("balance_relativ")
    if bs is not None and be is not None and not (isinstance(ra, bool) and isinstance(rb, bool) and ra != rb):
        return {"wert": round(be - bs, 2), "at": final.get("at"), "quelle": "final", "art": "balance"}
    start = _wd_num(tv.get("today_pnl_start"))
    if start is None:
        start = _wd_num(tv.get("rpl_start"))
    ende = _wd_num(final.get("today_pnl"))
    if start is not None and ende is not None and final.get("datum") and final.get("datum") == tv.get("datum_start"):
        return {"wert": round(ende - start, 2), "at": final.get("at"), "quelle": "final", "art": "rpl_start"}
    return None


def _wd_heute_zeile(p, acc, disp, vorher=None):
    """Eine Plan-Zeile für /admin/wd-heute — der JSON-Vertrag steht in der Route. vorher = letzter beendeter Trade
    desselben Kontos vor diesem Plan ({ended_at, balance_end_da}) für den Balance-Vorläufer (B14)."""
    base = p.get("mt5_baseline") if isinstance(p.get("mt5_baseline"), dict) else {}
    hedge = base.get("hedge") if isinstance(base.get("hedge"), dict) else None
    tv = base.get("tv") if isinstance(base.get("tv"), dict) else {}
    live = base.get("live") if isinstance(base.get("live"), dict) else {}
    final = base.get("final") if isinstance(base.get("final"), dict) else {}
    root = _symbol_wurzel(p.get("master_symbol_root") or p.get("master_symbol"))
    ppl = WD_HEUTE_PPL.get(root)
    kt = _wd_num(p.get("master_contracts"))
    richtung = str(p.get("richtung") or "").lower()
    # Einstieg (25.09.2026): aus dem Hedge, sonst aus der tv-Baseline (Teste speichert den Bot-Fill dort seit .517 auch
    # OHNE Hedge) — damit bekommen auch ungehedgte Winning Days ihre Level im Chart. Quelle wird mitgegeben.
    einstieg, einstieg_quelle = _wd_num((hedge or {}).get("einstieg_nq")), None
    if einstieg is not None:
        einstieg_quelle = "hedge"
    elif _wd_num(tv.get("einstieg_nq")) is not None:
        einstieg, einstieg_quelle = _wd_num(tv.get("einstieg_nq")), "tv"
    tp_usd, sl_usd = _wd_num(p.get("master_tp")), _wd_num(p.get("master_sl"))
    # Master-P&L: fertig am Plan → sonst letzter Rundgang-Stand (live) → sonst Ende-Differenz aus final/tv
    mpl = None
    if _wd_num(p.get("master_pl")) is not None:
        mpl = {"wert": _wd_num(p.get("master_pl")), "at": p.get("completed_at") or p.get("ended_at"), "quelle": "plan"}
    elif _wd_num(live.get("pnl")) is not None:
        mpl = {"wert": _wd_num(live.get("pnl")), "at": live.get("at"), "quelle": "rundgang"}
    elif p.get("route") == "tsv2":
        mpl = wd_tsx_master_pl(tv, final)
    elif _wd_num(final.get("today_pnl")) is not None:
        start = _wd_num(tv.get("today_pnl_start"))
        gleicher_tag = bool(final.get("datum")) and final.get("datum") == tv.get("datum_start")
        wert = (final["today_pnl"] - start) if (start is not None and gleicher_tag) else _wd_num(final.get("today_pnl"))
        mpl = {"wert": round(wert, 2), "at": final.get("at"), "quelle": "final"}
    uid = str(p.get("user_id") or "")
    ext = str((acc or {}).get("external_id") or "").strip()
    slz = wd_sl_zeile(p, acc, hedge, tv, einstieg, richtung, ppl, kt, sl_usd, vorher)
    zeile = {
        "id": str(p.get("id")), "plan_id": str(p.get("id")), "user_id": uid, "person": disp.get(uid, uid[:8]),
        # konto_id = master_account_id (08.10.2026, Prüfer zu „Manuelle Arbeit" aus „Braucht dich"): viele IDs haben mehrere
        # gleichnamige Konten — der Trade-Planer blendet deshalb über die Konto-ID aus, nicht über den Namen
        "konto_id": str(p.get("master_account_id") or "") or None,
        # farbe_key: derselbe Schluessel, mit dem die Flotte Personen faerbt (merken(w.uid) → mt5FleetFarbe(uid)) —
        # die user_id; das Frontend hasht wie gehabt
        "farbe_key": uid,
        "konto": {"name": (acc or {}).get("name") or p.get("master_name") or "", "firma": (acc or {}).get("firm") or p.get("master_firm") or "",
                  "groesse": _wd_konto_groesse(acc), "kontonr_ende": ext[-4:] if ext else "", "external_id": ext,
                  # B25: Start-Balance eines frischen Kontos — Topstep Express 0 $, sonst die Größe
                  "basis_balance": konto_basis_balance(acc, plan_balance_relativ(p)),
                  "topstep_express": ist_topstep_express(acc, plan_balance_relativ(p))},
        "route": p.get("route"), "richtung": richtung or None, "kt": kt, "kontrakte": kt, "symbol_root": root or None,
        "punktwert": ppl,   # B35/F28: $ je Punkt und Kontrakt (NQ 20, MNQ 2) — Live-P&L im Radar = (Kurs − Einstieg) · punktwert · kt
        "master_tp": tp_usd, "master_sl": sl_usd, "status": p.get("status"),
        "start_um": p.get("start_um"), "started_at": p.get("started_at"), "ended_at": p.get("ended_at"),
        "einstieg_nq": einstieg, "einstieg_quelle": einstieg_quelle,
        # Level = genau das, woran der Wächter schließt (Koordination 25.09.2026, nach .582 „Einstieg aus dem Puls-Fill nachtragen"):
        # hedge.tp_level_nq / sl_level_nq / schliesst_bei_nq sind beim Open eingefroren; einstieg_nq kann danach auf den Fill wandern.
        # Aus einstieg_nq + $-Distanz nur rechnen, wenn am Hedge kein Level steht (ungehedgte Winning Days, alte Pläne).
        "tp_level_nq": _wd_num((hedge or {}).get("tp_level_nq")) or _wd_level(einstieg, richtung, tp_usd, ppl, kt, True),
        # B14/F22 (27.09.2026): Winning Days → Liquidations-Level als „SL" (100 %, Start-Balance − (Größe + 100 $)), sonst master_sl
        "sl_level_nq": slz["sl_level_nq"], "sl_art": slz["sl_art"], "liq_balance": slz["liq_balance"], "liq_quelle": slz["liq_quelle"],
        "sl_hinweis": slz["sl_hinweis"],
        "schliesst_bei_nq": _wd_num((hedge or {}).get("schliesst_bei_nq")) or None,
        "level_quelle": ("hedge" if _wd_num((hedge or {}).get("tp_level_nq")) else ("einstieg" if einstieg is not None else None)),
        "master_pl": mpl,
        "hedge": hedge,   # KOMPLETT (mt5_baseline.hedge) — das Frontend rendert damit hedgeChipHtml unveraendert
        # Ende-Grund am Plan: final.quelle ('close' = Schliessen/Auto-Close, sonst Rundgang-Ende) — nur wenn ein Ende da ist
        "grund": (final.get("quelle") or ("rundgang" if final else None)) if (final or p.get("ended_at")) else None,
        "hedge_eur": _wd_num(p.get("hedge_eur")), "hedge_faktor": _wd_num(p.get("hedge_faktor")),
        "quelle": "farmer" if (p.get("notes") or "") == "Winning-Day-Farmer" else "manuell",
        "verknuepft": bool(p.get("start_um_gestartet_at") or p.get("orbit_gesendet_at")),
        "handelstag": _cme_handelstag(p.get("started_at") or p.get("start_um") or p.get("planned_for") or p.get("created_at")),
        # Abhak-Liste im Winning-Days-Block (Koordination 25.09.2026, Finn: „alle erledigten Winning Days unten abhaken — Master-
        # und Fusion-P&L kommen automatisch rein"): die Rohwerte am Plan + woher der Master-Wert stammt
        "master_pl_plan": _wd_num(p.get("master_pl")), "slave_pl": _wd_num(p.get("slave_pl")), "pl_quelle": p.get("pl_quelle"),
        "final_quelle": final.get("quelle"), "master_pl_schaetzung": _wd_num(final.get("master_pl_schaetzung")),
        "completed_at": p.get("completed_at"),
        "good_day": _wd_good_day(acc, p.get("master_pl")),
        # BESTANDEN-FLAG (07.10.2026, Finn: „sobald bei Wartet/Überprüfen der Trade geflagt ist, dass er sehr wahrscheinlich gepasst
        # ist … neue Accounts hinzufügen braucht meine Handarbeit"): Kontotyp + Ziel-Balance der Ziel-Wache (zw_tick, 5-min-Takt)
        "konto_typ": (acc or {}).get("account_type"), "ziel_usd": _zw["ziele"].get(str(p.get("master_account_id") or "")),   # 01.10.2026: Tradeify-WD über 250 $ → „Good Day" in Erledigt
        # Blow-Grenze aus den Kernwerten (Ziel-Wache, 08.10.2026) — die Ziel-Spanne in Überprüfen/Manuelle Arbeit, v. a. für Echo ohne Liq
        "boden_usd": (_zw.get("boeden") or {}).get(str(p.get("master_account_id") or "")),
        # P&L aus Fills + Abgleich (Koordination 25.09.2026): Einstieg/Start aus der tv-Baseline, Ende aus final — nur die Felder,
        # die die Rechnung braucht (Fill-Preise, Today's P&L, Quelle, Ende-Art), keine Zugangsdaten
        # TSV2-PNL (01.10.2026): dazu Balance vorher/nachher + Basis (TopstepX-Express 0-basiert) und der RP&L-Start
        "tv": {k: tv.get(k) for k in ("einstieg_nq", "einstieg_quelle", "einstieg_fill", "einstieg_symbol", "today_pnl_start", "datum_start",
                                      "balance_start", "balance_relativ", "rpl_start") if k in tv},
        "final": {k: final.get(k) for k in ("today_pnl", "datum", "quelle", "art", "grund", "exit_fill", "ende_quelle",
                                            "balance_end", "balance_relativ", "plattform") if k in final},
        # Endlesung (25.09.2026): Stand der Puls-Lesung nach dem Ende (Versuche, Fehler, Befund, Exit-Fill) — Statuszeile + „Jetzt lesen" (Design)
        "endlesung": _wd_endlesung_zeile(final),
        # MANUELLE ARBEIT (08.10.2026, Finn: Plan aus „Überprüfen" parken — „noch ein paar Winning Days mit 0,01 fahren, Notiz dran,
        # in zwei Tagen abhaken"): mt5_baseline.manuell {at, notiz, von} komplett oder null — das Radar baut daraus die Gruppe
        "manuell": base.get("manuell") if isinstance(base.get("manuell"), dict) else None,
    }
    # Puls-Merker NUR für Topstep V2 (05.10.2026, Topstep V2 im Radar): tv.puls 'tsx' = Puls hat den Plan in TopstepX gestartet;
    # ein von Hand gestarteter tsv2-Plan trägt das Feld nicht. Das Frontend braucht den Unterschied für die Radar-Zeile. Bewusst
    # nicht im Auszug oben: der gilt für jede Route, und Orbit V2 trägt am Plan ebenfalls tv.puls ('tv') — dessen Zeile bleibt
    # hier und in /admin/live-trades unverändert.
    if p.get("route") == "tsv2" and "puls" in tv:
        zeile["tv"]["puls"] = tv.get("puls")
    # F28: Topstep V2 — echte Brackets/MLL aus TopstepX vor gerechneten Werten (liq_level_nq/liq_pl_usd nur für live-trades)
    ueber = tsx_zeile_ueberlagern(p.get("route"), tv, einstieg, richtung, ppl, kt) or tv_bracket_ueberlagern(p.get("route"), tv, hedge)
    zeile.update({k: v for k, v in ueber.items() if k not in ("liq_level_nq", "liq_regel", "liq_pl_usd")})
    zeile["_tsx"] = ueber
    return zeile


def _wd_endlesung_signal(plan):
    """REIN RECHNEND (testbar): Signal-Zeile fuer den Knopf „Jetzt lesen" (25.09.2026) → (zeile, None) oder (None, (http, text)).
    Nur Orbit-V2-/Winning-Day-Plaene in „Ueberpruefen" mit Ende und OHNE gelesenes Today's P&L. Die Zeile gehoert dem
    Plan-Besitzer (order_signale-RLS: nur eigene Zeilen) — so claimt sie dessen PC-Tab (orderSignalTick, aktion 'endlesung').
    Handelstag und PC prueft der PC-Tab selbst (tvV2EndlesungGrund/PcPasst) und meldet den Grund im Ergebnis."""
    if not plan:
        return None, (404, "Plan nicht gefunden")
    route = plan.get("route")
    # 30.09.2026: Topstep V2 auch — aber NUR Pläne, die Puls in TopstepX gestartet hat (mt5_baseline.tv.puls == 'tsx');
    # Handpläne liest niemand automatisch. Echo V2 hat keinen Lese-Weg über Puls: sein P&L kommt aus der MT5-Balance.
    if route == "mt5v2":
        return None, (409, "Echo liest den P&L selbst aus der MT5-Balance — kein Nachlesen über Puls")
    if route == "tsv2":
        _b = plan.get("mt5_baseline") if isinstance(plan.get("mt5_baseline"), dict) else {}
        _tv = _b.get("tv") if isinstance(_b.get("tv"), dict) else {}
        if _tv.get("puls") != "tsx":
            return None, (409, "Topstep-Handplan — kein automatisches Nachlesen (nur von Puls gestartete Pläne)")
    elif route != "tvv2":
        return None, (409, "Kein Orbit-V2-/Winning-Day-/Topstep-V2-Plan")
    if plan.get("status") == "open":
        # Knopf „Beendet“ (28.09.2026): laufender Plan → der PC prüft erst in TradingView (tvV2BeendetPruefen), offen = nichts
        uid = str(plan.get("user_id") or "")
        if len(uid) < 10:
            return None, (409, "Plan ohne Besitzer")
        return {"user_id": uid, "plan_id": str(plan.get("id")), "status": "wartet",
                "params": {"aktion": "endlesung", "von": "admin", "pruefen": True}}, None
    if plan.get("status") != "review":
        return None, (409, f"Plan ist nicht in „Überprüfen“ (Status {plan.get('status')})")
    base = plan.get("mt5_baseline") if isinstance(plan.get("mt5_baseline"), dict) else {}
    fin = base.get("final") if isinstance(base.get("final"), dict) else None
    if not fin:
        return None, (409, "Plan hat noch kein Ende")
    if route == "tsv2":
        # TSV2-PNL (01.10.2026): today_pnl ist bei TopstepX der RP&L des GANZEN Handelstags — gelesen ist erst die Balance danach
        if _wd_num(fin.get("balance_end")) is not None:
            return None, (409, "Balance nach dem Trade ist schon gelesen")
    elif _wd_num(fin.get("today_pnl")) is not None or fin.get("quelle") == "puls":
        return None, (409, "Today's P&L ist schon gelesen")
    uid = str(plan.get("user_id") or "")
    if len(uid) < 10:
        return None, (409, "Plan ohne Besitzer")
    return {"user_id": uid, "plan_id": str(plan.get("id")), "status": "wartet",
            "params": {"aktion": "endlesung", "von": "admin"}}, None


# BALANCE FREMDER KONTEN AUS „BRAUCHT DICH" (08.10.2026, Finn am Trade-Planer: „Ich will hier direkt auf Balance-Refresh drücken können,
# sodass die Balance automatisch geladen wird — ohne auf Accounts zu gehen"; bisher nur der Hinweis „Am PC von Mike: Prophos → Accounts
# → ↻ Balance"). Gleiches Signal wie der eigene Weg (accBalanceLesen): MT5-Konto → 'mt5_balance' mit Login, TradingView/Topstep →
# 'konto_balance' — nur im Namen des KONTO-BESITZERS angelegt (order_signale-RLS), damit sein PC-Tab es claimt. Keine Logik an der
# Lesung selbst; Stand über balance_stand (= endlesung_stand für diese beiden Aktionen).
WD_BALANCE_FUTURES = WD_FUTURES_FIRMEN + ("alpha future", "alphafutures")   # wie tpFirmIstFutures im Frontend (Alpha Futures seit 07.10.)


def balance_lese_weg(firm, mt5_login="", external_id=""):
    """REIN RECHNEND (testbar): welcher PC-Weg liest die Balance eines Kontos (08.10.2026, Finn: „Bei The5%ers ist CFD. Da gibt es keinen
    Tradovate-Nutzernamen." — Puls-Routine fand auf pc-40mali eine Tradovate-Lesung für ein The5%ers-Konto ohne mt5_links-Zeile).
    Futures-Firma (WD_BALANCE_FUTURES) → ('konto_balance', '') = Puls in TradingView/TopstepX. CFD → ('mt5_balance', login) über das
    MT5-Terminal; Login aus mt5_links, sonst die External ID, wenn sie eine MT5-Nummer ist (wie mt5KontoLogin im Frontend und
    „Ansehen" in /admin/wd-plaene). CFD ohne Login → (None, Grund) — nie Tradovate."""
    f = str(firm or "").lower()
    if any(k in f for k in WD_BALANCE_FUTURES):
        return "konto_balance", ""
    login = str(mt5_login or "").strip() or str(external_id or "").strip()
    if not re.fullmatch(r"\d{4,}", login):
        return None, (f"CFD-Konto ({firm or 'Firma unbekannt'}) ohne MT5-Login — die Balance kommt nur über das MT5-Terminal (Echo), "
                      "nie über Tradovate. MT5-Verlinkung anlegen bzw. die MT5-Nummer als External ID eintragen.")
    return "mt5_balance", login


MT5_ORT_FRISCH_S = 120   # mt5_live-Zeile gilt als lebend (Leerlauf-Push der PC-Tabs alle 30 s)


def mt5_login_ort(login, rows, jetzt):
    """REIN RECHNEND (testbar): hat ein lebender PC der ID eine Echo-Instanz mit diesem MT5-Login? (08.10.2026, Finn: „Ich lade gerade
    ein Terminal bei Chris neu, es lädt seit 5 Minuten nichts" — Chris' mt5_balance für 14270909 verfiel nach 180 s, die Instanz
    schrieb seit 05.10. nicht mehr; 14 Tage: 21 von 67 MT5-Lese-/Terminal-Signalen verfielen so ohne Hinweis). Gleiche Regel wie
    mt5LoginOrt im Frontend. rows = mt5_live-Zeilen DER ID {pc_name, instance, master_login, master_expected, updated_at};
    jetzt = datetime (UTC). → ('da', None) | ('weg', zuletzt {pc, instanz, at} oder None) | (None, None) = unklar → Signal wie bisher.
    Unklar: kein lebender PC der ID (dann meldet der Signal-Weg „offline") oder eine lebende Instanz ohne bekannten Login (Build vor
    .1318 schreibt kein master_expected, Instanz ohne Snapshot)."""
    login = str(login or "").strip()
    if not login or rows is None:
        return None, None

    def _at(x):
        try:
            return datetime.fromisoformat(str(x.get("updated_at") or "").replace("Z", "+00:00"))
        except ValueError:
            return None

    def frisch(x):
        a = _at(x)
        return a is not None and (jetzt - a).total_seconds() < MT5_ORT_FRISCH_S

    def passt(x):
        return str(x.get("master_login") or "") == login or str(x.get("master_expected") or "") == login

    if any(frisch(x) and passt(x) for x in rows):
        return "da", None
    lebend = [x for x in rows if frisch(x)]
    if not lebend or any(not x.get("master_login") and not x.get("master_expected") for x in lebend):
        return None, None
    alt = sorted((x for x in rows if passt(x) and _at(x)), key=_at, reverse=True)
    z = alt[0] if alt else None
    return "weg", ({"pc": z.get("pc_name"), "instanz": z.get("instance"), "at": z.get("updated_at")} if z else None)


def mt5_login_ort_text(login, zuletzt):
    """Klartext zu mt5_login_ort 'weg' — gleicher Wortlaut wie mt5LoginOrtText im Frontend (Zeit in Dubai)."""
    t = f"Login {login} ist auf keinem laufenden PC dieser ID als Echo-Instanz eingerichtet"
    if zuletzt:
        wann = ""
        try:
            wann = datetime.fromisoformat(str(zuletzt.get("at") or "").replace("Z", "+00:00")).astimezone(_ap_tz("Asia/Dubai")).strftime("%d.%m., %H:%M")
        except (ValueError, TypeError):
            pass
        return (t + f" — zuletzt „{zuletzt.get('instanz')}“ auf {zuletzt.get('pc')} ({wann}). Dort im Echo-Panel die Instanz wieder "
                "anlegen bzw. „Direkt in Echo einrichten“.")
    return t + " — am PC dieser ID „Direkt in Echo einrichten“ (bzw. Instanz im Echo-Panel anlegen)."


def _mt5_ort_fehler(uid, login):
    """mt5_live der ID lesen und mt5_login_ort anwenden → Klartext, wenn sicher KEIN lebender PC den Login hat, sonst None
    (auch bei DB-Fehler: dann wie bisher das Signal senden)."""
    try:
        rows = sb_select("mt5_live", {"select": "pc_name,instance,master_login,updated_at,master_expected:status->>master_expected",
                                      "status->>user_id": f"eq.{uid}", "limit": "200"})
    except Exception:
        return None
    art, zuletzt = mt5_login_ort(login, rows, datetime.now(timezone.utc))
    return mt5_login_ort_text(login, zuletzt) if art == "weg" else None


def _wd_balance_signal(acc, mt5_login=""):
    """REIN RECHNEND (testbar): Signal-Zeile fuer „↻ Balance lesen" eines Kontos → (zeile, None) oder (None, (http, text)).
    acc = accounts-Zeile {id, user_id, name, firm, external_id}; mt5_login = mt5_links.mt5_login (leer = keins). Weg über
    balance_lese_weg: Futures → 'konto_balance' (Puls in TradingView/TopstepX), CFD → 'mt5_balance' (Echo-Terminal), CFD ohne Login → 409."""
    if not acc:
        return None, (404, "Konto nicht gefunden")
    aid, uid = str(acc.get("id") or ""), str(acc.get("user_id") or "")
    if len(aid) < 10:
        return None, (400, "account_id fehlt")
    if len(uid) < 10:
        return None, (409, "Konto ohne Besitzer")
    firm = str(acc.get("firm") or "")
    basis = {"account_id": aid, "external_id": acc.get("external_id"), "firm": firm, "name": acc.get("name"), "von": "admin"}
    weg, x = balance_lese_weg(firm, mt5_login, acc.get("external_id"))   # CFD nie über Tradovate (08.10.2026)
    if not weg:
        return None, (409, x)
    params = dict(basis, aktion="mt5_balance", login=x) if weg == "mt5_balance" else dict(basis, aktion="konto_balance")
    return {"user_id": uid, "plan_id": f"konto:{aid}", "status": "wartet", "params": params}, None


def _wd_endlesung_zeile(final):
    """Endlesungs-Stand fuer die wd-heute-Zeile (Design-Statuszeile, auch fuer fremde Plaene) — nur die puls-Felder."""
    final = final if isinstance(final, dict) else {}
    keys = ("today_pnl", "quelle", "datum", "at", "puls_at", "puls_versuche", "puls_fehler", "puls_aufgegeben",
            "puls_diagnose", "puls_flach", "exit_fill", "exit_diag", "ende_quelle",
            "puls_login_fehler", "puls_login_at", "puls_login_code",   # Login-Bremse (30.09.2026): Radar „Wartet · Login prüfen"
            # Balance nach dem Trade (TSV2-PNL, 01.10.2026): ohne sie zeigte die Abhak-Liste „Puls liest …" trotz gelesener Balance
            # und bei TopstepX den Tages-RP&L als „gelesen"
            "balance_end", "balance_quelle", "balance_relativ", "plattform",
            # Konto weg (05.10.2026): der PC-Tab setzt final.konto_weg + konto_weg_at, wenn das Konto im frisch angemeldeten
            # Tradovate-Login nicht mehr steht. Ohne die Felder erkannte der Radar einer fremden ID den Fall nur am Anfang
            # des Textes in puls_fehler.
            "konto_weg", "konto_weg_at")
    out = {k: final.get(k) for k in keys if final.get(k) is not None}
    return out or None


def _wd_heute_behalten(z, tag):
    """REIN RECHNEND (testbar): gehört die Zeile in /admin/wd-heute? Laufende und zu prüfende (review) IMMER, egal welcher
    Handelstag (Koordination 25.09.2026: sonst verschwinden Jacobs beendete Pläne um 22:00 UTC aus der Abhak-Liste);
    alles andere (planned, completed) nur am angefragten Handelstag."""
    return z.get("status") in ("open", "review") or z.get("handelstag") == tag


def _wd_heute_sortkey(z):
    """open (nach started_at) → planned (nach start_um) → Rest (ended_at absteigend)."""
    st = z.get("status")
    if st == "open":
        return (0, str(z.get("started_at") or ""), "")
    if st == "planned":
        return (1, str(z.get("start_um") or "9999"), "")
    # absteigend: Stempel negiert über ein umgekehrtes Zeichen-Mapping wäre umständlich → Tupel mit Marker,
    # sortiert wird unten stabil in zwei Schritten (siehe _wd_heute_sortieren)
    return (2, "", str(z.get("ended_at") or z.get("started_at") or ""))


def _wd_heute_sortieren(zeilen):
    rest = sorted([z for z in zeilen if _wd_heute_sortkey(z)[0] == 2], key=lambda z: _wd_heute_sortkey(z)[2], reverse=True)
    vorn = sorted([z for z in zeilen if _wd_heute_sortkey(z)[0] != 2], key=_wd_heute_sortkey)
    return vorn + rest


@app.route("/admin/wd-heute", methods=["GET", "OPTIONS"])
def admin_wd_heute():
    """GET /admin/wd-heute → {tag, jetzt, plaene:[…]} — alle Winning-Day-Pläne des CME-Handelstags
    über alle IDs (route tvv2 UND (Farmer-Notiz ODER hedge_eur > 0)) plus alle laufenden (status
    open) und alle zu prüfenden (status review), egal welcher Tag. Zusätzlich je Plan (25.09.2026, Abhak-Liste):
    master_pl_plan, slave_pl, pl_quelle, final_quelle, master_pl_schaetzung, completed_at. Auth wie /admin/wd-plaene (sb-token, Service-Key liest).
    Je Plan: {id (= plan_id), user_id, person, konto_id (= master_account_id, 08.10.2026), farbe_key, konto{name, firma, groesse, kontonr_ende,
    external_id}, route, richtung, kt (= kontrakte), symbol_root, master_tp, master_sl, status, start_um,
    started_at, ended_at, einstieg_nq, einstieg_quelle ('hedge'|'tv'|null), tp_level_nq, sl_level_nq (eingefroren am Hedge, sonst gerechnet),
    schliesst_bei_nq (Wächter-Level)|null, level_quelle 'hedge'|'einstieg'|null, master_pl{wert, at, quelle}|null,
    hedge (mt5_baseline.hedge komplett)|null, grund, hedge_eur, hedge_faktor, quelle 'farmer'|'manuell',
    verknuepft, handelstag}.
    Ausgeblendete Personen (ADMIN_EXCLUDE_EMAILS) fehlen wie in der Übersicht."""
    if request.method == "OPTIONS":
        return "", 200
    me, err = _wd_login()
    if err:
        return err
    try:
        tag = (request.args.get("tag") or "").strip()[:10] or _cme_handelstag()
        disp, excluded = _wd_personen()
        seit = datetime.fromtimestamp(datetime.now(timezone.utc).timestamp() - 3 * 86400, timezone.utc).isoformat()
        felder = ("id,user_id,master_account_id,master_name,master_firm,route,notes,status,richtung,master_contracts,"
                  "master_symbol,master_symbol_root,master_tp,master_sl,master_pl,hedge_eur,hedge_faktor,start_um,orbit_v3,"
                  "start_um_gestartet_at,orbit_gesendet_at,started_at,ended_at,completed_at,planned_for,created_at,mt5_baseline,"
                  "slave_pl,pl_quelle")
        # PostgREST: verschachteltes Oder heisst or(...) OHNE Punkt — "or.(...)" gab 400 Bad Request
        # (Finn 25.09.2026 am Markt-Block: "Winning Days des Tages nicht ladbar"). ilike statt eq, damit
        # Notes mit Zusatztext den Farmer-Plan nicht verlieren.
        wd = "or(notes.ilike.*Winning-Day-Farmer*,hedge_eur.gt.0)"
        # B16/F23 (27.09.2026): Puls für Topstep (route tsv2) zählt wie Orbit V2 (tvv2) — gleiche Baseline-Form (mt5_baseline.tv)
        rows = _sb_all("trade_plans", {"select": felder, "route": "in.(tvv2,tsv2)", "and": f"({wd},created_at.gte.{seit})"})
        rows += _sb_all("trade_plans", {"select": felder, "route": "in.(tvv2,tsv2)", "status": "eq.open", "and": f"({wd})"})
        # zu prüfende Winning Days jedes Tages (Abhak-Liste, 25.09.2026)
        rows += _sb_all("trade_plans", {"select": felder, "route": "in.(tvv2,tsv2)", "status": "eq.review", "and": f"({wd})"})
        gesehen, plaene = set(), []
        for p in rows:
            pid = str(p.get("id"))
            if pid in gesehen or str(p.get("user_id")) in excluded:
                continue
            gesehen.add(pid)
            plaene.append(p)
        acc_ids = {str(p.get("master_account_id")) for p in plaene if p.get("master_account_id")}
        accs = {}
        ids = sorted(acc_ids)
        for i in range(0, len(ids), 80):
            for a in sb_select("accounts", {"select": "id,name,firm,account_type,starting_balance,external_id,tv_balance,tv_balance_at", "id": f"in.({','.join(ids[i:i + 80])})"}):
                accs[str(a["id"])] = a
        zeilen = []
        fruehere = _wd_fruehere_trades(acc_ids)       # B14: für den Balance-Vorläufer (konto_balance)
        for p in plaene:
            # Orbit V3 ist nie ein Winning Day (05.10.2026, Finn: „Orbit-Pläne mit Fusion-Hedge sind separat von Winning Days … die
            # kommen ganz normal ins Radar") — Chris' Apex-Funded-Trades standen unter „Läuft gerade", weil hedge_eur > 0 reichte.
            # Gilt auch auf Winning-Days-Konten; wie plan_ist_wd.
            if p.get("orbit_v3") is True:
                continue
            z = _wd_heute_zeile(p, accs.get(str(p.get("master_account_id") or "")), disp, wd_vorher_waehlen(p, fruehere))
            z.pop("_tsx", None)
            if _wd_heute_behalten(z, tag):
                zeilen.append(z)
        kj = _kurs_jetzt()                       # B35/F28: aktueller Kurs je Wurzel (Radar-Weg Topstep)
        for z in zeilen:
            z["kurs_jetzt"] = kj.get(z.get("symbol_root") or "")
        return jsonify({"tag": tag, "jetzt": datetime.now(timezone.utc).isoformat(), "kurs_jetzt": kj, "plaene": _wd_heute_sortieren(zeilen)})
    except Exception as e:
        print(f"[wd-heute] ⚠️ {type(e).__name__}: {e}", flush=True)
        return jsonify({"error": f"Winning Days des Tages nicht ladbar ({type(e).__name__}: {e})"}), 502


# ══ LIVE TRADES (26.09.2026, Finn: „bei jedem einzelnen Trade, bei dem Puls auf TradingView platziert wird, eine neue Navigation
# unter Winning Days ‚Live Trades' … Einstieg, Take-Profit- bzw. Liquidationswerte von NQ … der Trade wird als Demo in Prophos genauso
# ausgeführt — wenn der Take Profit in Tradovate ausgelöst wurde, gilt er bei unserem Demo-Trade auch … danach liest Puls 1–30 min später
# die neue Live-Balance"). Eigener Block, NICHT im READER-WACHT-Bereich (Absprache mit dem Backend-Terminal).
# Demo = bei jedem Abruf frisch aus den gespeicherten Reader-Minutenkerzen (tv_kurs_1m: h/l je Minute) — kein Dauer-Wächter,
# rückwirkend identisch, auch wenn niemand zusah. Liquidation: Winning Day → Kontogröße + 100 $ (Finn 25.09.2026: WD-Master blowen
# bei 150.100 $), sonst Balance beim Start − Max-Drawdown. Ohne Start-Balance kein Liquidations-Level (nur TP).
# Seit 26.09.2026 abends (Finn: „Der Max-Drawdown ist quasi der SL. Das kannst du selber ausrechnen."): Nicht-WD-Konten
# bekommen das Level IMMER aus dem Max-Drawdown am Konto — Abstand wie ein SL von max_drawdown $ bei den Kontrakten des
# Plans (_wd_level), unabhängig von der Start-Balance; liq_balance (Start − Max-Drawdown) nur zusätzlich, wenn sie da ist.
# Ohne max_drawdown am Konto kein Level (nichts raten). Winning Days unverändert (Kontogröße + 100 $, braucht die Balance).
LT_WD_BLOW_PLUS = 100.0


def ist_topstep_express(acc, relativ=None):
    """REIN RECHNEND (testbar, B25, 27.09.2026): Topstep-Express-Konto (XFA, Kennung EXPRESS-V2-…). Startet bei 0 $ Balance,
    nicht bei der Kontogröße (ein Express mit 11.079,66 $ = Gewinn) — „Größe + 100 $" als Liquidation wäre dort Unsinn.
    EINE Regel mit dem Frontend (kontoIstTopstepExpress, Master-Entscheid 01.10.2026): Topstep UND (Kontotyp funded/winning_days
    ODER „EXPRESS"/„XFA" in Name/External ID). relativ (bool) = balance_relativ einer frischen TopstepX-Lesung dieses Trades —
    die gewinnt (TopstepX zeigt Express 0-basiert, Combine absolut); None = keine Lesung, dann die Regel."""
    a = acc or {}
    firm = str(a.get("firm") or "").lower()
    if "topstep" not in firm:
        return False
    if isinstance(relativ, bool):
        return relativ
    kenn = (str(a.get("external_id") or "") + " " + str(a.get("name") or "")).upper()
    typ = str(a.get("account_type") or "").lower()
    return typ in ("funded", "winning_days") or "EXPRESS" in kenn or "XFA" in kenn


def plan_balance_relativ(p):
    """REIN RECHNEND (testbar): balance_relativ der TopstepX-Lesungen eines Plans (tv beim Start, sonst final beim Ende) → bool | None."""
    base = (p or {}).get("mt5_baseline") if isinstance((p or {}).get("mt5_baseline"), dict) else {}
    for k in ("tv", "final"):
        v = base.get(k).get("balance_relativ") if isinstance(base.get(k), dict) else None
        if isinstance(v, bool):
            return v
    return None


def konto_basis_balance(acc, relativ=None):
    """REIN RECHNEND (testbar, B25): Balance, bei der ein frisches Konto startet — Topstep Express 0 $, sonst die Kontogröße
    (starting_balance, sonst „150k" aus dem Namen). None = unbekannt. relativ wie ist_topstep_express."""
    return 0.0 if ist_topstep_express(acc, relativ) else _wd_konto_groesse(acc)


def kurs_jetzt_wahl(zeilen):
    """REIN RECHNEND (testbar, B35/F28): letzte Reader-Minute je Wurzel → {wurzel: {kurs, minute}}. NQ und MNQ laufen
    preisgleich — fehlt eine Wurzel, übernimmt sie den Kurs der anderen (quelle = die andere Wurzel)."""
    out = {}
    for z in zeilen or ():
        w = str(z.get("wurzel") or "").upper()
        c = _wd_num(z.get("c"))
        if w in ("NQ", "MNQ") and c is not None and (w not in out or str(z.get("minute")) > str(out[w]["minute"])):
            out[w] = {"kurs": c, "minute": z.get("minute"), "quelle": w}
    for w, andere in (("NQ", "MNQ"), ("MNQ", "NQ")):
        if w not in out and andere in out:
            out[w] = dict(out[andere])
    return out


def _kurs_jetzt():
    """Letzte Reader-Minute je Wurzel aus tv_kurs_1m (zwei kleine Abfragen). Fehler → {}."""
    try:
        zeilen = []
        for w in ("NQ", "MNQ"):
            zeilen += sb_select("tv_kurs_1m", {"select": "wurzel,minute,c", "wurzel": f"eq.{w}", "order": "minute.desc", "limit": "1"}) or []
        return kurs_jetzt_wahl(zeilen)
    except Exception as e:
        print(f"[kurs-jetzt] ⚠️ {type(e).__name__}: {e}", flush=True)
        return {}


def plan_ist_wd(plan, typ=""):
    """REIN RECHNEND (testbar): Winning-Day-Plan? Kontoart/konto_typ 'winning_days' oder Fusion-Hedge (hedge_eur > 0) — AUSSER Orbit V3
    (trade_plans.orbit_v3, 01.10.2026): tvv2 + Fusion-Hedge, aber normaler Master-SL statt Liquidations-Level. Finn am Radar: „die Order hat
    einen Stop Loss — statt Liquidationspreis soll der Stop Loss angezeigt werden". Gleiche Regel wie tpIstWdPlan/hedgeIstWd im Frontend."""
    plan = plan or {}
    if plan.get("orbit_v3") is True:
        return False
    return (str(typ or "").lower() == "winning_days" or str(plan.get("konto_typ") or "") == "winning_days"
            or (_wd_num(plan.get("hedge_eur")) or 0) > 0)


def _lt_liq_balance(acc, plan, balance_start):
    """REIN RECHNEND (testbar): Balance, bei der das Konto blowt → (wert, regel) oder (None, grund).
    B25: Topstep Express startet bei 0 $ — dort nie „Kontogröße + 100", sondern wie jedes andere Konto Max-Drawdown."""
    typ = str((acc or {}).get("account_type") or "").lower()
    wd = plan_ist_wd(plan, typ)
    if wd and not ist_topstep_express(acc, plan_balance_relativ(plan)):
        g = _wd_konto_groesse(acc)
        return (g + LT_WD_BLOW_PLUS, f"Winning Day: Kontogröße {g:,.0f} + {LT_WD_BLOW_PLUS:,.0f} $".replace(",", ".")) if g else (None, "Kontogröße unbekannt")
    dd = _wd_num((acc or {}).get("max_drawdown"))
    if balance_start is None:
        return None, "keine Start-Balance"
    return (balance_start - dd, f"Start-Balance − Max-Drawdown {dd:,.0f} $".replace(",", ".")) if dd else (None, "kein Max-Drawdown am Konto")


def _lt_liq(acc, plan, balance_start, einstieg, richtung, ppl, kt):
    """REIN RECHNEND (testbar): Liquidation eines Trades → {level, balance, regel, pl_usd}.
    Winning Day: Level aus Start-Balance − (Kontogröße + 100 $), ohne Start-Balance keins. Sonst: Max-Drawdown als SL-Abstand
    in $ bei den Kontrakten des Plans (Finn 26.09.2026) — Level ohne Start-Balance; balance = Start − Max-Drawdown nur mit
    Start-Balance; pl_usd bei Liquidation = −Max-Drawdown."""
    liq_bal, regel = _lt_liq_balance(acc, plan, balance_start)
    typ = str((acc or {}).get("account_type") or "").lower()
    wd = plan_ist_wd(plan, typ)
    if wd and not ist_topstep_express(acc, plan_balance_relativ(plan)):
        level = None
        if balance_start is not None and liq_bal is not None and balance_start > liq_bal:
            level = _wd_level(einstieg, richtung, balance_start - liq_bal, ppl, kt, False)
        pl = round(liq_bal - balance_start, 2) if (balance_start is not None and liq_bal is not None) else None
        return {"level": level, "balance": liq_bal, "regel": regel, "pl_usd": pl}
    dd = _wd_num((acc or {}).get("max_drawdown"))
    if not dd or dd <= 0:
        return {"level": None, "balance": None, "regel": "kein Max-Drawdown am Konto", "pl_usd": None}
    return {"level": _wd_level(einstieg, richtung, dd, ppl, kt, False),
            "balance": round(balance_start - dd, 2) if balance_start is not None else None,
            "regel": f"Max-Drawdown {dd:,.0f} $ als SL".replace(",", "."), "pl_usd": -round(dd, 2)}


# ══ LIQ-REGELN (30.09.2026, Finn: „Die Liquidation ist bei uns immer der Stop Loss bzw. das Daily Loss, das nutzen wir immer
# komplett aus. Leg dafür eine Tabelle an"). Anlass Radar .853: Moritz Apex …0008 (Winning Days, BUY 3 × NQ) zeigte die Liquidation
# bei Kontogröße + 100 $ (≈ 155 Pkt unter dem Einstieg) — echt gilt Apex-Stufe 3, 3.000 $ Daily Loss ab Tagesstart-Balance (50 Pkt).
# Tabelle public.liq_regeln (sql/2026-09-30_liq-regeln*.sql). NUR ANZEIGE: zusätzliche Felder liq_regel_balance / _level_nq / _text in
# /admin/live-trades (_lt_zeile). liq_level_nq, wd_sl_zeile, hedge.sl_level_nq und die Hedge-Open-Rechnung bleiben unverändert — der
# Fusion-Hedge der Winning Days schließt weiter bei Kontogröße + 100 $ (echtes Geld), bis Finn es ausdrücklich anders entscheidet.
LIQ_REGELN_CACHE_S = 60
_liq_regeln_cache = {"at": 0.0, "zeilen": None}


def _liq_regeln_laden():
    """public.liq_regeln, höchstens einmal je LIQ_REGELN_CACHE_S Sekunden gelesen (kleine Tabelle). Fehler → letzter Stand bzw. []."""
    jetzt = time.time()
    if _liq_regeln_cache["zeilen"] is not None and jetzt - _liq_regeln_cache["at"] < LIQ_REGELN_CACHE_S:
        return _liq_regeln_cache["zeilen"]
    try:
        try:
            zeilen = _sb_all("liq_regeln", {"select": "id,firma,kontotyp,groesse,art,betrag_usd,lock_ueber_start_usd,stufen,wie_kontotyp,"
                                                      "maxdd_art,maxdd_lock_ueber_groesse_usd,maxdd_usd"})
        except Exception:
            # Spalten des Konto-Bodens (sql/2026-09-30_liq-kontoboden.sql) noch nicht da → Regeln wie bisher, Boden statisch
            zeilen = _sb_all("liq_regeln", {"select": "id,firma,kontotyp,groesse,art,betrag_usd,lock_ueber_start_usd,stufen,wie_kontotyp"})
        _liq_regeln_cache.update(at=jetzt, zeilen=zeilen or [])
    except Exception as e:
        print(f"[liq-regeln] ⚠️ {type(e).__name__}: {e}", flush=True)
        _liq_regeln_cache["at"] = jetzt          # nicht bei jedem Abruf neu versuchen
        if _liq_regeln_cache["zeilen"] is None:
            _liq_regeln_cache["zeilen"] = []
    return _liq_regeln_cache["zeilen"]


def liq_regel_waehlen(regeln, firma, kontotyp, groesse):
    """REIN RECHNEND (testbar): passende liq_regeln-Zeile → (zeile | None, weg). Die spezifischste gewinnt (Firma 4, Kontotyp 2,
    Größe 1 Punkt; null = alle). Firmen normalisiert (_firm_norm). wie_kontotyp wird EINMAL aufgelöst (Winning Days → Regel der
    Firma im Funded-Zustand); weg nennt das („winning_days wie funded"), sonst ''."""
    f = _firm_norm(firma).lower() if firma else ""
    g = _wd_num(groesse)

    def beste(typ):
        best, score = None, -1
        for r in regeln or ():
            rf, rt, rg = r.get("firma"), r.get("kontotyp"), _wd_num(r.get("groesse"))
            if rf and _firm_norm(rf).lower() != f:
                continue
            if rt and rt != typ:
                continue
            if rg is not None and (g is None or abs(rg - g) > 0.5):
                continue
            s = (4 if rf else 0) + (2 if rt else 0) + (1 if rg is not None else 0)
            if s > score:
                best, score = r, s
        return best

    z = beste(kontotyp)
    wie = (z or {}).get("wie_kontotyp")
    if wie and wie != kontotyp:
        z2 = beste(wie)
        if z2:
            return z2, f"{kontotyp} wie {wie}"
    return z, ""


def liq_stufe(stufen, balance):
    """REIN RECHNEND (testbar): Stufe mit dem höchsten ab_balance ≤ balance (darunter: die erste) → (nr ab 1, stufe) | (None, None)."""
    st = sorted([s for s in (stufen or []) if isinstance(s, dict) and _wd_num(s.get("ab_balance")) is not None],
                key=lambda s: _wd_num(s["ab_balance"]))
    if not st or balance is None:
        return None, None
    nr = 0
    for i, s in enumerate(st):
        if balance >= _wd_num(s["ab_balance"]):
            nr = i
    return nr + 1, st[nr]


def _liq_de(v, d=0):
    return f"{v:,.{d}f}".replace(",", "X").replace(".", ",").replace("X", ".")


def liq_aus_regel(regel, groesse, balance_start, tagesstart):
    """REIN RECHNEND (testbar): Liquidations-Balance nach einer liq_regeln-Zeile → (balance | None, text).
    fest           Start-Balance − Betrag           trailing_lock  min(Start-Balance − Betrag, Größe + Lock)
    tagesstart     Tagesstart − Betrag              stufen         Tagesstart − Daily Loss der Stufe (Stufe nach Tagesstart)
    boden          Größe (der Zeile, sonst des Kontos) + Lock
    Tagesstart fehlt → Start-Balance (dann ist dieser Trade der erste des Handelstags). Ohne nötige Werte → (None, Grund)."""
    if not regel:
        return None, "keine Liq-Regel für dieses Konto"
    art, b = regel.get("art"), _wd_num(regel.get("betrag_usd"))
    lock = _wd_num(regel.get("lock_ueber_start_usd")) or 0.0
    gr = _wd_num(regel.get("groesse")) or _wd_num(groesse)
    ts = tagesstart if tagesstart is not None else balance_start
    if art == "fest" and b:
        if balance_start is None:
            return None, f"fest {_liq_de(b)} $ — keine Start-Balance"
        return round(balance_start - b, 2), f"fest {_liq_de(b)} $ ab Start-Balance"
    if art in ("trailing_lock", "boden") and not gr:
        return None, f"{art} — Kontogröße unbekannt"
    if art == "trailing_lock" and b:
        if balance_start is None:
            return None, f"{_liq_de(b)} $ trailing — keine Start-Balance"
        return round(min(balance_start - b, gr + lock), 2), f"{_liq_de(b)} $ trailing, fest ab {_liq_de(gr + lock)} $"
    if art == "boden":
        return round(gr + lock, 2), f"Boden {_liq_de(gr)} + {_liq_de(lock)} $"
    if art == "tagesstart" and b:
        if ts is None:
            return None, f"Daily Loss {_liq_de(b)} $ — keine Tagesstart-Balance"
        return round(ts - b, 2), f"Daily Loss {_liq_de(b)} $ ab Tagesstart {_liq_de(ts, 2)} $"
    if art == "stufen":
        if ts is None:
            return None, "Stufen — keine Tagesstart-Balance"
        nr, st = liq_stufe(regel.get("stufen"), ts)
        dl = _wd_num((st or {}).get("daily_loss_usd"))
        if not dl:
            return None, "Stufen ohne Daily Loss"
        return round(ts - dl, 2), (f"Stufe {nr} (ab {_liq_de(_wd_num(st['ab_balance']))} $): Daily Loss {_liq_de(dl)} $ "
                                   f"ab Tagesstart {_liq_de(ts, 2)} $")
    return None, "Liq-Regel offen"


def liq_tagesstart(p, start_bal, fruehere):
    """REIN RECHNEND (testbar): Balance zu Beginn des CME-Handelstags dieses Plans → (wert | None, quelle). Früher gestarteter
    Plan desselben Kontos im selben Handelstag mit Start-Balance → die des FRÜHESTEN; sonst ist dieser Plan der erste des Tages →
    start_bal. fruehere = [{id, master_account_id, started_at, bal_start}] (_wd_fruehere_trades)."""
    st = str(p.get("started_at") or "")
    tag = _cme_handelstag(st) if st else None
    acc = str(p.get("master_account_id") or "")
    kand = [f for f in (fruehere or []) if str(f.get("master_account_id") or "") == acc and str(f.get("id")) != str(p.get("id"))
            and f.get("started_at") and str(f["started_at"]) < st and _wd_num(f.get("bal_start")) is not None
            and _cme_handelstag(f["started_at"]) == tag]
    if tag and kand:
        f = min(kand, key=lambda x: str(x["started_at"]))
        return _wd_num(f["bal_start"]), "erster Trade des Handelstags"
    return start_bal, "Start-Balance dieses Trades"


_liq_kw_cache = {"at": 0.0, "firmen": None}


def _liq_kw_laden():
    """auto_plan_regeln.regeln.firmen (Kernwerte je Firma) für den Konto-Boden weicher Tagesstopps (liq_boden_kernwerte), höchstens
    einmal je LIQ_REGELN_CACHE_S Sekunden gelesen. Fehler → letzter Stand bzw. None (dann rechnet der Boden wie bisher)."""
    jetzt = time.time()
    if _liq_kw_cache["firmen"] is not None and jetzt - _liq_kw_cache["at"] < LIQ_REGELN_CACHE_S:
        return _liq_kw_cache["firmen"]
    try:
        reg = (sb_select("auto_plan_regeln", {"select": "regeln", "id": "eq.1"}) or [{}])[0]
        _liq_kw_cache.update(at=jetzt, firmen=list(((reg or {}).get("regeln") or {}).get("firmen") or []))
    except Exception as e:
        print(f"[liq-kernwerte] ⚠️ {type(e).__name__}: {e}", flush=True)
        _liq_kw_cache["at"] = jetzt
    return _liq_kw_cache["firmen"]


# ══ KONTO-BODEN (LIQ-KONTOBODEN, 30.09.2026, Finn: „Der Account hat insgesamt 4.000 $ Drawdown. Ich habe schon 2.500 $ verloren, von
# 150.000 auf 147.500. Beim nächsten Trade ist die Liquidation nur noch 1.500 $ entfernt, nicht wieder 4.000."). Die Regel aus liq_regeln
# rechnet ab der Balance beim Trade-Start — nach einem Verlust ist das zu viel Luft. Daneben jetzt der absolute Boden des Kontos aus dem
# Max Drawdown (statisch: Größe − DD; eod_trailing: höchste belegte End-Balance − DD, gedeckelt beim Lock). Die Liquidation im Radar
# ist die ENGERE (höhere) der beiden. Nur Anzeige wie liq_regeln — der Fusion-Hedge rechnet unverändert.
LIQ_VERLAUF_CACHE_S = 60
_liq_verlauf_cache = {}


def _liq_verlauf_laden(acc_ids, streng=False):
    """Belegte Balances (tv.balance_start, final.balance_end) aller Orbit-/Topstep-V2-Pläne der Konten, ohne Zeitgrenze (der Höchststand
    kann älter als 14 Tage sein) — je Konto 60 s gecacht, Fehler → [] (dann rechnet der Boden ab Kontogröße bzw. Start-Balance).
    streng=True (Topstep-Kette mit DLL, Prüfung Slave 2 08.10.2026): der Fehler wird weitergereicht — dort hängt eine Handelsentscheidung
    (MLL) daran, ein stilles [] ergäbe einen zu tiefen MLL."""
    jetzt, out, fehlt = time.time(), [], []
    for a in sorted({str(x) for x in acc_ids if x}):
        c = _liq_verlauf_cache.get(a)
        if c and jetzt - c[0] < LIQ_VERLAUF_CACHE_S:
            out += c[1]
        else:
            fehlt.append(a)
    try:
        for i in range(0, len(fehlt), 80):
            teil = fehlt[i:i + 80]
            zeilen = _sb_all("trade_plans", {"select": "id,master_account_id,konto_typ,started_at,ended_at,"
                                                       "bal_end:mt5_baseline->final->balance_end,bal_start:mt5_baseline->tv->balance_start",
                                             "master_account_id": f"in.({','.join(teil)})", "route": "in.(tvv2,tsv2)"})
            je = {a: [] for a in teil}
            for z in zeilen or []:
                je.setdefault(str(z.get("master_account_id")), []).append(z)
            for a, l in je.items():
                _liq_verlauf_cache[a] = (jetzt, l)
                out += l
    except Exception as e:
        print(f"[liq-verlauf] ⚠️ {type(e).__name__}: {e}", flush=True)
        if streng:
            raise
    return out


def liq_peak(p, acc, start_bal, verlauf):
    """REIN RECHNEND (testbar): höchste BELEGTE Balance des Kontos in seiner aktuellen Phase VOR dem Start dieses Trades → wert | None.
    Belegt = final.balance_end früherer Pläne (Ende vor diesem Start), tv.balance_start früherer Pläne, die Start-Balance dieses Trades
    und accounts.tv_balance (gelesen vor diesem Start). Phase = trade_plans.konto_typ gleich der Kontoart — Höchststände aus der
    Challenge heben den Funded-Boden nicht (dieselbe Konto-Zeile wechselt die Phase). Pläne ohne konto_typ zählen nicht."""
    a = acc or {}
    typ, aid = str(a.get("account_type") or "").lower(), str(a.get("id") or p.get("master_account_id") or "")
    st = str(p.get("started_at") or "")
    werte = [start_bal] if start_bal is not None else []
    for f in verlauf or ():
        if str(f.get("master_account_id") or "") != aid or str(f.get("id")) == str(p.get("id")):
            continue
        if not f.get("konto_typ") or str(f.get("konto_typ")).lower() != typ:
            continue
        be, bs = _wd_num(f.get("bal_end")), _wd_num(f.get("bal_start"))
        if be is not None and f.get("ended_at") and (not st or str(f["ended_at"]) <= st):
            werte.append(be)
        if bs is not None and f.get("started_at") and (not st or str(f["started_at"]) <= st):
            werte.append(bs)
    tvb = _wd_num(a.get("tv_balance"))
    if tvb is not None and a.get("tv_balance_at") and (not st or str(a["tv_balance_at"]) <= st):
        werte.append(tvb)
    werte = [w for w in werte if w is not None and w > 0]
    return max(werte) if werte else None


def liq_konto_groesse(acc):
    """REIN RECHNEND (testbar): Kontogröße NUR für den Konto-Boden — _wd_konto_groesse, sonst die Größe aus dem Kürzel in Name bzw.
    External ID (Tradeify TDFYSL150…/FTDFYSLX150…, Topstep 150KTC-…). Rund 60 Konten tragen die Größe nur so. _wd_konto_groesse selbst
    bleibt unverändert, weil der Fusion-Hedge der Winning Days daran hängt (Größe + 100 $)."""
    g = _wd_konto_groesse(acc)
    if g:
        return g
    kenn = (str((acc or {}).get("name") or "") + " " + str((acc or {}).get("external_id") or "")).upper()
    m = re.search(r"F?TDFYSLX?(150|100|50|25)", kenn) or re.search(r"\b(150|100|50)KTC", kenn)
    return float(m.group(1)) * 1000 if m else None


def liq_konto_boden(regel, acc, groesse, peak, start_bal, relativ=None):
    """REIN RECHNEND (testbar): absoluter Konto-Boden aus dem Max Drawdown → (boden | None, text, max_dd | None, art | None).
    statisch: Größe − DD. eod_trailing: max(Größe, peak) − DD, höchstens Größe + maxdd_lock_ueber_groesse_usd (null = kein Lock).
    DD aus accounts.max_drawdown, sonst maxdd_usd der Regel. Topstep Express (Start bei 0 $) und ein Boden, der nicht unter der
    Start-Balance liegt (Datenzweifel), werden nicht angewandt."""
    a = acc or {}
    if ist_topstep_express(a, relativ):
        return None, "Topstep Express — Boden = MLL aus TopstepX", None, None
    dd = _wd_num(a.get("max_drawdown")) or _wd_num((regel or {}).get("maxdd_usd"))
    if not dd or dd <= 0:
        return None, "kein Max Drawdown am Konto", None, None
    if not groesse:
        return None, "Kontogröße unbekannt", dd, None
    art = (regel or {}).get("maxdd_art") or "statisch"
    if art == "eod_trailing":
        bezug = max(groesse, peak) if peak else groesse
        boden, lock = bezug - dd, _wd_num((regel or {}).get("maxdd_lock_ueber_groesse_usd"))
        gelockt = lock is not None and boden >= groesse + lock
        if gelockt:
            boden = groesse + lock
        text = (f"Konto-Boden {_liq_de(boden)} $ (Max DD {_liq_de(dd)} $, EOD-trailing ab Höchststand {_liq_de(bezug, 2)} $"
                + (f", Lock bei {_liq_de(groesse + lock)} $" if gelockt else "") + ")")
    else:
        art, boden = "statisch", groesse - dd
        text = f"Konto-Boden {_liq_de(boden)} $ (Max DD {_liq_de(dd)} $, statisch ab {_liq_de(groesse)} $)"
    if start_bal is not None and boden >= start_bal:
        return None, text + " — liegt nicht unter der Balance, nicht angewandt", dd, art
    return round(boden, 2), text, dd, art


def liq_boden_kernwerte(regel, acc, typ, wd, kw_firmen):
    """REIN RECHNEND (testbar): Regel, Konto und Kontogröße für liq_konto_boden → (regel, acc, groesse).
    APEX-EVAL-SOFTBREACH (07.10.2026, Finn am Radar: Apex-150k-Eval · Orbit V2 · BUY 3×NQ · Balance 148.097 $ · −1.884,30 $ stand als
    „💀 geblowt" — „Apex 150k Evaluation: Daily Loss 2.000 $ ist ein SOFT BREACH. Der Tag stoppt, das Konto lebt weiter. Geblowt
    ist es erst beim Gesamt-Drawdown 4.000 $, also Balance ≤ 146.000"). Ursache: am Konto stand max_drawdown 400 statt 4.000
    (bekannter Einzelfehler, siehe ap_kw_param) → Konto-Boden 149.600 statt 146.000. Für Konten mit weichem Tagesstopp (liq_regeln
    art tagesstart/stufen = Apex) in der Prüfphase (challenge/phase1/phase2) gilt deshalb der Gesamt-Drawdown der Kernwerte
    (auto_plan_regeln.regeln.firmen[], dd_usd + boden) statt accounts.max_drawdown — dieselbe Quelle wie Planer und Vorrat.
    Ohne Kernwerte bzw. für alle anderen Firmen/Phasen (Apex Funded mit Lock, Tradeify, Topstep, CFD) unverändert."""
    a, gr = acc or {}, liq_konto_groesse(acc)
    if kw_firmen is None or wd or (regel or {}).get("art") not in ("tagesstart", "stufen") or typ not in ("challenge", "phase1", "phase2"):
        return regel, a, gr
    kw = ap_kw_param(ap_regel_finden(kw_firmen, a.get("firm")))
    dd = _wd_num((kw or {}).get("dd_usd"))
    if not kw or not dd or kw.get("dd_pct"):
        return regel, a, gr
    if not gr and len(kw.get("groessen") or []) == 1:      # Apex nur 150k: Größe aus den Kernwerten, wenn Name/Startwert sie nicht tragen
        gr = float(kw["groessen"][0])
    return (dict(regel, maxdd_usd=dd, maxdd_art="statisch" if kw.get("boden") == "statisch" else (regel.get("maxdd_art") or "statisch")),
            dict(a, max_drawdown=None), gr)


def _liq_pl_de(v):
    return None if v is None else f"{'−' if v < 0 else '+'}{_liq_de(abs(v))} $"


def liq_regel_felder(regeln, acc, plan, start_bal, tagesstart, einstieg, richtung, ppl, kt, peak=None, mll=None, kw_firmen=None):
    """REIN RECHNEND (testbar): Anzeige-Felder einer /admin/live-trades-Zeile → {liq_regel_balance, liq_regel_level_nq,
    liq_regel_text, liq_gilt, liq_regel_nur_balance, liq_boden_balance, liq_boden_text, liq_maxdd, liq_maxdd_art, liq_vergleich_text}.
    liq_regel_balance/_level_nq = die EFFEKTIVE Liquidation: die engere (höhere Balance) von Regel (liq_regeln, unverändert) und
    Konto-Boden (liq_konto_boden; bei Topstep V2 mit gelesener MLL die MLL selbst). Level = Abstand (Start-Balance − Liq-Balance) als
    $-SL ab Einstieg (_wd_level). art fest geht auch ohne Start-Balance (Abstand = Betrag). Winning Day wie in _lt_liq_balance erkannt;
    dort liegt der Boden der Regel (Größe + 100) ohnehin gleich oder enger."""
    a = acc or {}
    typ = str(a.get("account_type") or "").lower()
    wd = plan_ist_wd(plan, typ)
    groesse = _wd_konto_groesse(a)
    regel, weg = liq_regel_waehlen(regeln, a.get("firm"), "winning_days" if wd else (typ or None), groesse)
    r_bal, r_text = liq_aus_regel(regel, groesse, start_bal, tagesstart)
    if weg:
        r_text = f"{r_text} ({weg})"
    if mll is not None:
        b_bal, b_text, dd, art = mll, f"MLL TopstepX {_liq_de(mll, 2)} $", None, "mll"
    else:
        b_regel, b_acc, b_gr = liq_boden_kernwerte(regel, a, typ, wd, kw_firmen)
        b_bal, b_text, dd, art = liq_konto_boden(b_regel, b_acc, b_gr, peak, start_bal, plan_balance_relativ(plan))
    kand = [(v, k) for v, k in ((r_bal, "regel"), (b_bal, "boden")) if v is not None]
    bal, gilt = max(kand) if kand else (None, None)        # gleich hoch → „regel" (Tupel-Vergleich, 'regel' > 'boden')
    text = b_text if gilt == "boden" else r_text
    abstand = None
    if bal is not None and start_bal is not None:
        abstand = start_bal - bal
        if abstand <= 0:
            text += " — Start-Balance liegt nicht darüber"
    elif regel and regel.get("art") == "fest" and _wd_num(regel.get("betrag_usd")):
        abstand, gilt, text = _wd_num(regel.get("betrag_usd")), "regel", r_text
    level = _wd_level(einstieg, richtung, abstand, ppl, kt, False) if (abstand or 0) > 0 else None

    def teil(v, t, k):
        pl = _liq_pl_de(v - start_bal) if (v is not None and start_bal is not None) else None
        return f"{t}{' → ' + pl if pl else ''}{' ✓ gilt' if gilt == k and len(kand) > 1 else ''}"
    vergleich = None
    if b_bal is not None and r_bal is not None:
        vergleich = " · ".join([teil(b_bal, b_text, "boden"), "Regel: " + teil(r_bal, r_text, "regel")])
    return {"liq_regel_balance": bal, "liq_regel_level_nq": level, "liq_regel_text": text, "liq_gilt": gilt,
            "liq_regel_nur_balance": r_bal, "liq_boden_balance": b_bal, "liq_boden_text": b_text, "liq_maxdd": dd,
            "liq_maxdd_art": art, "liq_vergleich_text": vergleich,
            # Art der Regel (02.10.2026, Finn: „Apex Daily Loss ist nur ein Soft-Breach, kein Blow") — 'tagesstart'/'stufen' sind
            # Tageslimits: Positionen zu, Konto lebt. Echter Blow nur am Konto-Boden (liq_boden_balance). Das Radar trennt danach.
            "liq_regel_art": (regel or {}).get("art"), "liq_regel_soft": (regel or {}).get("art") in ("tagesstart", "stufen")}


def lt_demo_liq(liq_level, liq_pl_alt, regel_f, start_bal, einstieg, richtung, ppl, kt):
    """REIN RECHNEND (testbar, DEMO-LIQ 30.09.2026, Master: „Spanne, Chart und Demo sollen übereinstimmen"): Liquidations-Level und
    $ beim Erreichen für die Radar-Demo → (level, pl_usd). liq_regel_level_nq (liq_regeln) vor dem alten Level; $ = Liq-Balance −
    Start-Balance, ohne Balance aus dem Level ((Level − Einstieg) × Richtung × Punktwert × Kontrakte). Ohne Regel-Level wie bisher.
    Nur die Demo — der Fusion-Hedge rechnet unverändert mit liq_level_nq/hedge.sl_level_nq."""
    lvl = (regel_f or {}).get("liq_regel_level_nq")
    if lvl is None:
        return liq_level, liq_pl_alt
    rb = (regel_f or {}).get("liq_regel_balance")
    if rb is not None and start_bal is not None:
        return lvl, round(rb - start_bal, 2)
    ri = 1 if richtung == "buy" else -1 if richtung == "sell" else 0
    try:
        pl = round((float(lvl) - float(einstieg)) * ri * float(ppl) * float(kt), 2) if (einstieg and ppl and kt and ri) else None
    except (TypeError, ValueError):
        pl = None
    return lvl, pl


def _lt_demo(richtung, tp_level, liq_level, kerzen, start_iso, ende_iso=None, sl_level=None):
    """REIN RECHNEND (testbar): Demo-Ausführung gegen Minutenkerzen [{minute, h, l}] ab der Start-Minute.
    → {status: 'tp'|'liquidiert'|'beide_in_minute'|'laeuft'|'beendet_ohne_treffer'|'ohne_kurs'|'ohne_level', at, preis, minuten}.
    BUY: TP bei h ≥ TP, Liquidation bei l ≤ Level; SELL gespiegelt. Beide in derselben Minute: Reihenfolge unbekannt.
    ende_iso (B5, 26.09.2026, Finns Screenshot: Moritz Apex …0008 SELL 6 MNQ „zu 26.09., 01:17" zeigte „Demo läuft · 543 Minuten"):
    Kerzen NACH der Ende-Minute zählen nicht; ohne Treffer bis zum Ende → 'beendet_ohne_treffer' (at = Ende).
    EINSTIEGSMINUTE ZÄHLT NICHT (29.09.2026, Finns Live-Test Plan b2f630e6: Kauf 16:41:37 @ 30543.5, TP 30555.25 — das Hoch der Kerze
    16:41 (30558.75) lag VOR dem Kauf, die Demo meldete „TP 16:41", in TradingView traf 16:43 der SL). Gewertet wird ab der Minute
    NACH dem Start; ein Treffer in den Sekunden nach dem Fill bleibt der Nachlesung/„Beendet" überlassen.
    sl_level (29.09.2026): echter Stop-Loss (Bracket/master_sl) — beendet die Demo wie eine Liquidation (status 'liquidiert',
    stop 'sl'); ohne SL wie bisher die Liquidation."""
    if richtung not in ("buy", "sell") or tp_level is None:
        return {"status": "ohne_level"}
    try:
        t0 = datetime.fromisoformat(str(start_iso).replace("Z", "+00:00")).replace(second=0, microsecond=0)
    except (TypeError, ValueError):
        return {"status": "ohne_level"}
    ks = []
    for k in kerzen or []:
        try:
            m = datetime.fromisoformat(str(k.get("minute")).replace("Z", "+00:00"))
            ks.append((m, float(k.get("h")), float(k.get("l"))))
        except (TypeError, ValueError):
            continue
    t1 = None
    if ende_iso:
        try:
            t1 = datetime.fromisoformat(str(ende_iso).replace("Z", "+00:00")).replace(second=0, microsecond=0)
        except (TypeError, ValueError):
            t1 = None
    im_fenster = [k for k in ks if k[0] >= t0 and (t1 is None or k[0] <= t1)]
    ks = sorted([k for k in im_fenster if k[0] > t0], key=lambda k: k[0])   # ohne die Einstiegsminute (s. o.)
    if not ks:
        if im_fenster and t1 is None:                                        # nur die Einstiegsminute da: läuft, noch nichts gewertet
            return {"status": "laeuft", "minuten": 0, "letzte_minute": t0.isoformat()}
        return {"status": "ohne_kurs"}
    stop = sl_level if sl_level is not None else liq_level
    for m, h, l in ks:
        tp = (h >= tp_level) if richtung == "buy" else (l <= tp_level)
        liq = stop is not None and ((l <= stop) if richtung == "buy" else (h >= stop))
        if tp and liq:
            return {"status": "beide_in_minute", "at": m.isoformat(), "preis": None, "minuten": len(ks)}
        if tp:
            return {"status": "tp", "at": m.isoformat(), "preis": tp_level, "minuten": len(ks)}
        if liq:
            aus = {"status": "liquidiert", "at": m.isoformat(), "preis": stop, "minuten": len(ks)}
            if sl_level is not None:
                aus["stop"] = "sl"
            return aus
    if t1 is not None:
        return {"status": "beendet_ohne_treffer", "at": t1.isoformat(), "minuten": len(ks), "letzte_minute": ks[-1][0].isoformat()}
    return {"status": "laeuft", "minuten": len(ks), "letzte_minute": ks[-1][0].isoformat()}


def _lt_kerze_start(kerzen, start_iso):
    """REIN RECHNEND (testbar): Einstieg eines Handstarts aus Minutenkerzen [{minute, h, l}] — Mitte (h+l)/2 der Kerze der
    Start-Minute, sonst die erste bis 3 min danach; auf 0,25 gerundet. None ohne passende Kerze."""
    try:
        t0 = datetime.fromisoformat(str(start_iso).replace("Z", "+00:00")).replace(second=0, microsecond=0)
    except (TypeError, ValueError):
        return None
    best = None
    for k in kerzen or []:
        try:
            m = datetime.fromisoformat(str(k.get("minute")).replace("Z", "+00:00"))
            h, l = float(k.get("h")), float(k.get("l"))
        except (TypeError, ValueError):
            continue
        d = (m - t0).total_seconds()
        if 0 <= d <= 180 and h > 1000 and l > 1000 and (best is None or d < best[0]):
            best = (d, h, l)
    return None if best is None else round((best[1] + best[2]) / 2 * 4) / 4


def lt_pl_balance(route, tv, fin):
    """REIN RECHNEND (testbar, 05.10.2026, Topstep V2 im Radar): pl_balance der Radar-Zeile = Balance nachher − vorher → Zahl | None.
    Topstep V2 (tsv2): TopstepX zeigt ein Express-Konto 0-basiert (balance_relativ), sonst die volle Balance. Sagen Start- und
    End-Lesung ausdrücklich verschiedene Basen (beide bool, ungleich), gibt es KEINE Differenz — sonst stünde die Kontogröße als
    P&L in der Zeile. Dieselbe Bedingung wie wd_tsx_master_pl; fehlt die Angabe auf einer Seite, wird gerechnet wie bisher.
    Jede andere Route: unverändert die einfache Differenz."""
    tv, fin = tv or {}, fin or {}
    bs, be = _wd_num(tv.get("balance_start")), _wd_num(fin.get("balance_end"))
    if bs is None or be is None:
        return None
    if route == "tsv2":
        ra, rb = tv.get("balance_relativ"), fin.get("balance_relativ")
        if isinstance(ra, bool) and isinstance(rb, bool) and ra != rb:
            return None
    return round(be - bs, 2)


# BALANCE-SPRUNG (08.10.2026, Master nach der Gegenprüfung, Fall ea91e359: Tradeify-WD, Balance 165.039,22 → 159.950,02 = −5.089,20,
# Tages-P&L −589,20 — dazwischen eine Auszahlung von 4.500 $ von der Balance; Hand-Eintrag −600, Hedge +182,64 passte nur zu ~−590).
# Balance nachher − vorher ist der Trade-P&L nur, solange nichts anderes die Balance bewegt (Auszahlung, Gebührenbuchung, Hand-Trade).
# Liegen Today's P&L beim Klick (tv.today_pnl_start, Topstep V2 älter rpl_start) und nach dem Ende (final.today_pnl) vom SELBEN
# CME-Handelstag vor (tv.datum_start == final.datum, Grenze 22:00 UTC), ist Ende − Start der Trade-P&L — nie today_pnl allein (Topstep-
# Kette: zwei Trades am Tag). Liegt die Balance-Differenz mehr als LT_BALANCE_SPRUNG_USD UNTER diesem Wert, gilt sie nicht als P&L: kein
# Automatik-Wert, Ergebnis-Wort „Balance-Sprung", Abhak-Popup mit dem Tages-P&L vorbelegt. Nur nach unten (Auszahlungen senken die Balance,
# Einzahlungen gibt es auf Prop-Konten nicht) und nur, wenn sich Today's P&L bewegt hat — hängt Total P/L (Ende = Start, Fall 8da04bfe:
# 12,6 vor und nach dem Trade, Balance −50,40), sagt er nichts, dann wie bisher die Balance-Differenz (Prüfung Slave 2 / Master 08.10.2026).
# Fehlt ein Wert / anderer Tag: wie bisher.
LT_BALANCE_SPRUNG_USD = 100.0


def lt_balance_sprung(route, tv, fin):
    """REIN RECHNEND (testbar): Balance-Sprung eines beendeten Puls-Plans → {balance, tages, differenz} | None (s. o.)."""
    tv, fin = tv or {}, fin or {}
    bal = lt_pl_balance(route, tv, fin)
    if bal is None:
        return None
    start = _wd_num(tv.get("today_pnl_start"))
    if start is None and route == "tsv2":
        start = _wd_num(tv.get("rpl_start"))
    ende = _wd_num(fin.get("today_pnl"))
    if start is None or ende is None or not fin.get("datum") or fin.get("datum") != tv.get("datum_start"):
        return None
    if abs(ende - start) < 0.005:
        return None                       # Total P/L hängt (unverändert) → keine Aussage
    tages = round(ende - start, 2)
    if bal >= tages - LT_BALANCE_SPRUNG_USD:
        return None                       # nur nach unten und mehr als die Schwelle
    return {"balance": bal, "tages": tages, "differenz": round(bal - tages, 2)}


def _lt_zeile(p, acc, disp, kerzen_je_wurzel, vorher=None, regeln=None, fruehere=None, verlauf=None, kw_firmen=None):
    z = _wd_heute_zeile(p, acc, disp, vorher)
    base = p.get("mt5_baseline") if isinstance(p.get("mt5_baseline"), dict) else {}
    tv = base.get("tv") if isinstance(base.get("tv"), dict) else {}
    fin = base.get("final") if isinstance(base.get("final"), dict) else {}
    bs, be = _wd_num(tv.get("balance_start")), _wd_num(fin.get("balance_end"))
    ppl, kt = WD_HEUTE_PPL.get(z.get("symbol_root") or ""), z.get("kt")
    # B14: Start-Balance wie /admin/wd-heute — balance_start, sonst frische Konto-Balance (Vorläufer), sonst keine
    start_bal, liq_quelle, _sa = wd_start_balance(p, tv, acc, vorher)
    liq = _lt_liq(acc, p, start_bal, z.get("einstieg_nq"), z.get("richtung"), ppl, kt)
    liq_bal, liq_regel, liq_level = liq["balance"], liq["regel"], liq["level"]
    ub = z.pop("_tsx", {}) or {}
    if ub.get("liq_balance") is not None:                  # F28: Topstep V2 — Liquidation = MLL TopstepX beim Start
        liq_bal, liq_regel, liq_level, liq_quelle = ub["liq_balance"], ub["liq_regel"], ub.get("liq_level_nq"), "mll_tsx"
        liq = dict(liq, pl_usd=ub.get("liq_pl_usd"))
    kerzen = kerzen_je_wurzel.get(z.get("symbol_root") or "") or []
    # HANDSTART (28.09.2026, Vorfall Jacob Apex …0002, Plan 2a6637b9: Puls füllte das Ticket, fand den Kauf-Knopf nicht —
    # „Nichts platziert"; Jacob kaufte selbst und setzte den Plan von Hand auf „Läuft". Ohne Puls-Fill fehlte jeder Einstieg,
    # der Radar zeigte keine Level, die Demo stand auf 'ohne_level' → kein Demo-Ende, keine Nachlesung. Finn: „jeder einzelne
    # Trade soll ins Prophos-Radar"). Kein Einstieg am Plan → Mitte der Minutenkerze beim Start (höchstens 3 min später, falls
    # der Feed dort eine Lücke hat), Quelle 'kerze_start'. Der PC-Tab friert den Wert danach am Plan ein (tvV2HandstartEinstieg).
    if z.get("einstieg_nq") is None and p.get("started_at") and z.get("richtung") in ("buy", "sell"):
        ek = _lt_kerze_start(kerzen, p.get("started_at"))
        if ek is not None:
            z["einstieg_nq"], z["einstieg_quelle"], z["level_quelle"] = ek, "kerze_start", "einstieg"
            z["tp_level_nq"] = z.get("tp_level_nq") or _wd_level(ek, z.get("richtung"), p.get("master_tp"), ppl, kt, True)
            if z.get("sl_level_nq") is None and z.get("sl_art") != "liquidation":
                z["sl_level_nq"] = _wd_level(ek, z.get("richtung"), p.get("master_sl"), ppl, kt, False)
            if ub.get("liq_balance") is None:          # Topstep V2 behält seine MLL aus TopstepX
                liq = _lt_liq(acc, p, start_bal, ek, z.get("richtung"), ppl, kt)
                liq_bal, liq_regel, liq_level = liq["balance"], liq["regel"], liq["level"]
    # LIQ-REGELN (30.09.2026): Anzeige-Felder aus liq_regeln — VOR der Demo, damit sie gegen dieselbe Liq rechnet wie Spanne und Chart
    regel_f = {}
    if regeln is not None:
        tagesstart, _tq = liq_tagesstart(p, start_bal, fruehere)
        # Konto-Boden (30.09.2026): Höchststand der Phase für EOD-trailing; Topstep V2 mit gelesener MLL nimmt die MLL als Boden
        regel_f = liq_regel_felder(regeln, acc, p, start_bal, tagesstart, z.get("einstieg_nq"), z.get("richtung"), ppl, kt,
                                   peak=liq_peak(p, acc, start_bal, verlauf), mll=ub.get("liq_balance"), kw_firmen=kw_firmen)
    demo_liq, demo_liq_pl = lt_demo_liq(liq_level, liq["pl_usd"], regel_f, start_bal, z.get("einstieg_nq"), z.get("richtung"), ppl, kt)
    # Ende (B5): beendete Trades rechnen die Demo nur bis zum Ende — ended_at, sonst final.at, sonst completed_at
    ende = None if str(p.get("status") or "") == "open" else (p.get("ended_at") or fin.get("at") or p.get("completed_at"))
    # echter SL (Bracket aus TradingView bzw. master_sl) beendet die Demo vor der Liquidation (29.09.2026); WD ('liquidation') nicht
    sl_demo = _wd_num(z.get("sl_level_nq")) if z.get("sl_art") in ("bracket", "master_sl") else None
    demo = _lt_demo(z.get("richtung"), z.get("tp_level_nq"), demo_liq, kerzen, p.get("started_at"), ende, sl_demo) if p.get("started_at") else {"status": "geplant"}
    if demo.get("status") == "tp":
        demo["pl_usd"] = _wd_num(p.get("master_tp"))
    elif demo.get("status") == "liquidiert" and demo.get("stop") == "sl":
        demo["pl_usd"] = -abs(_wd_num(p.get("master_sl"))) if _wd_num(p.get("master_sl")) is not None else None
    elif demo.get("status") == "liquidiert":
        demo["pl_usd"] = demo_liq_pl
    z.update({"balance_start": bs, "equity_start": _wd_num(tv.get("equity_start")), "balance_end": be,
              "pl_balance": lt_pl_balance(p.get("route"), tv, fin),
              "balance_sprung": lt_balance_sprung(p.get("route"), tv, fin),   # Auszahlung o. Ä. zwischen Start und Ende (08.10.2026)
              "liq_balance": liq_bal, "liq_regel": liq_regel, "liq_level_nq": liq_level, "demo": demo,
              "liq_quelle": liq_quelle if liq_level is not None else None,
              "konto_balance": _wd_num((acc or {}).get("tv_balance")), "konto_balance_at": (acc or {}).get("tv_balance_at")})
    z.update(regel_f)   # liq_regel_* nur zusätzlich — liq_level_nq/Hedge bleiben wie oben gerechnet
    return z


# ══ ECHO IM RADAR (30.09.2026, Finn: „im Radar oben die Orbit-Trades und darunter eine Sektion ‚Echo' — so sieht man auch bei
# Echo, wie nah ein Trade am TP bzw. an der Liquidation/dem SL ist"). Echo V2 (route mt5v2) hat KEINE NQ-Level und keine Demo:
# der Plan trägt TP/SL nur in $ und kein Symbol; die echten Werte stehen in der MT5-Cloud (mt5_live.status.master_positions,
# je Position ident = mt5_baseline.ticket, symbol, volume, type 0 buy/1 sell, price_open, sl, tp, contract_size) — geschrieben
# vom Copier bzw. vom PC-Panel der Lese-Instanz (lesen=true) alle paar Sekunden. Einen CFD-Kurs-Feed gibt es nicht (tv_kurse
# führt nur NQ/MNQ): der Kurs jetzt wird nur dann aus Equity − Balance zurückgerechnet, wenn die Plan-Position die EINZIGE
# offene des Kontos ist (sonst null) — Swap/Spread machen ihn zu einem ≈-Wert, quelle 'mt5_equity'. Opt-in über ?echo=1,
# damit PC-Tab-Takt, Winning Days und Live Trades unverändert bleiben (kein Mehr-Read für sie).
LT_ECHO_MAX_ALTER_S = 90       # ältere mt5_live-Zeilen gelten nicht als live (Position kann längst zu sein)
LT_ECHO_ROUTEN = ("mt5v2", "mt5")   # Echo V2 und (seit 01.10.2026 abends) das klassische Echo mit Fusion-Hedge


def lt_fusion_pl_echo(live, jetzt_ts):
    """REIN RECHNEND (testbar): schwebender Fusion-P&L eines klassischen Echo-Trades = Summe profit aller Hedges der Instanz
    (mt5_live.status.hedges {ident: [{profit, …}]}). Nur frisch (≤ LT_ECHO_MAX_ALTER_S) und mit mindestens einem Hedge, sonst None."""
    if not live:
        return None
    try:
        alter = jetzt_ts - datetime.fromisoformat(str(live.get("updated_at")).replace("Z", "+00:00")).timestamp()
    except (TypeError, ValueError):
        return None
    hd = live.get("hd")
    if alter > LT_ECHO_MAX_ALTER_S or not isinstance(hd, dict):
        return None
    werte = [_wd_num(h.get("profit")) for hs in hd.values() if isinstance(hs, list) for h in hs if isinstance(h, dict)]
    werte = [w for w in werte if w is not None]
    return round(sum(werte), 2) if werte else None


def lt_fusion_lots_echo(live, jetzt_ts):
    """REIN RECHNEND (testbar): Fusion-Lots eines klassischen Echo-Trades = Summe volume aller Hedges der Instanz (wie
    lt_fusion_pl_echo, 02.10.2026 für die Radar-Zuordnung „welcher Fusion-Trade gehört zu welchem"). Nur frisch, sonst None."""
    if not live:
        return None
    try:
        alter = jetzt_ts - datetime.fromisoformat(str(live.get("updated_at")).replace("Z", "+00:00")).timestamp()
    except (TypeError, ValueError):
        return None
    hd = live.get("hd")
    if alter > LT_ECHO_MAX_ALTER_S or not isinstance(hd, dict):
        return None
    werte = [_wd_num(h.get("volume")) for hs in hd.values() if isinstance(hs, list) for h in hs if isinstance(h, dict)]
    werte = [w for w in werte if w is not None]
    return round(sum(werte), 2) if werte else None


def lt_satz_setzen(trades, konto_je_plan, werte):
    """REIN RECHNEND (SATZ-AN-LIVE-TRADES, 07.10.2026, Hinweis Terminal 2: fremde Hand-Trades, die vor dem Öffnen des Trade-Planers
    gestartet sind und nicht im Delta stehen, hatten im Frontend keinen Kontowert-Satz → „ohne Wert" im Hypo-P&L; /admin/kontowerte
    liefert Nicht-Admins nur die eigenen Konten): je Zeile satz_eur_je_usd (€ je $, wie Delta offen[]) des Master-Kontos aus den
    Kontowerten (ap_kontowert_konto, dieselbe Rechnung wie Probelauf/Accounts). Nur der Satz, kein wert_eur — mehr braucht der
    Hypo-P&L nicht. Ohne Wert None — kein Raten."""
    for z in trades:
        aid = konto_je_plan.get(str(z.get("plan_id") or z.get("id") or ""))
        w = (werte or {}).get(str(aid)) if aid else None
        z["satz_eur_je_usd"] = (w or {}).get("satz_eur_pro_usd")
    return trades


def lt_fusion_pl_solo(hedge, solo_je_pc, jetzt_ts):
    """REIN RECHNEND (testbar): schwebender Fusion-P&L eines Orbit-/Winning-Day-Hedges aus mt5_live.status.hedge_solo des
    Hedge-PCs (solo_je_pc = {pc: {updated_at, solo: [{ticket, profit|pl_live}]}}). Nur offener Hedge mit Ticket, frisch, sonst None."""
    h = hedge if isinstance(hedge, dict) else {}
    if str(h.get("status") or "") not in ("offen", "schliesst") or not h.get("ticket") or not h.get("pc"):
        return None
    z = (solo_je_pc or {}).get(str(h.get("pc")))
    if not z:
        return None
    try:
        alter = jetzt_ts - datetime.fromisoformat(str(z.get("updated_at")).replace("Z", "+00:00")).timestamp()
    except (TypeError, ValueError):
        return None
    if alter > LT_ECHO_MAX_ALTER_S:
        return None
    for q in (z.get("solo") or []):
        if isinstance(q, dict) and str(q.get("ticket")) == str(h.get("ticket")):
            v = _wd_num(q.get("pl_live")) if _wd_num(q.get("pl_live")) is not None else _wd_num(q.get("profit"))
            return round(v, 2) if v is not None else None
    return None


def lt_echo_live_wahl(zeilen):
    """REIN RECHNEND (testbar): mt5_live-Zeilen → {master_login: jüngste Zeile}. Ein Login kann auf mehreren PCs
    konfiguriert sein (real: pc-4bx8nm 5 Tage alt neben pc-usq1i6 frisch) — die jüngste gewinnt."""
    out = {}
    for z in zeilen or ():
        lg = str(z.get("master_login") or "").strip()
        if lg and (lg not in out or str(z.get("updated_at") or "") > str(out[lg].get("updated_at") or "")):
            out[lg] = z
    return out


def lt_echo_felder(p, live, jetzt_ts):
    """REIN RECHNEND (testbar): Echo-Felder eines mt5v2-Plans aus mt5_baseline und der jüngsten mt5_live-Zeile des
    Master-Logins (live = {updated_at, pos, bal, eq, ccy, note} oder None). Nichts wird erfunden: ohne passende, frische
    Position bleiben Einstieg/Level/Kurs null. -> dict"""
    base = p.get("mt5_baseline") if isinstance(p.get("mt5_baseline"), dict) else {}
    fin = base.get("final") if isinstance(base.get("final"), dict) else {}
    bs, be = _wd_num(base.get("master_balance")), _wd_num(fin.get("master_balance"))
    out = {"plattform": "echo", "symbol": None, "symbol_quelle": None, "lots": _wd_num(p.get("master_contracts")),
           "contract_size": None, "einstieg": None, "tp_level": None, "sl_level": None, "liq_level": None, "level_quelle": None,
           "position_offen": False, "kurs_jetzt": None, "pl_live": None, "pl_live_art": None, "pl_bei_tp": None, "pl_bei_sl": None,
           "waehrung": None, "mt5_alter_s": None, "balance_start": bs, "balance_end": be,
           "pl_balance": round(be - bs, 2) if (bs is not None and be is not None) else None,
           "konto_balance": None, "konto_balance_at": None, "demo": None}
    if not live:
        return out
    try:
        alter = jetzt_ts - datetime.fromisoformat(str(live.get("updated_at")).replace("Z", "+00:00")).timestamp()
    except (TypeError, ValueError):
        return out
    out["mt5_alter_s"] = int(round(alter))
    if alter > LT_ECHO_MAX_ALTER_S or live.get("note"):
        return out
    eq, bal = _wd_num(live.get("eq")), _wd_num(live.get("bal"))
    ccy = str(live.get("ccy") or "").upper() or None
    out.update(waehrung=ccy, konto_balance=bal, konto_balance_at=live.get("updated_at"))
    if str(p.get("status") or "") != "open":
        return out
    positionen = [x for x in (live.get("pos") or []) if isinstance(x, dict)]
    # Live-P&L wie der Karten-Chip (mt5V2PnlAus): Equity − Start-Balance; ohne Baseline Equity − Balance (schwebend)
    if eq is not None and bs is not None:
        out.update(pl_live=round(eq - bs, 2), pl_live_art="equity_start")
    elif eq is not None and bal is not None and positionen:
        out.update(pl_live=round(eq - bal, 2), pl_live_art="schwebend")
    ticket = str(base.get("ticket") or "").strip()
    pos = next((x for x in positionen if ticket and str(x.get("ident") or "") == ticket), None)
    if pos is None and not ticket and len(positionen) == 1:
        pos = positionen[0]          # Plan ohne Ticket (Baseline fehlte): nur die einzige offene Position
    if pos is None:
        return out
    vol, cs, e = _wd_num(pos.get("volume")), _wd_num(pos.get("contract_size")), _wd_num(pos.get("price_open"))
    tp, sl = _wd_num(pos.get("tp")), _wd_num(pos.get("sl"))
    richtung = "buy" if str(pos.get("type")) == "0" else "sell" if str(pos.get("type")) == "1" else None
    vz = 1 if richtung == "buy" else -1 if richtung == "sell" else 0
    faktor = (vol or 0) * (cs or 0)
    out.update(symbol=pos.get("symbol") or None, symbol_quelle="mt5_position", contract_size=cs, einstieg=e,
               tp_level=tp if tp else None, sl_level=sl if sl else None, level_quelle="mt5_position", position_offen=True,
               lots=vol if vol is not None else out["lots"], richtung_mt5=richtung)
    if e and vz and faktor > 0:
        if tp:
            out["pl_bei_tp"] = round((tp - e) * vz * faktor, 2)
        if sl:
            out["pl_bei_sl"] = round((sl - e) * vz * faktor, 2)
        if len(positionen) == 1 and eq is not None and bal is not None:
            out["kurs_jetzt"] = {"kurs": round(e + vz * (eq - bal) / faktor, 2), "minute": None, "quelle": "mt5_equity",
                                 "alter_s": out["mt5_alter_s"]}
    return out


def _lt_echo_zeile(p, acc, disp, live_je_login, firm_sym, jetzt_ts, vorher=None):
    """Eine Echo-V2-Zeile im Live-Trades-Format: Rahmen aus _wd_heute_zeile (Person, Konto, Farbe, Status, master_pl …),
    NQ-Felder bleiben leer, dazu lt_echo_felder. Symbol ohne Position: Firmen-Standard (symbol_quelle 'firma')."""
    z = _wd_heute_zeile(p, acc, disp, vorher)
    z.pop("_tsx", None)
    login = str((acc or {}).get("external_id") or "").strip()
    z.update(lt_echo_felder(p, live_je_login.get(login) if login else None, jetzt_ts))
    if str(p.get("route") or "") == "mt5" and str(p.get("status") or "") == "open":
        z["slave_pl_live"] = lt_fusion_pl_echo(live_je_login.get(login) if login else None, jetzt_ts)
        z["slave_lots_live"] = lt_fusion_lots_echo(live_je_login.get(login) if login else None, jetzt_ts)
    # NQ-/Futures-Felder gelten für Echo nicht — leer statt gerechnet (die Max-Drawdown-Liquidation ist eine Futures-Regel)
    for k in ("einstieg_nq", "einstieg_quelle", "tp_level_nq", "sl_level_nq", "sl_art", "schliesst_bei_nq", "liq_level_nq",
              "liq_balance", "liq_regel", "liq_quelle", "sl_hinweis", "punktwert", "symbol_root"):
        z[k] = None
    if not z.get("symbol") and acc:
        s = firm_sym.get(_firm_norm(acc.get("firm")))
        if s:
            z["symbol"], z["symbol_quelle"] = s, "firma"
    return z


@app.route("/admin/live-trades", methods=["GET", "OPTIONS"])
def admin_live_trades():
    """GET /admin/live-trades?tage=2 → {jetzt, trades:[…]} — alle Orbit-V2-Pläne (route tvv2) aller IDs: laufend, geplant, in
    „Überprüfen" und abgeschlossen der letzten `tage` Tage. Je Trade der /admin/wd-heute-Vertrag plus balance_start/_end,
    pl_balance, liq_balance/_regel/_level_nq und demo {status, at, preis, pl_usd}. Auth wie /admin/wd-heute.
    ?echo=1 (30.09.2026): zusätzlich Echo-V2-Pläne (route mt5v2) mit plattform 'echo' und den Feldern aus lt_echo_felder;
    jede Zeile trägt plattform 'orbit' | 'echo'. Ohne den Parameter ist die Antwort wie bisher (nur Orbit/Topstep V2)."""
    if request.method == "OPTIONS":
        return "", 200
    me, err = _wd_login()
    if err:
        return err
    try:
        tage = max(1, min(14, int(request.args.get("tage") or 2)))
        # F21 (27.09.2026): jeder PC-Tab fragt alle 55–70 s ?tage=1&nur_eigene=1&status=open — Last klein halten
        nur_eigene = str(request.args.get("nur_eigene") or "") in ("1", "true", "ja")
        nur_offen = str(request.args.get("status") or "").lower() == "open"
        mit_echo = str(request.args.get("echo") or "") in ("1", "true", "ja")
        disp, excluded = _wd_personen()
        seit = datetime.fromtimestamp(datetime.now(timezone.utc).timestamp() - tage * 86400, timezone.utc).isoformat()
        felder = ("id,user_id,master_account_id,master_name,master_firm,route,notes,status,richtung,master_contracts,master_symbol,"
                  "master_symbol_root,master_tp,master_sl,master_pl,hedge_eur,hedge_faktor,start_um,start_um_gestartet_at,orbit_gesendet_at,orbit_v3,"
                  "started_at,ended_at,completed_at,planned_for,created_at,mt5_baseline,slave_pl,pl_quelle,konto_typ,orbit_v3")
        # B16: Topstep V2 wie Orbit V2. Seit 01.10.2026 abends (Finn: „ein Tab je Modell im Radar") mit ?echo=1 auch das klassische
        # Echo mit Fusion-Hedge (route mt5) — gleiche Felder wie Echo V2 aus mt5_live, dazu der Fusion-P&L (slave_pl_live)
        basis_f = {"select": felder, "route": "in.(tvv2,tsv2,mt5v2,mt5)" if mit_echo else "in.(tvv2,tsv2)"}
        if nur_eigene:
            basis_f["user_id"] = f"eq.{me}"
        if nur_offen:
            rows = _sb_all("trade_plans", dict(basis_f, status="eq.open"))
        else:
            rows = _sb_all("trade_plans", dict(basis_f, status="in.(open,review,planned)"))
            rows += _sb_all("trade_plans", dict(basis_f, status="eq.completed", completed_at=f"gte.{seit}"))
        gesehen, plaene = set(), []
        for p in rows:
            pid = str(p.get("id"))
            if pid in gesehen or str(p.get("user_id")) in excluded:
                continue
            if p.get("status") == "planned" and str(p.get("created_at") or "") < seit:
                continue   # alte, nie gestartete Pläne gehören nicht in „Live"
            gesehen.add(pid)
            plaene.append(p)
        accs = {}
        ids = sorted({str(p.get("master_account_id")) for p in plaene if p.get("master_account_id")})
        for i in range(0, len(ids), 80):
            for a in sb_select("accounts", {"select": "id,name,firm,account_type,starting_balance,external_id,max_drawdown,tv_balance,tv_balance_at",
                                            "id": f"in.({','.join(ids[i:i + 80])})"}):
                accs[str(a["id"])] = a
        # Kerzen je Wurzel ab dem frühesten Start (eine Abfrage je Wurzel)
        orbit = [p for p in plaene if str(p.get("route") or "") not in LT_ECHO_ROUTEN]      # Echo rechnet keine NQ-Demo
        starts = [str(p.get("started_at")) for p in orbit if p.get("started_at")]
        kerzen = {}
        if starts:
            ab = min(starts)
            # F21: Kerzen nur für die Wurzeln der gelieferten Pläne (Rückfall: die andere Wurzel, preisgleich)
            noetig = {_symbol_wurzel(p.get("master_symbol_root") or p.get("master_symbol")) for p in orbit if p.get("started_at")}
            noetig = [w for w in ("NQ", "MNQ") if w in noetig] or ["NQ", "MNQ"]
            for w in noetig:
                kerzen[w] = _sb_all("tv_kurs_1m", {"select": "minute,h,l", "wurzel": f"eq.{w}", "minute": f"gte.{ab[:16]}", "order": "minute.asc"})
            # NQ und MNQ laufen preisgleich — fehlt einer Wurzel der Feed, nimmt die andere
            for w, andere in (("NQ", "MNQ"), ("MNQ", "NQ")):
                if not kerzen.get(w):
                    if andere not in kerzen:
                        kerzen[andere] = _sb_all("tv_kurs_1m", {"select": "minute,h,l", "wurzel": f"eq.{andere}", "minute": f"gte.{ab[:16]}", "order": "minute.asc"})
                    kerzen[w] = kerzen[andere]
        fruehere = _wd_fruehere_trades(ids)          # B14: für den Balance-Vorläufer (konto_balance)
        liq_regeln = _liq_regeln_laden()             # LIQ-REGELN (30.09.2026): einmal je Abruf, 60 s gecacht
        liq_verlauf = _liq_verlauf_laden(ids)        # KONTO-BODEN (30.09.2026): belegte Balances je Konto, 60 s gecacht
        liq_kw = _liq_kw_laden()                     # APEX-EVAL-SOFTBREACH (07.10.2026): Kernwerte je Firma, 60 s gecacht
        # Echo (?echo=1): EIN Read auf mt5_live für die Master-Logins laufender Echo-Pläne — nur die nötigen JSON-Teile
        echo = [p for p in plaene if str(p.get("route") or "") in LT_ECHO_ROUTEN]
        live_je_login, firm_sym = {}, {}
        logins = sorted({str((accs.get(str(p.get("master_account_id") or "")) or {}).get("external_id") or "").strip()
                         for p in echo if p.get("status") == "open"} - {""})
        if logins:
            try:
                live_je_login = lt_echo_live_wahl(sb_select("mt5_live", {
                    "select": "master_login,updated_at,pos:status->master_positions,bal:status->master_balance,eq:status->master_equity,"
                              "ccy:status->>master_currency,note:status->>note,hd:status->hedges",
                    "master_login": f"in.({','.join(logins)})"}) or [])
            except Exception as e:
                print(f"[live-trades] ⚠️ mt5_live (Echo): {type(e).__name__}: {e}", flush=True)
        # Fusion-P&L live für Orbit/Winning Day (01.10.2026 abends, Finn: „bei Modellen mit Gegenhedge im Radar live beide P&Ls"):
        # EIN Read auf mt5_live.status.hedge_solo für die Hedge-PCs offener Pläne (nur mit ?echo=1 — der PC-Tab-Takt fragt ohne)
        solo_je_pc = {}
        if mit_echo:
            pcs = sorted({str(((p.get("mt5_baseline") or {}).get("hedge") or {}).get("pc") or "") for p in plaene
                          if p.get("status") == "open" and isinstance(p.get("mt5_baseline"), dict)
                          and isinstance(p["mt5_baseline"].get("hedge"), dict) and p["mt5_baseline"]["hedge"].get("status") in ("offen", "schliesst")} - {""})
            if pcs:
                try:
                    for zl in sb_select("mt5_live", {"select": "pc_name,updated_at,solo:status->hedge_solo", "pc_name": f"in.({','.join(pcs)})"}) or []:
                        k = str(zl.get("pc_name") or "")
                        if k and isinstance(zl.get("solo"), list) and (k not in solo_je_pc or str(zl.get("updated_at") or "") > str(solo_je_pc[k].get("updated_at") or "")):
                            solo_je_pc[k] = zl
                except Exception as e:
                    print(f"[live-trades] ⚠️ mt5_live (Fusion-Solo): {type(e).__name__}: {e}", flush=True)
        jetzt_ts = datetime.now(timezone.utc).timestamp()
        trades = []
        for p in plaene:
            acc, vorher = accs.get(str(p.get("master_account_id") or "")), wd_vorher_waehlen(p, fruehere)
            if str(p.get("route") or "") in LT_ECHO_ROUTEN:
                try:
                    z = _lt_echo_zeile(p, acc, disp, live_je_login, firm_sym, jetzt_ts, vorher)
                except Exception as e:     # eine kaputte Echo-Zeile darf Orbit nicht mitreißen
                    print(f"[live-trades] ⚠️ Echo-Zeile {str(p.get('id'))[:8]}: {type(e).__name__}: {e}", flush=True)
                    continue
                if not z.get("symbol") and acc and not firm_sym.get("_geladen"):
                    # Firmen-Standard nur, wenn einem Echo-Plan die Position fehlt (Überprüfen/Erledigt) — einmal je Abruf
                    firm_sym["_geladen"] = True
                    try:
                        for f in _sb_all("firm_specs", {"select": "name,symbol"}):
                            w = _cfd_wurzel(f.get("symbol"))
                            if w:
                                firm_sym.setdefault(_firm_norm(f.get("name")), w)
                    except Exception as e:
                        print(f"[live-trades] ⚠️ firm_specs (Echo): {type(e).__name__}: {e}", flush=True)
                    z = _lt_echo_zeile(p, acc, disp, live_je_login, firm_sym, jetzt_ts, vorher)
                trades.append(z)
            else:
                z = _lt_zeile(p, acc, disp, kerzen, vorher, regeln=liq_regeln, fruehere=fruehere, verlauf=liq_verlauf, kw_firmen=liq_kw)
                z["plattform"] = "orbit"
                if p.get("status") == "open" and solo_je_pc:
                    z["slave_pl_live"] = lt_fusion_pl_solo((p.get("mt5_baseline") or {}).get("hedge") if isinstance(p.get("mt5_baseline"), dict) else None, solo_je_pc, jetzt_ts)
                trades.append(z)
        rang = {"open": 0, "planned": 1, "review": 2, "completed": 3}
        trades.sort(key=lambda z: (rang.get(z.get("status"), 9), str(z.get("started_at") or z.get("start_um") or "")), reverse=False)
        # Weg je Zeile (01.10.2026, Finn am Radar: „immer sehen, mit welchem Modell der gestartet wurde"): Orbit V3 und Winning Day
        # sind beide tvv2 + hedge_eur — unterscheiden lässt sie nur die Kennung orbit_v3; konto_typ für den Winning-Day-Rückfall
        je_id = {str(p.get("id")): p for p in plaene}
        for z in trades:
            q = je_id.get(str(z.get("id"))) or {}
            z["orbit_v3"], z["konto_typ"] = bool(q.get("orbit_v3")), q.get("konto_typ")
        if mit_echo:
            # SATZ-AN-LIVE-TRADES (07.10.2026): Kontowert-Satz je Zeile für den Hypo-P&L im Trade-Planer — nur mit ?echo=1 (Radar/Planer),
            # der PC-Tab-Takt (?nur_eigene=1&status=open) bleibt ohne. Kontowerte aus dem 60-s-Merker; scheitern sie, fehlt nur der Satz.
            try:
                lt_satz_setzen(trades, {k: q.get("master_account_id") for k, q in je_id.items()}, ap_kontowerte_gemerkt(None))
            except Exception as e:
                print(f"[live-trades] ⚠️ Kontowerte (Satz): {type(e).__name__}: {e}", flush=True)
        kj = _kurs_jetzt()                       # B35/F28: aktueller Kurs je Wurzel (Radar-Weg Topstep)
        for z in trades:
            if z.get("plattform") != "echo":     # Echo trägt seinen eigenen (CFD-)Kurs aus lt_echo_felder
                z["kurs_jetzt"] = kj.get(z.get("symbol_root") or "")
        return jsonify({"jetzt": datetime.now(timezone.utc).isoformat(), "tage": tage, "kurs_jetzt": kj, "trades": trades})
    except Exception as e:
        print(f"[live-trades] ⚠️ {type(e).__name__}: {e}", flush=True)
        return jsonify({"error": f"Live Trades nicht ladbar ({type(e).__name__}: {e})"}), 502


def _wd_ende_upd(plan, jetzt_iso, datum, grund=None):
    """REIN RECHNEND (testbar): Update für „Winning Day beenden" vom Mac (25.09.2026, Finn: laufende Winning
    Days ALLER IDs vom Mac aus beenden — trade_plans liegt unter RLS, fremde Pläne nur über den Service-Key).
    Form = exakt die zwei Frontend-Schritte zusammen: tvV2EndeSetzen (mt5_baseline.final {today_pnl, datum, at,
    quelle} + live {offen: false, at}) und atMoveToReview (status 'review', ended_at). today_pnl bleibt null —
    _autoPnlFetchTvV2 liefert dann nichts und Finn trägt den P&L im Abschluss-Popup ein. mt5_baseline.hedge und
    alle anderen Felder bleiben unverändert: der PC-Wächter sieht Plan ≠ open und schließt den Hedge ('master_ende').
    -> (upd, None) oder (None, (http_code, fehler))"""
    if not isinstance(plan, dict) or not plan.get("id"):
        return None, (404, "Plan nicht gefunden")
    alt = plan.get("mt5_baseline") if isinstance(plan.get("mt5_baseline"), dict) else {}
    # Topstep V2 (K5, 30.09.2026): nur von Puls gestartete Pläne (tv.puls == 'tsx') — dort folgt die Nachlesung wie bei Orbit V2;
    # Handpläne beendet niemand automatisch über diesen Weg
    route = str(plan.get("route") or "")
    tsx_puls = route == "tsv2" and isinstance(alt.get("tv"), dict) and alt["tv"].get("puls") == "tsx"
    if (route != "tvv2" and not tsx_puls) or str(plan.get("status") or "") != "open":
        return None, (409, "nicht offen")
    fin = {"today_pnl": None, "datum": datum, "at": jetzt_iso, "quelle": "hand",
           "grund": (str(grund).strip()[:60] if grund else "hand")}
    live = dict(alt.get("live") or {}) if isinstance(alt.get("live"), dict) else {}
    live.update({"offen": False, "at": jetzt_iso})
    base = dict(alt)
    base["final"] = fin
    base["live"] = live
    return {"status": "review", "ended_at": jetzt_iso, "mt5_baseline": base}, None


# Winning-Days-Gegenhedge in Finanzen (25.09.2026, Finn: „auf ‚Erledigt' wird es in Finanzen gebucht — eigene
# Finanzen-Kategorie für den Winning-Days-Gegenhedge; das sind ab jetzt die einzigen Hedgekosten").
# ZIELKONTO — BEFUND 25.09.2026: der Fusion-Login 488579 ist KEIN einzelnes Prophos-Konto, sondern liegt als eigenes
# Konto in jedem Profil (live, Fusion Markets, external_id '488579'; Emin hedgt auf 430095); jede ID hat ihren
# Hedge-P&L bisher als 'live_pnl' auf IHRE Kopie gebucht. REGEL (Koordinations-Session, identisch mit Testes Buchung
# eigener Pläne): user_id = Besitzer des Plans; Konto = sein Konto mit external_id = Hedge-Login (mt5_baseline.hedge.
# hedge_login, sonst mt5_live.hedge_login des hedge.pc, sonst 488579); Rückfall erstes live-Konto mit Firma
# „Fusion"; sonst account_id null + account_name 'Fusion (WD-Hedge)'. currency immer EUR (Copier-P&L ist
# Kontowährung EUR; die currency-Spalte der Konten steht fälschlich auf USD).
WD_HEDGE_LOGIN = "488579"


def _wd_hedge_schluessel(pid):
    """Idempotenz-Schlüssel der Buchung in transactions.notes."""
    return f"Trade #{str(pid)[:8]} WD-Hedge"


def _wd_hedge_konto(konten, login=None, archiviert=None):
    """REIN RECHNEND: Fusion-Hedge-Konto für die Buchung aus den Konten des Plan-Besitzers — dieselbe Wahl wie
    wdHedgeKonto im Frontend (zweite Gegenprüfung 25.09.2026, Befund 11: Backend nahm auch archivierte Konten und
    kannte den MetaApi-Login nicht, je nachdem wer buchte, landete die Zeile auf einem anderen Konto).
    Archivierte Konten (user_settings 'archive', Menge der IDs) zählen nie. Reihenfolge = created_at.
    1) external_id = login ODER meta_api_login = login (nur mit meta_api_account_id, wie row.ma im Frontend),
       live vor anderen, sonst der erste Treffer;
    2) erstes live-Konto mit Firma „Fusion"; 3) None (Buchung ohne Konto).
    -> (Konto-dict | None, quelle 'login' | 'fusion_live' | 'ohne')"""
    login = str(login or WD_HEDGE_LOGIN).strip()
    aus = {str(x) for x in (archiviert or ())}
    ks = sorted([a for a in (konten or []) if a and a.get("id") and str(a.get("id")) not in aus],
                key=lambda a: str(a.get("created_at") or ""))

    def _treffer(a):
        if str(a.get("external_id") or "").strip() == login:
            return True
        return bool(a.get("meta_api_account_id")) and str(a.get("meta_api_login") or "").strip() == login

    passend = [a for a in ks if _treffer(a)]
    live = [a for a in passend if str(a.get("account_type") or "") == "live"]
    if passend:
        return (live or passend)[0], "login"
    fusion = [a for a in ks if str(a.get("account_type") or "") == "live" and "fusion" in str(a.get("firm") or "").lower()]
    if fusion:
        return fusion[0], "fusion_live"
    return None, "ohne"


def _wd_zahl(v):
    """Zahl aus JSON (int/float oder Text mit Punkt/Komma); None = keine Zahl, bool zählt nicht."""
    if isinstance(v, bool) or v is None:
        return None
    if isinstance(v, (int, float)):
        return float(v) if v == v and abs(v) != float("inf") else None
    try:
        return float(str(v).strip().replace(",", "."))
    except (TypeError, ValueError):
        return None


# Good Day (01.10.2026, Finn: „wenn der Winning Day abgehakt wird und der P&L bei Tradeify über 250 ist, automatisch als
# Winning Day anhaken"): Firma (Teilstring, klein) → Master-P&L in $, AB dem (echt darüber) der Tag als Winning Day zählt.
# Nur Konten vom Typ 'winning_days'; andere Firmen zählen weiter von Hand über das 🏆-Häkchen.
WD_GOOD_DAY_MIN = {"tradeify": 250.0}


def _wd_good_day(konto, master_pl):
    """REIN RECHNEND (testbar): True, wenn dieser Trade ein Good Day ist — Konto vom Typ winning_days, Firma mit Schwelle in
    WD_GOOD_DAY_MIN und Master-P&L echt darüber. Fehlt etwas → False."""
    if not isinstance(konto, dict) or str(konto.get("account_type") or "") != "winning_days":
        return False
    try:
        pl = float(master_pl)
    except (TypeError, ValueError):
        return False
    firma = str(konto.get("firm") or "").lower()
    return any(k in firma and pl > grenze for k, grenze in WD_GOOD_DAY_MIN.items())


def _wd_good_day_konto_upd(konto, heute):
    """REIN RECHNEND (testbar): Konto-Update für „Winning Day +1" — gleiche Felder und Regel wie zielManuellPlus im Frontend:
    höchstens einmal je Berlin-Tag (goal_manual_last), goal_kind/goal_manual/goal_target werden mitgeschrieben (Futures-Funded
    zählt implizit mit Ziel 5). None = heute schon gezählt (erneutes 'erledigt' zählt nie doppelt)."""
    if str(konto.get("goal_manual_last") or "")[:10] == heute:
        return None
    ziel = konto.get("goal_target")
    try:
        ziel = int(ziel) if ziel and int(ziel) > 0 else 5
    except (TypeError, ValueError):
        ziel = 5
    try:
        stand = max(0, int(konto.get("goal_done_offset") or 0))
    except (TypeError, ValueError):
        stand = 0
    return {"goal_done_offset": stand + 1, "goal_manual_last": heute, "goal_kind": "winning_days", "goal_manual": True, "goal_target": ziel}


def _berlin_heute():
    # Berlin wie _deTodayStr() im Frontend — sonst zählte derselbe Tag je nach Seite unterschiedlich
    try:
        from zoneinfo import ZoneInfo
        return datetime.now(ZoneInfo("Europe/Berlin")).strftime("%Y-%m-%d")
    except Exception:   # pragma: no cover — tzdata fehlt → UTC
        return datetime.now(timezone.utc).strftime("%Y-%m-%d")


WD_ERLEDIGT_ROUTEN = ("tvv2", "mt5v2", "tsv2", "mt5", "tvplus")   # 30.09.2026: Orbit, Echo V2, Topstep V2 — seit 02.10.2026 auch
# Echo mit Fusion-Hedge (mt5) und Duplikum (tvplus), Finn: „natürlich will ich auch Echo-Trades hier abhaken"
WD_FUSION_AM_PLAN = ("mt5", "tvplus")   # Fusion-P&L nur als slave_pl am Plan — wie das große Erledigt-Popup, KEINE wd_hedge-Buchung


def _wd_erledigt_upd(plan, master_pl, slave_pl, jetzt_iso, datum):
    """REIN RECHNEND (testbar): Update für „Winning Day erledigt" (Abschluss-Popup vom Mac, 25.09.2026).
    Route 'tvv2', seit 30.09.2026 auch 'mt5v2' (Echo V2) und 'tsv2' (Topstep V2) — Finn will im Radar ALLES abhaken, auch
    Trades fremder IDs (Anlass: Echo-Trade von Mike, Knopf gesperrt). Status open/review (completed = Korrektur, idempotent:
    completed_at bleibt). Setzt master_pl ($), slave_pl (€ | null), status 'completed', completed_at; ended_at, falls leer;
    mt5_baseline.final wie bei 'ende', falls noch keins (tvv2 und seit K5 tsv2 mit tv.puls 'tsx' — Echo und Topstep-Handpläne
    behalten ihre Baseline).
    Fusion-P&L (slave_pl) gibt es nur bei Orbit V2 / Winning Days: sonst 400, damit keine falsche wd_hedge-Buchung entsteht.
    -> (upd, None) oder (None, (http_code, fehler))"""
    if not isinstance(plan, dict) or not plan.get("id"):
        return None, (404, "Plan nicht gefunden")
    st = str(plan.get("status") or "")
    route = str(plan.get("route") or "")
    if route not in WD_ERLEDIGT_ROUTEN or st not in ("open", "review", "completed"):
        return None, (409, "nicht offen")
    if route not in ("tvv2",) + WD_FUSION_AM_PLAN and slave_pl is not None:
        return None, (400, "Fusion-P&L gibt es nur bei Orbit, Winning Days, Echo und Duplikum")
    upd = {"status": "completed", "master_pl": master_pl, "slave_pl": slave_pl}
    if st != "completed" or not plan.get("completed_at"):
        upd["completed_at"] = jetzt_iso
    if not plan.get("ended_at"):
        upd["ended_at"] = jetzt_iso
    base = plan.get("mt5_baseline") if isinstance(plan.get("mt5_baseline"), dict) else {}
    if not isinstance(base.get("final"), dict):
        e_upd, _e = _wd_ende_upd(dict(plan, status="open"), jetzt_iso, datum, "erledigt")
        if e_upd:
            upd["mt5_baseline"] = e_upd["mt5_baseline"]
    return upd, None


def _wd_hedge_buchung(plan_id, uid, konto, person, slave_pl, datum):
    """REIN RECHNEND: transactions-Zeile 'wd_hedge' (EUR, Vorzeichen = P&L, auto_generated). user_id = Besitzer
    des Plans; ohne Konto account_id null + 'Fusion (WD-Hedge)' (kapitel_id setzt der Trigger dann übers Datum)."""
    name = (konto or {}).get("name") or "Fusion (WD-Hedge)"
    return {"user_id": str(uid), "account_id": (str(konto.get("id")) if konto else None),
            "account_name": name, "account_firm": (konto or {}).get("firm") or "Fusion Markets",
            "kind": "wd_hedge", "amount": round(float(slave_pl), 2), "currency": "EUR", "occurred_at": datum,
            "notes": f"{_wd_hedge_schluessel(plan_id)} · {person or '—'} · {name}",
            "auto_generated": True}


# ══ PC-TAB-LEBENSZEICHEN JE ID (08.10.2026, Master/Finn; Anlass: ein Trade stand 20 h auf „wird gelesen", weil der Prophos-Tab am PC
# der ID gar nicht lief — niemand sah es). mt5_live wird vom PC-TAB geschrieben (prophos.html Flotten-Push, alle 12 s Lebenszeichen,
# status.tab_build/bot_version/copier_version/user_id) — updated_at ist also der Herzschlag des Tabs, nicht des Copiers. Nur lesen.
PC_STAND_LEBT_S = 180


def pc_stand_zusammenfassen(rows, jetzt):
    """REIN RECHNEND (testbar): mt5_live-Zeilen → je user_id der jüngste Stand {pc_name, tab_build, bot_version, copier_version,
    zuletzt, alt_s, lebt, pcs[]}. Mehrere Instanzen/PCs je ID: der jüngste Herzschlag zählt, alle PC-Namen stehen in pcs."""
    out = {}
    for r in rows or []:
        uid = str(r.get("user_id") or "").strip()
        if not uid:
            continue
        try:
            at = datetime.fromisoformat(str(r.get("updated_at") or "").replace("Z", "+00:00"))
        except (TypeError, ValueError):
            continue
        if at.tzinfo is None:
            at = at.replace(tzinfo=timezone.utc)
        alt = max(0, int((jetzt - at).total_seconds()))
        pc = str(r.get("pc_name") or "")
        z = out.get(uid)
        # Je PC der jüngste Stand (08.10.2026, Admin → Übersicht → PC-Tabs): Build, Wartegrund des Neulade-Wächters, inhaltsgleich
        je_pc = dict((z or {}).get("je_pc") or {})
        if pc and (pc not in je_pc or alt < je_pc[pc]["alt_s"]):
            je_pc[pc] = {"pc_name": pc, "tab_build": r.get("tab_build"), "bot_version": r.get("bot_version"), "tab_bw": r.get("tab_bw"),
                         "tab_gleich": r.get("tab_gleich"), "zuletzt": at.isoformat(), "alt_s": alt, "lebt": alt < PC_STAND_LEBT_S,
                         "mt5_update": r.get("mt5_update") if isinstance(r.get("mt5_update"), dict) else None}
        # MT5-Update-Stand je PC (08.10.2026, Admin → PC-Tabs „MT5-Update ✓/✗"): die jüngste Zeile, die ihn überhaupt hat — ein alter
        # Tab ohne das Feld (z. B. noch .1335) löscht den Stand einer anderen Instanz desselben PCs nicht
        if pc and pc in je_pc and je_pc[pc].get("mt5_update") is None and isinstance(r.get("mt5_update"), dict):
            je_pc[pc]["mt5_update"] = r.get("mt5_update")
        if z is None or alt < z["alt_s"]:
            out[uid] = {"pc_name": pc, "tab_build": r.get("tab_build"), "bot_version": r.get("bot_version"),
                        "copier_version": r.get("copier_version"), "zuletzt": at.isoformat(), "alt_s": alt,
                        "lebt": alt < PC_STAND_LEBT_S, "pcs": sorted(set((z or {}).get("pcs", []) + ([pc] if pc else []))),
                        "je_pc": je_pc}
        else:
            z["je_pc"] = je_pc
            if pc and pc not in z["pcs"]:
                z["pcs"] = sorted(z["pcs"] + [pc])
    return out


@app.route("/admin/pc-stand", methods=["GET", "OPTIONS"])
def admin_pc_stand():
    """GET → {ok, at, stand: {user_id: {...}}}. Gate wie /admin/wd-plaene (eingeloggt); eingeschränkte Logins sehen nur ihre Sicht
    (Verwalter: Gruppe, Mitglied/„nur eigene": sich selbst), Finn mit ?gruppe= nur diese Gruppe (08.10.2026)."""
    if request.method == "OPTIONS":
        return "", 200
    me, err = _wd_login()
    if err:
        return err
    rows = sb_select("mt5_live", {"select": "id,pc_name,updated_at,user_id:status->>user_id,tab_build:status->>tab_build,"
                                             "bot_version:status->>bot_version,copier_version:status->>copier_version,"
                                             "tab_bw:status->tab_bw,tab_gleich:status->>tab_gleich,mt5_update:status->mt5_update",
                                  "order": "updated_at.desc", "limit": "400"}) or []
    jetzt = datetime.now(timezone.utc)
    stand = pc_stand_zusammenfassen(rows, jetzt)
    sicht = _admin_sicht()   # Admin-Gruppen (08.10.2026): Verwalter = seine Gruppe, Mitglied = nur er, Finn mit ?gruppe= = diese Gruppe
    if sicht is not None:
        stand = {k: v for k, v in stand.items() if str(k) in sicht}
    else:   # Standard-Sicht HT (09.10.2026): Gruppen MIT Verwalter raus
        std_aus = _admin_standard_aus()
        stand = {k: v for k, v in stand.items() if str(k) not in std_aus}
    return jsonify({"ok": True, "at": jetzt.isoformat(), "lebt_s": PC_STAND_LEBT_S, "stand": stand})


# HANDARBEIT (Finn 09.10.2026 ~01:30 Dubai: „eine Liste mit allen Accounts, die gepasst wurden oder irgendwas manuell Hilfe brauchen … in einem
# Popup: welche Accounts brauchen genau die Hilfe? Wo muss ich die Phase hinzufügen?"). Vier Gruppen, nur aktive Konten (Archiv wie _admin_basis):
#   bestanden    accounts.ziel_erreicht_at (Ziel-Wache), Kontoart Challenge/Phase → Phase alt → neu (wie WDL_ZIEL_TYP im Radar), neues Konto nötig
#   geblowt      letzter gestarteter Plan des Kontos mit blown = true, Konto nicht archiviert
#   ueberpruefen trade_plans review OHNE Manuell-Kennzeichen, Ende älter als 6 h
#   manuell      trade_plans review MIT mt5_baseline.manuell (Schritt + Notiz)
# Sicht wie die Admin-Reiter (_admin_sicht: Verwalter = Gruppe mit ?ansicht=admin, Finns ?gruppe=); ein Login ohne Einschränkung, der NICHT in
# ADMIN_EMAILS steht, sieht nur sich (Master: „normale ID: nur eigene"). Nur Lesen, 30 s gemerkt je Sicht — das Frontend fragt alle 60 s.
HAND_CACHE_S = 30
HAND_UEBERPRUEFEN_H = 6
HAND_BLOWN_TAGE = 60                                # Blow-Pläne nur so weit zurück (Last)
HAND_NACH = {"challenge": "funded", "phase1": "phase2", "phase2": "funded_cfd"}
# 5. Gruppe „Planer braucht dich" (Master 09.10.2026): Gründe des letzten Nachtlaufs, die eine Hand brauchen — ohne die, die schon eine andere
# Gruppe zeigt (Ziel erreicht = bestanden, noch nicht erledigt = Überprüfen) und ohne „hat schon einen geplanten/laufenden Plan" (kein Fall)
HAND_PLANER_OHNE = re.compile(r"Ziel erreicht|bestanden|noch nicht erledigt|Überprüfen|geplanten/laufenden Plan|Manuelle Arbeit", re.I)
_hand_cache = {}
_hand_lock = threading.Lock()


def hand_gruppen(konten_ziel, reviews, blown, letzte, accs, archiv, namen, ausgeblendet, jetzt, lauf=None):
    """REIN RECHNEND (testbar): die vier Handarbeit-Gruppen. konten_ziel = accounts mit ziel_erreicht_at; reviews = trade_plans review
    (mit manuell); blown = trade_plans blown=true; letzte = {konto_id: (plan_id, started_at)} jüngster gestarteter Plan je Konto;
    accs = {konto_id: account} (Name/Firma/External ID/Typ der Plan-Konten); archiv = archivierte Konto-IDs; namen = user_id → Name.
    lauf = {at, ausgelassen[]} des letzten echten Nachtlaufs (schon auf die Sicht gefiltert) oder None → Gruppe planer.
    → {bestanden, geblowt, ueberpruefen, manuell, planer} — Listen von Zeilen, neueste zuerst (planer in Lauf-Reihenfolge)."""
    def ende4(a):
        return str((a or {}).get("external_id") or "").strip()[-4:]

    def basis(uid, kid, a, firma=None, name=None):
        a = a or {}
        return {"user_id": str(uid or ""), "user": namen.get(str(uid or ""), ""), "konto_id": str(kid or "") or None,
                "firma": firma or a.get("firm") or "", "konto": name or a.get("name") or "", "ende4": ende4(a),
                "typ": a.get("account_type"), "start_balance": _wd_num(a.get("starting_balance"))}
    out = {"bestanden": [], "geblowt": [], "ueberpruefen": [], "manuell": [], "planer": []}
    # Konto mit Manuelle-Arbeit-Zeile nicht zusätzlich als „bestanden" (wie die Ziel-Zeilen im Radar: nicht doppelt)
    man_konten = {str(p.get("master_account_id")) for p in reviews or ()
                  if isinstance(p.get("manuell"), dict) and p["manuell"].get("at") and p.get("master_account_id")}
    for a in konten_ziel or ():
        kid, uid = str(a.get("id") or ""), str(a.get("user_id") or "")
        if not kid or kid in archiv or kid in man_konten or uid in ausgeblendet or a.get("account_type") not in HAND_NACH:
            continue
        z = basis(uid, kid, a)
        z.update(art="bestanden", seit=a.get("ziel_erreicht_at"), nach=HAND_NACH[a["account_type"]],
                 bal=_wd_num(a.get("ziel_erreicht_bal")), ziel=_wd_num(a.get("ziel_usd")))
        out["bestanden"].append(z)
    gesehen = set()
    for p in blown or ():
        kid, uid = str(p.get("master_account_id") or ""), str(p.get("user_id") or "")
        if not kid or kid in gesehen or kid in archiv or uid in ausgeblendet:
            continue
        if (letzte.get(kid) or (None,))[0] != str(p.get("id")):
            continue                                   # nach dem Blow lief schon ein neuer Plan auf dem Konto → kein Fall
        gesehen.add(kid)
        z = basis(uid, kid, accs.get(kid), p.get("master_firm"), p.get("master_name"))
        z.update(art="geblowt", plan_id=str(p.get("id")), seit=p.get("ended_at") or p.get("completed_at"), pl=_wd_num(p.get("master_pl")))
        out["geblowt"].append(z)
    for p in reviews or ():
        kid, uid = str(p.get("master_account_id") or ""), str(p.get("user_id") or "")
        if uid in ausgeblendet or (kid and kid in archiv):
            continue
        m = p.get("manuell") if isinstance(p.get("manuell"), dict) else None
        z = basis(uid, kid, accs.get(kid), p.get("master_firm"), p.get("master_name"))
        z["plan_id"] = str(p.get("id"))
        if m and m.get("at"):
            z.update(art="manuell", seit=m.get("at"), schritt=m.get("schritt"), notiz=m.get("notiz"))
            out["manuell"].append(z)
            continue
        ende = _ap_ts(p.get("ended_at") or p.get("completed_at"))
        if ende is None or (jetzt - ende).total_seconds() < HAND_UEBERPRUEFEN_H * 3600:
            continue
        z.update(art="ueberpruefen", seit=ende.isoformat(), pl=_wd_num(p.get("master_pl")))
        out["ueberpruefen"].append(z)
    for k in out:
        out[k].sort(key=lambda z: str(z.get("seit") or ""), reverse=True)
    schon = {z.get("konto_id") for k in ("bestanden", "geblowt", "ueberpruefen", "manuell") for z in out[k] if z.get("konto_id")}
    for x in (lauf or {}).get("ausgelassen") or ():
        if not isinstance(x, dict):
            continue
        kid, uid, grund = str(x.get("konto_id") or ""), str(x.get("user_id") or ""), str(x.get("grund") or "").strip()
        if not grund or HAND_PLANER_OHNE.search(grund) or uid in ausgeblendet or (kid and (kid in archiv or kid in schon)):
            continue
        if x.get("balance_gelesen_at"):                # seit dem Lauf gelesen → kein Fall mehr, das Nachplanen nimmt es mit (09.10.2026)
            out.setdefault("planer_gelesen", 0)
            out["planer_gelesen"] += 1
            continue
        a = accs.get(kid) or {}
        z = basis(uid, kid, a, x.get("firma"), x.get("konto"))
        z["typ"] = z.get("typ") or x.get("typ")
        z.update(art="planer", grund=grund, seit=(lauf or {}).get("at"),
                 knopf="balance" if re.search(r"keine Balance|nicht live|nie gelesen", grund, re.I) else "")
        out["planer"].append(z)
        if kid:
            schon.add(kid)
    return out


@app.route("/admin/handarbeit", methods=["GET", "OPTIONS"])
def admin_handarbeit():
    """GET → {ok, at, n, gruppen: hand_gruppen(…)} für die Sicht des Logins (siehe oben)."""
    if request.method == "OPTIONS":
        return "", 200
    me, err = _wd_login()
    if err:
        return err
    sicht = _admin_sicht()
    if sicht is None:
        try:
            mail = str((_auth_user_anfrage((request.headers.get("sb-token") or "").strip()).json() or {}).get("email") or "").strip().lower()
        except Exception:
            mail = ""
        if mail not in ADMIN_EMAILS:
            sicht = frozenset({str(me)})
    # Standard-Sicht HT (09.10.2026): Finn ohne Gruppen-Chip sieht keine IDs der Gruppen MIT Verwalter
    try:
        std_aus = _admin_standard_aus() if sicht is None else set()
    except Exception as e:
        return jsonify({"error": f"Gruppen nicht lesbar ({type(e).__name__})"}), 502
    schluessel = ("*-" + ",".join(sorted(std_aus))) if sicht is None else ",".join(sorted(sicht))
    with _hand_lock:
        c = _hand_cache.get(schluessel)
        if c and c[0] > time.time():
            return jsonify(c[1])
    try:
        f = admin_sicht_filter(sicht) or (("not.in.(" + ",".join(sorted(std_aus)) + ")") if std_aus else None)
        uq = {"user_id": f} if f else {}
        konten_ziel = _sb_all("accounts", dict(uq, select="id,user_id,name,firm,account_type,external_id,starting_balance,"
                                                           "ziel_erreicht_at,ziel_erreicht_bal,ziel_usd", ziel_erreicht_at="not.is.null"))
        reviews = _sb_all("trade_plans", dict(uq, select="id,user_id,master_account_id,master_name,master_firm,master_pl,ended_at,"
                                                         "completed_at,manuell:mt5_baseline->manuell", status="eq.review"))
        # Blow-Pläne nur der letzten HAND_BLOWN_TAGE (Prüfer 09.10.2026: ohne Grenze wüchse die Abfrage mit jedem Blow aller Zeiten mit) —
        # Ende = ended_at, sonst completed_at (manche Pläne haben nur das); ohne „+" im Zeitstempel (or-Filter)
        ab_b = datetime.fromtimestamp(time.time() - HAND_BLOWN_TAGE * 86400, timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        blown = _sb_all("trade_plans", dict(uq, select="id,user_id,master_account_id,master_name,master_firm,master_pl,started_at,"
                                                       "ended_at,completed_at", blown="is.true", order="started_at.desc",
                                            **{"or": f"(ended_at.gte.{ab_b},and(ended_at.is.null,completed_at.gte.{ab_b}))"}))
        archiv = _ap_archiviert()
        lauf = None                                     # letzter echter Nachtlauf (5. Gruppe „Planer braucht dich")
        for l in sb_select("auto_plan_lauf", {"select": "at,aus:ergebnis->ausgelassen,trocken:ergebnis->>trocken",
                                              "ergebnis->>quelle": "eq.nacht", "order": "at.desc", "limit": "3"}) or []:
            if str(l.get("trocken") or "").lower() != "true":
                lauf = {"at": l.get("at"), "ausgelassen": [x for x in (l.get("aus") or []) if isinstance(x, dict)
                                                            and admin_in_sicht(x.get("user_id"), sicht)
                                                            and str(x.get("user_id") or "") not in std_aus]}
                try:
                    lauf = ap_lauf_gelesen_markieren(lauf)   # seit dem Lauf gelesene „Balance fehlt"-Konten (09.10.2026)
                except Exception as e:
                    print(f"[handarbeit] ⚠️ gelesen-Markierung: {type(e).__name__}: {e}", flush=True)
                break
        aktiv = lambda liste: sorted({str(p.get("master_account_id")) for p in liste or []
                                      if p.get("master_account_id") and str(p.get("master_account_id")) not in archiv})
        kids_blown = aktiv(blown)
        kids = aktiv((blown or []) + (reviews or []) + [{"master_account_id": x.get("konto_id")} for x in ((lauf or {}).get("ausgelassen") or [])])
        letzte, accs = {}, {}
        for j in range(0, len(kids_blown), 150):          # jüngster gestarteter Plan nur für die Blow-Konten (Last: nichts sonst)
            for r in _sb_all("trade_plans", {"select": "id,master_account_id,started_at", "started_at": "not.is.null",
                                             "master_account_id": "in.(" + ",".join(kids_blown[j:j + 150]) + ")", "order": "started_at.desc"}):
                k = str(r.get("master_account_id"))
                if k not in letzte:
                    letzte[k] = (str(r.get("id")), r.get("started_at"))
        for j in range(0, len(kids), 150):
            for a in _sb_all("accounts", {"select": "id,name,firm,account_type,external_id,starting_balance",
                                          "id": "in.(" + ",".join(kids[j:j + 150]) + ")"}):
                accs[str(a["id"])] = a
        namen, ausgeblendet = _wd_personen()
        gr = hand_gruppen(konten_ziel, reviews, blown, letzte, accs, archiv, namen, ausgeblendet, datetime.now(timezone.utc), lauf)
        gelesen = gr.pop("planer_gelesen", 0)
        antwort = {"ok": True, "at": datetime.now(timezone.utc).isoformat(), "n": sum(len(v) for v in gr.values()), "gruppen": gr,
                   "planer_gelesen": gelesen}
    except Exception as e:
        print(f"[handarbeit] ⚠️ {type(e).__name__}: {e}", flush=True)
        return jsonify({"ok": False, "error": f"{type(e).__name__}: {e}"}), 502
    with _hand_lock:
        _hand_cache[schluessel] = (time.time() + HAND_CACHE_S, antwort)
    return jsonify(antwort)


@app.route("/admin/wd-plaene", methods=["GET", "POST", "PATCH", "DELETE", "OPTIONS"])
def admin_wd_plaene():
    if request.method == "OPTIONS":
        return "", 200
    me, err = _wd_login()
    if err:
        return err
    # Der Farmer plant über alle IDs (Tagesplan, belegte Konten, Anlegen/Löschen) — nichts
    # für eine ID, die im Admin nur sich selbst sieht (27.09.2026). PATCH bleibt, aber nur
    # auf EIGENE Pläne/Signale/Konten: der PC-Tab beendet, liest nach und hakt darüber
    # auch seine eigenen Trades ab (ende/endlesung/endlesung_stand/erledigt/farm/id).
    # ADMIN-GRUPPEN (08.10.2026, Finn: „Emin bekommt das volle Admin wie Finn, aber nur mit den IDs seiner Gruppe"): ein Verwalter darf
    # GET/POST/PATCH/DELETE, aber nur auf Pläne/Signale/Konten seiner Gruppe (Besitz-Prüfung wie bisher, nur gegen die Menge); GET
    # liefert nur seine Gruppe (_wd_personen + Filter unten). Ein Mitglied ohne eigenen Zugang bleibt wie Emin bis .1380: nur PATCH auf
    # Eigenes (PC-Tab). Mit DELETE kam bisher jeder Login an jeden geplanten Plan — für Eingeschränkte jetzt nur die eigene Sicht.
    nur = _admin_nur_uid()
    sicht_fest = getattr(g, "admin_sicht", None)
    if nur:
        if request.method != "PATCH" and not _admin_verwalter():
            return jsonify({"error": "Winning-Day-Farmer ist für diese ID nicht freigegeben"}), 403
        if request.method in ("PATCH", "DELETE"):
            d = request.get_json(silent=True) or {}
            akt = d.get("aktion") if request.method == "PATCH" else None
            try:
                if akt == "tab_neu_laden":     # kein Objekt, nur die ID selbst (bis .1380 fiel das hier immer auf 403)
                    besitz = [{"user_id": str(d.get("user_id") or "").strip()}]
                else:
                    if akt in ("endlesung_stand", "balance_stand"):
                        tab, key = "order_signale", str(d.get("signal_id") or "").strip()
                    elif akt in ("farm", "balance"):
                        tab, key = "accounts", str(d.get("account_id") or "").strip()
                    elif akt in ("ende", "endlesung", "erledigt", "ansehen", "manuell", "manuell_weg"):
                        tab, key = "trade_plans", str(d.get("plan_id") or "").strip()
                    else:
                        tab, key = "trade_plans", str(d.get("id") or request.args.get("id") or "").strip()
                    besitz = sb_select(tab, {"select": "user_id", "id": f"eq.{key}", "limit": "1"}) if len(key) >= 10 else []
            except Exception as e:
                return jsonify({"error": f"Besitz nicht prüfbar ({type(e).__name__})"}), 502
            if not besitz or not admin_in_sicht(besitz[0].get("user_id"), sicht_fest or frozenset({nur})):
                return jsonify({"error": "Nur Pläne und Konten der eigenen Gruppe" if _admin_verwalter() else "Nur eigene Pläne und Konten"}), 403

    if request.method == "GET":
        tag = (request.args.get("tag") or "").strip()[:10]
        try:
            disp, excluded = _wd_personen()
            archiv = _acc_plan_archiviert()
            accs = _sb_all("accounts", {"select": "id,user_id,name,firm,account_type,external_id,starting_balance,max_drawdown,wd_farm,tv_balance,tv_balance_at"})
            konten = []
            for a in accs:
                typ = (a.get("account_type") or "").lower()
                firm = (a.get("firm") or "").strip()
                uid = str(a.get("user_id"))
                # 25.09.2026: nur noch Winning-Days-Konten (vierter Kontotyp) — Finn: „immer nur die Winning Days sehen"
                if typ != "winning_days" or not any(k in firm.lower() for k in WD_FUTURES_FIRMEN):
                    continue
                if str(a["id"]) in archiv or uid in excluded:
                    continue
                konten.append({
                    "id": str(a["id"]), "user_id": uid, "person": disp.get(uid, uid[:8]),
                    "name": a.get("name") or "", "firm": firm, "type": typ,
                    "ext": (a.get("external_id") or "").strip(),
                    "max_drawdown": _wd_num(a.get("max_drawdown")),
                    "starting_balance": _wd_num(a.get("starting_balance")),
                    # B8 (26.09.2026): Live-Wert aus TradingView statt der manuellen Balance (Feld „balance" entfällt —
                    # das Frontend liest es seit F9 nicht mehr; Rückfall bei RPC-Ausfall nimmt diese drei Namen, F10)
                    # Topstep Express (01.10.2026, gemeinsame Regel): 0-basiert — 0/negativ sind echte Stände, keine leeren Syncs
                    "live_balance": _wd_num(a.get("tv_balance")) if ((_wd_num(a.get("tv_balance")) or 0) > 0
                                                                      or (_wd_num(a.get("tv_balance")) is not None and ist_topstep_express(a))) else None,
                    "live_at": a.get("tv_balance_at"),
                    "wd_farm": bool(a.get("wd_farm")),
                })
            # Duplikum-Slave je Person = Slave des jüngsten dup/tvplus-Plans (Echo-Pläne
            # laufen über route=mt5 und haben einen anderen Slave — die zählen hier nicht)
            slaves = {}
            uids = {k["user_id"] for k in konten}
            if uids:
                seit = datetime.now(timezone.utc).timestamp() - 120 * 86400
                seit_iso = datetime.fromtimestamp(seit, timezone.utc).isoformat()
                plans = _sb_all("trade_plans", {"select": "user_id,slave_account_id,slave_name,slave_firm,created_at",
                                                "route": "in.(dup,tvplus)", "created_at": f"gte.{seit_iso}",
                                                "order": "created_at.desc"})
                for p in plans:
                    uid = str(p.get("user_id"))
                    if uid in uids and uid not in slaves and p.get("slave_account_id"):
                        slaves[uid] = {"id": str(p["slave_account_id"]), "name": p.get("slave_name") or "",
                                       "firm": p.get("slave_firm") or ""}
            # Pläne, auf die die Tagesplan-Zeilen zeigen (über alle IDs — genau das sieht der Mac per RLS nicht)
            plaene = []
            if tag:
                ids = []
                for row in sb_select("wd_tagesplan", {"select": "konten", "tag": f"eq.{tag}"}):
                    for k in (row.get("konten") or []):
                        if isinstance(k, dict) and k.get("plan_id"):
                            ids.append(str(k["plan_id"]))
                for i in range(0, len(ids), 80):
                    chunk = ",".join(ids[i:i + 80])
                    plaene += sb_select("trade_plans", {
                        # B38 (28.09.2026): route + master_contracts — „Plan heute Nacht" erkennt einen falschen Weg (tvplus vom
                        # PC-Rückfall, Jacob) auch bei fremden IDs
                        "select": "id,user_id,master_account_id,status,route,master_contracts,start_um,start_um_gestartet_at,orbit_gesendet_at,"
                                  "ended_at,master_pl,master_tp,master_risk,slave_risk,multiplier,richtung,master_symbol,"
                                  "slave_name,master_name,updated_at",
                        "id": f"in.({chunk})"})
            # Admin-Gruppen (08.10.2026): die Tagesplan-Zeilen sind nutzerübergreifend (RLS offen) — Pläne fremder IDs nicht an einen
            # eingeschränkten Login bzw. nicht in Finns Gruppenfilter
            sicht_get = _admin_sicht()
            if sicht_get is not None:
                plaene = [p for p in plaene if str(p.get("user_id")) in sicht_get]
            # 23.09.2026 (Finn: „immer noch nicht — alle Konten off"): beim LADEN tote Farmer-Plaene frueherer Tage
            # wegraeumen (planned, nie gestartet — z.B. Farmer AUS) und melden, welche Konten wirklich belegt sind
            # (belegt: Konto → Grund) bzw. welchen Farmer-Plan es fuer diesen Tag schon gibt (plaene_tag) — damit
            # der Tab seine Zeilen selbst heilen kann, ohne dass jemand „Wuerfeln" drueckt.
            belegt, plaene_tag, richtung_fest = {}, [], {}
            if tag and uids:
                offen = _sb_all("trade_plans", {"select": "id,user_id,master_account_id,status,route,notes,planned_for,start_um,start_um_gestartet_at,"
                                                          "orbit_gesendet_at,ended_at,master_pl,master_tp,master_sl,master_risk,slave_risk,"
                                                          "master_contracts,multiplier,richtung,master_symbol,slave_name,master_name,updated_at,"
                                                          "master_firm,auto_plan,auto_bestaetigt_at",
                                                "status": "in.(planned,open)"})
                if sicht_get is not None:   # Admin-Gruppen (08.10.2026): belegt/plaene_tag/richtung_fest/Aufräumen nur in der Sicht
                    offen = [o for o in offen if str(o.get("user_id")) in sicht_get]
                # RICHTUNG ÜBERNEHMEN (Finn 08.10.2026: „solange der Apex-Short bei Ina läuft, muss bei Ina auch nur short gemacht werden;
                # ist er per TP/SL zu, darf wieder long"): dieselbe Quelle wie der Planer (ap_id_fest) — je ID+Firma die Richtung aus
                # laufenden Trades aller Wege und aus Plänen, die in ≤ 30 min wirklich starten. Das Würfeln im Farmer übernimmt sie
                # statt zu würfeln (Frontend wdRichtungVorgabe); der Start-Riegel am PC bleibt die Sperre dahinter.
                try:
                    def _wd_iso_ts(iso):
                        try:
                            return datetime.fromisoformat(str(iso).replace("Z", "+00:00")).timestamp() if iso else None
                        except (TypeError, ValueError):
                            return None
                    _jm = datetime.now(timezone.utc).timestamp() / 60.0
                    richtung_fest = ap_id_fest(
                        [{"user_id": str(o.get("user_id")), "firma_key": ap_firma_key([], o.get("master_firm")), "richtung": o.get("richtung"),
                          "plan_id": o.get("id")} for o in offen if o.get("status") == "open"],
                        [{"user_id": str(o.get("user_id")), "firma_key": ap_firma_key([], o.get("master_firm")), "richtung": o.get("richtung"),
                          "plan_id": o.get("id"), "start_min": (_wd_iso_ts(o.get("start_um")) / 60.0) if _wd_iso_ts(o.get("start_um")) else None,
                          "auto_plan": bool(o.get("auto_plan")), "bestaetigt": bool(o.get("auto_bestaetigt_at")),
                          "geclaimt": bool(o.get("start_um_gestartet_at"))} for o in offen if o.get("status") == "planned"], _jm)
                except Exception as e:
                    print(f"[wd] ⚠️ richtung_fest: {type(e).__name__}: {e}", flush=True)
                    richtung_fest = {}
                for o in offen:
                    mid = str(o.get("master_account_id") or "")
                    farmer = (o.get("notes") or "") == "Winning-Day-Farmer"
                    alt_tag = str(o.get("planned_for") or "")
                    if (farmer and o.get("status") == "planned" and not o.get("start_um_gestartet_at") and alt_tag and alt_tag < tag
                            and wd_plan_wegraeumbar(o.get("start_um"))):          # Vorfall 28.09.2026: nie vor/kurz nach dem Start
                        if nur and str(o.get("user_id")) != str(nur):
                            continue    # Verwalter-Ansicht (08.10.2026, Nachbesserung A): Aufräumen fremder IDs nie aus seinem Laden
                        try:
                            _sb_anfrage("DELETE", f"{SUPABASE_URL}/rest/v1/trade_plans",
                                            params={"id": f"eq.{o['id']}", "status": "eq.planned", "start_um_gestartet_at": "is.null"},
                                            headers=_sb_headers("return=representation"), timeout=12)
                        except Exception as e:
                            print(f"[wd] ⚠️ alter Plan {o['id']} nicht geloescht: {e}", flush=True)
                        continue
                    if farmer and alt_tag == tag:
                        plaene_tag.append(o)
                        continue
                    belegt[mid] = "hat schon einen geplanten/laufenden Plan"
            return jsonify({"konten": konten, "slaves": slaves, "plaene": plaene, "fx": _wd_fx(), "belegt": belegt, "plaene_tag": plaene_tag,
                            "richtung_fest": richtung_fest})
        except Exception as e:
            print(f"[wd] ⚠️ laden: {type(e).__name__}: {e}", flush=True)
            return jsonify({"error": f"Farmer-Daten nicht ladbar ({type(e).__name__}: {e})"}), 502

    daten = request.get_json(silent=True) or {}

    if request.method == "POST":
        rows = daten.get("plaene") or []
        if not isinstance(rows, list) or not rows:
            return jsonify({"error": "plaene fehlt"}), 400
        angelegt, uebersprungen, verknuepft = [], [], []
        try:
            for r in rows[:200]:
                body = {k: v for k, v in (r or {}).items() if k in WD_PLAN_FELDER}
                _wd_ohne_master_sl(body)   # Winning Days ohne Master-SL (25.09.2026) — immer null, auch wenn ein alter Tab einen schickt
                mid, uid = str(body.get("master_account_id") or ""), str(body.get("user_id") or "")
                if len(mid) < 10 or len(uid) < 10:
                    uebersprungen.append({"master_account_id": mid, "grund": "user_id/master_account_id fehlt"}); continue
                if not _admin_darf_uid(uid):   # Admin-Gruppen (08.10.2026): Verwalter legt nur für IDs seiner Gruppe an
                    uebersprungen.append({"master_account_id": mid, "grund": "ID nicht in deiner Gruppe"}); continue
                # Konto muss dieser Person gehören — sonst landet ein Plan im falschen Profil
                acc = sb_select("accounts", {"select": "id,user_id,firm", "id": f"eq.{mid}"})
                if not acc or str(acc[0].get("user_id")) != uid:
                    uebersprungen.append({"master_account_id": mid, "grund": "Konto gehört nicht zu dieser ID"}); continue
                offen = sb_select("trade_plans", {"select": "id,status,notes,planned_for,start_um,start_um_gestartet_at", "master_account_id": f"eq.{mid}",
                                                  "status": "in.(planned,open)", "limit": "5"})
                # 23.09.2026 (Finn: „alle Accounts sind einfach off — hat schon einen Plan"): ein Farmer-Plan eines
                # FRUEHEREN Tages, der nie gestartet ist (Farmer AUS), blockiert sonst jeden Folgetag → weg damit.
                # Ein Farmer-Plan fuer DENSELBEN Tag (die Zeile hatte den Verweis verloren) wird verknuepft statt
                # uebersprungen. Nur fremde/laufende Plaene blockieren wirklich.
                neu_tag = str(body.get("planned_for") or "")
                blockiert = None
                for o in offen:
                    farmer = (o.get("notes") or "") == "Winning-Day-Farmer"
                    alt_tag = str(o.get("planned_for") or "")
                    if (farmer and o.get("status") == "planned" and not o.get("start_um_gestartet_at") and alt_tag and neu_tag and alt_tag < neu_tag
                            and wd_plan_wegraeumbar(o.get("start_um"))):          # Vorfall 28.09.2026: nie vor/kurz nach dem Start
                        try:
                            _sb_anfrage("DELETE", f"{SUPABASE_URL}/rest/v1/trade_plans",
                                            params={"id": f"eq.{o['id']}", "status": "eq.planned", "start_um_gestartet_at": "is.null"},
                                            headers=_sb_headers("return=representation"), timeout=12)
                        except Exception as e:
                            print(f"[wd] ⚠️ alter Plan {o['id']} nicht geloescht: {e}", flush=True)
                        continue
                    if farmer and o.get("status") == "planned" and alt_tag == neu_tag:
                        voll = sb_select("trade_plans", {"select": "*", "id": f"eq.{o['id']}"})
                        if voll:
                            verknuepft.append(voll[0]); blockiert = "verknuepft"; break
                    blockiert = "hat schon einen geplanten/laufenden Plan"; break
                if blockiert == "verknuepft":
                    continue
                if blockiert:
                    uebersprungen.append({"master_account_id": mid, "grund": blockiert}); continue
                body["status"] = "planned"
                body.setdefault("notes", "Winning-Day-Farmer")
                body["winning_day"] = True   # Farmer-Plan = Winning Day (25.09.2026, sql/2026-09-25_trade_plans_winning_day.sql)
                # kapitel_id bewusst nicht gesetzt (24.09.2026): der DB-Trigger ordnet den Plan nach Datum dem Kapitel zu.
                # V2 statt Hedge-Weg (24.09.2026, Vollumstieg): route tvv2/mt5v2, kein Slave, kein Multiplier.
                _wd_plan_v2(body, (acc[0].get("firm") if acc and acc[0].get("firm") else body.get("master_firm")))
                angelegt.append(sb_insert("trade_plans", body))
            return jsonify({"angelegt": angelegt, "uebersprungen": uebersprungen, "verknuepft": verknuepft})
        except Exception as e:
            print(f"[wd] ⚠️ anlegen: {type(e).__name__}: {e}", flush=True)
            return jsonify({"angelegt": angelegt, "uebersprungen": uebersprungen, "verknuepft": verknuepft,
                            "error": f"Anlegen abgebrochen ({type(e).__name__}: {e})"}), 502

    if request.method == "PATCH":
        if daten.get("aktion") == "ende":
            # Winning Day vom Mac beenden (25.09.2026). Optimistische Sperre über updated_at (Trigger
            # trade_plans_set_updated_at): schreibt der PC-Wächter zwischen Lesen und Schreiben den Hedge in
            # mt5_baseline, greift der Filter nicht → neu lesen statt den Hedge zu überschreiben (max. 3 Versuche).
            pid = str(daten.get("plan_id") or "").strip()
            if len(pid) < 10:
                return jsonify({"error": "plan_id fehlt"}), 400
            try:
                for _versuch in range(3):
                    rows = sb_select("trade_plans", {"select": "id,route,status,mt5_baseline,updated_at", "id": f"eq.{pid}", "limit": "1"})
                    jetzt = datetime.now(timezone.utc)
                    upd, fehler = _wd_ende_upd(rows[0] if rows else None, jetzt.isoformat().replace("+00:00", "Z"),
                                               _cme_handelstag(), daten.get("grund"))
                    if fehler:
                        return jsonify({"error": fehler[1], "plan_id": pid}), fehler[0]
                    filt = {"id": f"eq.{pid}", "status": "eq.open", "route": "in.(tvv2,tsv2)"}   # tsv2 nur mit Puls, s. _wd_ende_upd
                    if rows[0].get("updated_at"):
                        filt["updated_at"] = f"eq.{rows[0]['updated_at']}"
                    z = sb_update("trade_plans", filt, upd)
                    if z:
                        return jsonify({"ok": True, "plan_id": pid, "status": "review", "ended_at": z[0].get("ended_at") or upd["ended_at"]})
                return jsonify({"error": "Plan wurde gleichzeitig geändert — bitte erneut versuchen", "plan_id": pid}), 409
            except Exception as e:
                return jsonify({"error": f"Nicht beendet ({type(e).__name__})"}), 502
        if daten.get("aktion") == "ansehen":
            # „Ansehen" im Radar (02.10.2026, Finn: „Puls navigiert am PC zu dem Trade, damit ich ihn visuell sehe — falls er schon
            # zu ist, wird er direkt abgehakt"). Kein neuer PC-Weg, nur vorhandene Signale im Namen des Plan-Besitzers:
            # TradingView/TopstepX (Orbit, Winning Day, Orbit V2, Puls-Topstep V2) = Endlesung mit Prüfen — Puls springt aufs Konto,
            # ist die Position zu, geht der Plan auf „Überprüfen"; Echo/Echo V2 = 'mt5_terminal' — das MT5-Terminal des Masters kommt
            # nach vorn (keine Order). Stand wie bei „Jetzt lesen" über endlesung_stand.
            pid = str(daten.get("plan_id") or "").strip()
            if len(pid) < 10:
                return jsonify({"error": "plan_id fehlt"}), 400
            try:
                rows = sb_select("trade_plans", {"select": "id,route,status,user_id,master_account_id,master_name,mt5_baseline",
                                                 "id": f"eq.{pid}", "limit": "1"})
                plan = rows[0] if rows else None
                if not plan:
                    return jsonify({"error": "Plan nicht gefunden", "plan_id": pid}), 404
                route, uid = str(plan.get("route") or ""), str(plan.get("user_id") or "")
                if len(uid) < 10:
                    return jsonify({"error": "Plan ohne Besitzer", "plan_id": pid}), 409
                if route in ("mt5", "mt5v2"):
                    aid = str(plan.get("master_account_id") or "")
                    acc = sb_select("accounts", {"select": "id,name,firm,external_id", "id": f"eq.{aid}", "limit": "1"}) if aid else []
                    ml = sb_select("mt5_links", {"select": "mt5_login", "account_id": f"eq.{aid}", "limit": "1"}) if aid else []
                    a0 = acc[0] if acc else {}
                    login = str((ml[0] if ml else {}).get("mt5_login") or a0.get("external_id") or "").strip()
                    if not aid or not login:
                        return jsonify({"error": "Master ohne MT5-Login — Terminal nicht auffindbar", "plan_id": pid}), 409
                    zeile = {"user_id": uid, "plan_id": f"konto:{aid}", "status": "wartet",
                             "params": {"aktion": "mt5_terminal", "account_id": aid, "login": login, "external_id": a0.get("external_id"),
                                        "firm": a0.get("firm"), "name": a0.get("name") or plan.get("master_name"), "von": "admin"}}
                else:
                    zeile, fehler = _wd_endlesung_signal(plan)
                    if fehler:
                        return jsonify({"error": fehler[1], "plan_id": pid}), fehler[0]
                sig = sb_insert("order_signale", zeile)
                return jsonify({"ok": True, "plan_id": pid, "signal_id": str((sig or {}).get("id") or ""),
                                "art": zeile["params"]["aktion"]})
            except Exception as e:
                return jsonify({"error": f"Signal nicht angelegt ({type(e).__name__})"}), 502
        if daten.get("aktion") == "tab_neu_laden":
            # „Tab neu laden" (08.10.2026, Admin → Übersicht → PC-Tabs, Finn: „dass jeder einzelne PC immer die Updates direkt bekommt"):
            # Signal im Namen der ID, nur der genannte PC claimt es (prophos.html orderSignalTick, Zweig tab_neu_laden) und lädt im ruhigen
            # Moment neu. Keine Order, kein Plan — plan_id 'tab:<pc>'. „Nur eigene" (admin_zugang) darf nur die eigene ID anstoßen.
            uid_z, pc_z = str(daten.get("user_id") or "").strip(), str(daten.get("pc") or "").strip()
            if len(uid_z) < 10 or not re.fullmatch(r"pc-[a-z0-9]{3,24}", pc_z):
                return jsonify({"error": "user_id und pc (pc-xxxxxx) nötig"}), 400
            if not _admin_darf_uid(uid_z):   # seit 08.10.2026 Verwalter: jede ID seiner Gruppe
                return jsonify({"error": "Nur IDs der eigenen Gruppe" if _admin_verwalter() else "Nur die eigene ID"}), 403
            try:
                sig = sb_insert("order_signale", {"user_id": uid_z, "plan_id": f"tab:{pc_z}", "status": "wartet",
                                                  "params": {"aktion": "tab_neu_laden", "pc": pc_z, "von": "admin"}})
                return jsonify({"ok": True, "signal_id": str((sig or {}).get("id") or ""), "pc": pc_z})
            except Exception as e:
                return jsonify({"error": f"Signal nicht angelegt ({type(e).__name__})"}), 502
        if daten.get("aktion") == "endlesung":
            # „Jetzt lesen" (25.09.2026): Signal im Namen des Plan-Besitzers — sein PC-Tab liest Today's P&L + Exit-Fill
            pid = str(daten.get("plan_id") or "").strip()
            if len(pid) < 10:
                return jsonify({"error": "plan_id fehlt"}), 400
            try:
                rows = sb_select("trade_plans", {"select": "id,route,status,user_id,mt5_baseline", "id": f"eq.{pid}", "limit": "1"})
                zeile, fehler = _wd_endlesung_signal(rows[0] if rows else None)
                if fehler:
                    return jsonify({"error": fehler[1], "plan_id": pid}), fehler[0]
                sig = sb_insert("order_signale", zeile)
                return jsonify({"ok": True, "plan_id": pid, "signal_id": str((sig or {}).get("id") or "")})
            except Exception as e:
                return jsonify({"error": f"Signal nicht angelegt ({type(e).__name__})"}), 502
        if daten.get("aktion") == "balance":
            # „↻ Balance lesen" fuer fremde Konten aus „Braucht dich" (08.10.2026, s. _wd_balance_signal): Signal im Namen des Besitzers
            aid = str(daten.get("account_id") or "").strip()
            if len(aid) < 10:
                return jsonify({"error": "account_id fehlt"}), 400
            try:
                acc = sb_select("accounts", {"select": "id,user_id,name,firm,external_id", "id": f"eq.{aid}", "limit": "1"})
                ml = sb_select("mt5_links", {"select": "mt5_login", "account_id": f"eq.{aid}", "limit": "1"})
                zeile, fehler = _wd_balance_signal(acc[0] if acc else None, (ml[0] if ml else {}).get("mt5_login") or "")
                if fehler:
                    return jsonify({"error": fehler[1], "account_id": aid}), fehler[0]
                # Kein lebender PC der ID hat den MT5-Login → sofort sagen statt 4 min „wartet auf PC" (08.10.2026, s. mt5_login_ort)
                if zeile["params"]["aktion"] == "mt5_balance":
                    ort = _mt5_ort_fehler(zeile["user_id"], zeile["params"]["login"])
                    if ort:
                        return jsonify({"error": ort, "code": "kein_pc_login", "account_id": aid}), 409
                sig = sb_insert("order_signale", zeile)
                return jsonify({"ok": True, "account_id": aid, "signal_id": str((sig or {}).get("id") or ""), "art": zeile["params"]["aktion"]})
            except Exception as e:
                return jsonify({"error": f"Signal nicht angelegt ({type(e).__name__})"}), 502
        if daten.get("aktion") in ("endlesung_stand", "balance_stand"):
            # Stand eines Endlesungs-/Balance-Signals (der Mac liest fremde order_signale per RLS nicht)
            sid = str(daten.get("signal_id") or "").strip()
            if len(sid) < 10:
                return jsonify({"error": "signal_id fehlt"}), 400
            try:
                rows = sb_select("order_signale", {"select": "id,status,ergebnis,pc,updated_at,params", "id": f"eq.{sid}", "limit": "1"})
                if not rows or (rows[0].get("params") or {}).get("aktion") not in ("endlesung", "mt5_terminal", "mt5_balance", "konto_balance"):   # mt5_terminal: „Ansehen"; *_balance: „↻ Balance lesen" (08.10.2026)
                    return jsonify({"error": "Signal nicht gefunden"}), 404
                z = rows[0]
                return jsonify({"ok": True, "status": z.get("status"), "ergebnis": z.get("ergebnis"), "pc": z.get("pc"), "updated_at": z.get("updated_at")})
            except Exception as e:
                return jsonify({"error": f"Stand nicht lesbar ({type(e).__name__})"}), 502
        if daten.get("aktion") in ("manuell", "manuell_weg"):
            # MANUELLE ARBEIT (08.10.2026, Finn: „per Drag & Drop in die Gruppe ziehen, kurze Notiz, in zwei Tagen abhaken"): Kennzeichen
            # mt5_baseline.manuell {at, notiz, von} nur an Plänen in „Überprüfen" (status review, sonst 409), nichts wird verbucht.
            # Atomar über das RPC mt5_baseline_patch (merged in der DB, Service-Key) — 'manuell_weg' setzt den Schlüssel auf null.
            pid = str(daten.get("plan_id") or "").strip()
            if len(pid) < 10:
                return jsonify({"error": "plan_id fehlt"}), 400
            try:
                rows = sb_select("trade_plans", {"select": "id,status", "id": f"eq.{pid}", "limit": "1"})
                if not rows:
                    return jsonify({"error": "Plan nicht gefunden"}), 404
                if rows[0].get("status") != "review":
                    return jsonify({"error": "Nur Pläne in Überprüfen lassen sich parken", "status": rows[0].get("status")}), 409
                m = None
                if daten.get("aktion") == "manuell":
                    m = {"at": datetime.now(timezone.utc).isoformat(), "notiz": str(daten.get("notiz") or "").strip()[:300], "von": str(me),
                         "schritt": str(daten.get("schritt") or "").strip()[:40] or None}   # nächster Schritt (Finn 08.10.2026: „→ Funded / Phase 2")
                r = _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/rpc/mt5_baseline_patch", headers=_sb_headers(), timeout=(5, 15),
                                json={"p_plan": pid, "p_patch": {"manuell": m}, "p_status": "review"})
                _sb_pruefen(r)
                if not r.json():
                    return jsonify({"error": "Plan hat sich inzwischen geändert — nichts geschrieben"}), 409
                return jsonify({"ok": True, "plan_id": pid, "manuell": m})
            except Exception as e:
                return jsonify({"error": f"nicht gespeichert ({type(e).__name__})"}), 502
        if daten.get("aktion") == "erledigt":
            # Winning Day erledigt (25.09.2026): P&L von Hand, Fusion-P&L als 'wd_hedge' in Finanzen. Reihenfolge:
            # Zielkonto auflösen (ohne Konto bei slave_pl ≠ null: 409, NICHTS geschrieben) → Plan (optimistische
            # Sperre wie 'ende') → Buchung idempotent über den notes-Schlüssel (vorhandene aktualisieren, nie doppeln;
            # slave_pl null löscht eine frühere Auto-Buchung). Master-P&L wird NICHT gebucht (Prop-Konto).
            pid = str(daten.get("plan_id") or "").strip()
            mpl = _wd_zahl(daten.get("master_pl"))
            spl = None if daten.get("slave_pl") in (None, "") else _wd_zahl(daten.get("slave_pl"))
            # Account-Status wie im großen Erledigt-Popup (02.10.2026, Finn im Radar bei einem fremden Trade): 'none' = Konto bleibt,
            # 'blown' = Plan blown + Master-Konto im Archiv des BESITZERS ('blown'), 'passed' = Archiv 'passed_pending' — der Besitzer
            # trägt den Nachfolger bei sich nach („🎉 Account-Daten nachtragen"). Serverseitig, weil der Mac fremde Archive nicht schreibt.
            konto_status = str(daten.get("konto_status") or "none")
            if konto_status not in ("none", "blown", "passed"):
                return jsonify({"error": "konto_status unbekannt"}), 400
            blown = konto_status == "blown"
            if len(pid) < 10:
                return jsonify({"error": "plan_id fehlt"}), 400
            if mpl is None:
                return jsonify({"error": "master_pl fehlt oder ist keine Zahl"}), 400
            if daten.get("slave_pl") not in (None, "") and spl is None:
                return jsonify({"error": "slave_pl ist keine Zahl"}), 400
            try:
                # Tempo (02.10.2026, Finn: „dauert 5 Sekunden, bis es eingebucht ist"): vorher 9–12 Supabase-Anfragen
                # NACHEINANDER. Jetzt in vier Wellen — was voneinander unabhängig ist, läuft gleichzeitig. Reihenfolge und
                # Regeln wie bisher: Konto vor dem Plan-Update auflösen, Plan mit optimistischer Sperre, Buchung idempotent.
                # _wd_personen bleibt im Request-Thread (liest g über _admin_nur_uid), die Pool-Threads fassen g nie an.
                pool = concurrent.futures.ThreadPoolExecutor(max_workers=6)
                try:
                    plan_sel = {"select": "id,route,status,user_id,master_account_id,master_name,mt5_baseline,"
                                          "updated_at,ended_at,completed_at", "id": f"eq.{pid}", "limit": "1"}
                    # Welle 1: nur die plan_id nötig
                    f_plan = pool.submit(sb_select, "trade_plans", plan_sel)
                    f_alt = pool.submit(sb_select, "transactions", {"select": "id,amount", "kind": "eq.wd_hedge", "auto_generated": "is.true",
                                                                   "notes": f"like.{_wd_hedge_schluessel(pid)}*"})
                    f_archiv = pool.submit(_acc_plan_archiviert) if spl is not None else None
                    disp, _excl = _wd_personen()
                    uid = konto = person = None
                    konto_quelle = login_quelle = None
                    f_kk = None
                    rows = f_plan.result()
                    for _versuch in range(3):
                        if _versuch:
                            rows = sb_select("trade_plans", plan_sel)
                        plan = rows[0] if rows else None
                        jetzt = datetime.now(timezone.utc)
                        jetzt_iso = jetzt.isoformat().replace("+00:00", "Z")
                        upd, fehler = _wd_erledigt_upd(plan, mpl, spl, jetzt_iso, _cme_handelstag())
                        if fehler:
                            return jsonify({"error": fehler[1], "plan_id": pid}), fehler[0]
                        if blown:
                            upd["blown"] = True
                        if daten.get("pl_quelle") == "hand":
                            upd["pl_quelle"] = "hand"   # Hand-Betrag im Erledigt-Popup (08.10.2026, Fall ea91e359: −600 ohne Herkunft)
                        if uid is None:
                            # Welle 2: was den Plan braucht — Good-Day-Konto, Konten der ID, Hedge-Login
                            if plan.get("master_account_id"):
                                f_kk = pool.submit(sb_select, "accounts", {"select": "id,name,firm,account_type,goal_done_offset,goal_manual_last,goal_target",
                                                                           "id": f"eq.{plan.get('master_account_id')}", "limit": "1"})
                            uid = str(plan.get("user_id") or "")
                            if not uid and plan.get("master_account_id"):
                                macc = sb_select("accounts", {"select": "user_id", "id": f"eq.{plan.get('master_account_id')}", "limit": "1"})
                                uid = str((macc[0] if macc else {}).get("user_id") or "")
                            person = disp.get(uid, uid[:8])
                            if spl is not None and str(plan.get("route") or "") == "tvv2":   # Echo/Duplikum: nur slave_pl am Plan
                                h = ((plan.get("mt5_baseline") or {}).get("hedge") or {}) if isinstance(plan.get("mt5_baseline"), dict) else {}
                                login = str(h.get("hedge_login") or "").strip()
                                f_konten = pool.submit(sb_select, "accounts", {"select": "id,user_id,name,firm,account_type,external_id,created_at,"
                                                                                         "meta_api_account_id,meta_api_login",
                                                                               "user_id": f"eq.{uid}"}) if uid else None
                                if not login and h.get("pc"):
                                    ml = sb_select("mt5_live", {"select": "hedge_login,updated_at", "pc_name": f"eq.{h.get('pc')}",
                                                                "hedge_login": "neq.", "order": "updated_at.desc", "limit": "1"})
                                    login = str((ml[0] if ml else {}).get("hedge_login") or "").strip()
                                konten = f_konten.result() if f_konten else []
                                konto, konto_quelle = _wd_hedge_konto(konten, login or WD_HEDGE_LOGIN, f_archiv.result())
                                login_quelle = login or f"{WD_HEDGE_LOGIN} (Standard)"
                        # Welle 3: der Plan selbst
                        filt = {"id": f"eq.{pid}", "route": f"in.({','.join(WD_ERLEDIGT_ROUTEN)})", "status": "in.(open,review,completed)"}
                        if plan.get("updated_at"):
                            filt["updated_at"] = f"eq.{plan['updated_at']}"
                        z = sb_update("trade_plans", filt, upd)
                        if z:
                            break
                    else:
                        return jsonify({"error": "Plan wurde gleichzeitig geändert — bitte erneut versuchen", "plan_id": pid}), 409

                    # Welle 4 (gleichzeitig): Kontotyp, Buchung, Good Day — jede für sich, Fehler stoppen das Abhaken nicht

                    def _konto_typ():
                        # Kontotyp zum Zeitpunkt des Trades festhalten (25.09.2026) — ein Winning Day ist immer 'winning_days'; nur wenn
                        # leer, und still, falls die Spalte noch fehlt. Echo/Topstep (30.09.2026) sind keine Winning Days.
                        try:
                            sb_update("trade_plans", {"id": f"eq.{pid}", "konto_typ": "is.null"}, {"konto_typ": "winning_days"})
                        except Exception:
                            pass

                    def _buchen():
                        # Buchung (idempotent über den notes-Schlüssel)
                        if str(plan.get("route") or "") in WD_FUSION_AM_PLAN:
                            return None, None   # Fusion-P&L steht als slave_pl am Plan, Finanzen zählt ihn von dort
                        try:
                            alt = f_alt.result()
                            if spl is None:
                                for t in alt:
                                    _sb_anfrage("DELETE", f"{SUPABASE_URL}/rest/v1/transactions", params={"id": f"eq.{t['id']}"},
                                                    headers=_sb_headers(), timeout=12).raise_for_status()
                                return None, None
                            zeile = _wd_hedge_buchung(pid, uid, konto, person, spl, jetzt.date().isoformat())
                            if alt:
                                r = sb_update("transactions", {"id": f"eq.{alt[0]['id']}"}, zeile)
                                for t in alt[1:]:   # Altlast: Doppelte weg, genau eine Buchung je Plan
                                    _sb_anfrage("DELETE", f"{SUPABASE_URL}/rest/v1/transactions", params={"id": f"eq.{t['id']}"},
                                                    headers=_sb_headers(), timeout=12).raise_for_status()
                            else:
                                r = sb_insert("transactions", zeile)
                            r0 = (r[0] if isinstance(r, list) and r else r) or {}
                            return {"id": r0.get("id"), "amount": zeile["amount"], "account_id": zeile["account_id"],
                                    "account_name": zeile["account_name"], "user_id": zeile["user_id"], "neu": not alt,
                                    "konto_quelle": konto_quelle, "hedge_login": login_quelle}, None
                        except Exception as e:
                            return None, f"Buchung fehlgeschlagen ({type(e).__name__}) — erneut 'erledigt' senden, der Plan bleibt completed"

                    def _good_day():
                        # Good Day (01.10.2026): Tradeify-WD mit Master-P&L über 250 $ → Plan winning_day = true und Winning Day +1 am
                        # Konto (einmal je Berlin-Tag). Fehler hier stoppen das Abhaken nicht — sie stehen in der Antwort.
                        if f_kk is None:
                            return None
                        try:
                            kr = f_kk.result()
                            kk = kr[0] if kr else None
                            if not _wd_good_day(kk, mpl):
                                return None
                            sb_update("trade_plans", {"id": f"eq.{pid}"}, {"winning_day": True})
                            k_upd = _wd_good_day_konto_upd(kk, _berlin_heute())
                            if k_upd:
                                sb_update("accounts", {"id": f"eq.{kk['id']}"}, k_upd)
                            return {"gezaehlt": bool(k_upd), "stand": (k_upd or {}).get("goal_done_offset", kk.get("goal_done_offset")),
                                    "ziel": (k_upd or {}).get("goal_target", kk.get("goal_target") or 5), "konto": kk.get("name")}
                        except Exception as e:
                            return {"fehler": f"Winning Day nicht gezählt ({type(e).__name__}) — im Account von Hand +1"}

                    def _archivieren():
                        # Archiv = user_settings key 'archive' des Plan-Besitzers ({konto_id: {archived, reason, at}}), lesen → ergänzen →
                        # upsert. Bestehende Einträge bleiben; ein schon archiviertes Konto wird nicht überschrieben.
                        aid = str(plan.get("master_account_id") or "")
                        if not aid or not uid:
                            return {"fehler": "Konto nicht archiviert (Plan ohne Master-Konto) — im Account von Hand archivieren"}
                        try:
                            z = sb_select("user_settings", {"select": "value", "user_id": f"eq.{uid}", "key": "eq.archive", "limit": "1"})
                            v = (z[0] if z else {}).get("value")
                            if isinstance(v, str):
                                v = json.loads(v)
                            arch = v if isinstance(v, dict) else {}
                            if not (isinstance(arch.get(aid), dict) and arch[aid].get("archived")):
                                arch[aid] = {"archived": True, "reason": "blown" if blown else "passed_pending", "at": jetzt_iso}
                                _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/user_settings", params={"on_conflict": "user_id,key"},
                                            json={"user_id": uid, "key": "archive", "value": arch, "updated_at": jetzt_iso},
                                            headers=_sb_headers("resolution=merge-duplicates,return=minimal"), timeout=12).raise_for_status()
                            # Echo-Konto: Terminal-Löschauftrag wie archiveAccount() im Frontend (07.09.2026) — still, falls keins verknüpft
                            try:
                                ml = sb_select("mt5_links", {"select": "mt5_login", "account_id": f"eq.{aid}", "limit": "1"})
                                if ml and ml[0].get("mt5_login"):
                                    _sb_anfrage("POST", f"{SUPABASE_URL}/rest/v1/echo_loesch_auftraege", params={"on_conflict": "mt5_login"},
                                                json={"mt5_login": str(ml[0]["mt5_login"]), "grund": "blown" if blown else "passed_pending",
                                                      "account_name": plan.get("master_name"), "angelegt_am": jetzt_iso,
                                                      "erledigt_am": None, "erledigt_info": None},
                                                headers=_sb_headers("resolution=merge-duplicates,return=minimal"), timeout=12).raise_for_status()
                            except Exception as e:
                                print(f"[erledigt] ⚠️ Echo-Löschauftrag {aid}: {type(e).__name__}: {e}", flush=True)
                            return {"archiviert": True, "konto_id": aid, "grund": konto_status}
                        except Exception as e:
                            return {"fehler": f"Konto nicht archiviert ({type(e).__name__}) — im Account von Hand archivieren"}

                    f_typ = pool.submit(_konto_typ) if str(plan.get("route") or "") == "tvv2" else None
                    f_buch = pool.submit(_buchen)
                    f_gd = pool.submit(_good_day)
                    f_arch = pool.submit(_archivieren) if konto_status != "none" else None
                    buchung, buchung_fehler = f_buch.result()
                    good_day = f_gd.result()
                    if f_typ:
                        f_typ.result()
                    archiv = f_arch.result() if f_arch else None
                finally:
                    pool.shutdown(wait=False)
                out = {"ok": True, "plan_id": pid, "status": "completed", "buchung": buchung}
                if archiv:
                    out["archiv"] = archiv
                if good_day:
                    out["good_day"] = good_day
                if buchung_fehler:
                    out["buchung_fehler"] = buchung_fehler
                return jsonify(out)
            except Exception as e:
                return jsonify({"error": f"Nicht erledigt ({type(e).__name__})"}), 502
        if daten.get("aktion") == "farm":
            aid = str(daten.get("account_id") or "")
            if len(aid) < 10:
                return jsonify({"error": "account_id fehlt"}), 400
            try:
                z = sb_update("accounts", {"id": f"eq.{aid}"}, {"wd_farm": bool(daten.get("wd_farm"))})
                return jsonify({"geaendert": bool(z)})
            except Exception as e:
                return jsonify({"error": f"Haken nicht gesetzt ({type(e).__name__})"}), 502
        pid = str(daten.get("id") or "")
        upd = {k: v for k, v in (daten.get("upd") or {}).items() if k in WD_PATCH_FELDER}
        if len(pid) < 10 or not upd:
            return jsonify({"error": "id/upd fehlt"}), 400
        if "master_contracts" in upd:
            kt, kf = wd_kontrakte_pruefen(upd["master_contracts"])
            if kf:
                return jsonify({"error": kf}), 400
            upd["master_contracts"] = kt
        # master_sl: nur null wird geschrieben (Winning Days ohne Master-SL, 25.09.2026) — ein Wert wird zu null
        sl_verworfen = False
        if "master_sl" in upd:
            upd, sl_verworfen = _wd_ohne_master_sl(upd)
        try:
            # V2-Plan (24.09.2026): Slave-Risiko/Multiplier gibt es ohne Hedge nicht — ein
            # Admin-Nachzug (Staffel) darf sie nicht wieder an einen V2-Plan schreiben.
            if "slave_risk" in upd or "multiplier" in upd:
                alt = sb_select("trade_plans", {"select": "route,hedge_eur", "id": f"eq.{pid}", "limit": "1"})
                # Farm-Plan mit Fusion-Hedge (26.09.2026): Multiplikator/Risiko Slave darf nachgezogen werden
                try: alt_hedge = bool(alt) and float(alt[0].get("hedge_eur") or 0) > 0
                except (TypeError, ValueError): alt_hedge = False
                try: alt_hedge = alt_hedge or float(upd.get("hedge_eur") or 0) > 0
                except (TypeError, ValueError): pass
                if alt and (alt[0].get("route") or "") in WD_V2_ROUTEN and not alt_hedge:
                    upd.pop("slave_risk", None); upd.pop("multiplier", None)
                    if not upd:
                        return jsonify({"geaendert": False, "plan": None, "hinweis": "V2-Plan ohne Slave — nichts zu ändern"})
            z = sb_update("trade_plans", {"id": f"eq.{pid}", "status": "eq.planned", "start_um_gestartet_at": "is.null"}, upd)
            out = {"geaendert": bool(z), "plan": z[0] if z else None}
            if sl_verworfen:
                out["hinweis"] = "master_sl verworfen — Winning Days haben keinen Master-SL (gespeichert: null)"
            return jsonify(out)
        except Exception as e:
            return jsonify({"error": f"Nicht geändert ({type(e).__name__})"}), 502

    pid = str(daten.get("id") or request.args.get("id") or "").strip()
    if len(pid) < 10:
        return jsonify({"error": "id fehlt"}), 400
    try:
        del_params = {"id": f"eq.{pid}", "status": "eq.planned", "start_um_gestartet_at": "is.null"}
        if sicht_fest is not None:   # Admin-Gruppen (08.10.2026): Guard in derselben Anfrage — nur Pläne der eigenen Sicht
            del_params["user_id"] = admin_sicht_filter(sicht_fest)
        r = _sb_anfrage("DELETE", f"{SUPABASE_URL}/rest/v1/trade_plans", params=del_params,
                            headers=_sb_headers("return=representation"), timeout=12)
        r.raise_for_status()
        return jsonify({"geloescht": bool(r.json())})
    except Exception as e:
        return jsonify({"error": f"Nicht gelöscht ({type(e).__name__})"}), 502


